import { marked } from 'marked';

import {
  CHORD_SYMBOL_SOURCE,
  getLeadingSpaceLikeLength,
  hasChordProgressionText,
  isSpaceLikeCharacter,
  normalizeConfigFieldName,
  normalizeStrummingPatternValue,
  shouldAllowInvisibleWordSeparators,
  trimSpaceLikeEnd,
  trimSpaceLikeStart,
  trimSpaceLikeText,
} from '../../../editor/scripts/shared.ts';
import { parseFenceHeader } from '../domain/parser/fences.ts';
import {
  formatStructureStepLabel,
  parseStructureValue,
} from '../domain/structure.ts';
import { describeChordKey } from '../domain/music-theory.ts';

const OL_FENCE_BLOCK_RE = /^```ol:([^\r\n]*)[ \t]*\r?\n([\s\S]*?)^```[ \t]*$/gm;
const DIRECTIVE_TOKEN_RE = /(\{[^{}\r\n]+\})/g;
const CHORD_TOKEN_RE = /(\[[^\[\]\r\n]+\])/g;
const BAR_TOKEN_RE = /(\|\|:|\|:|:\|\||:\||\|)/g;
const REPEAT_TOKEN_RE = /\(([1-9]\d*x)\)/g;
const PLAIN_OL_TOKEN_RE =
  /(\{[^{}\r\n]+\}|\|\|:|\|:|:\|\||:\||\||\([1-9]\d*x\))/g;
const INLINE_OL_TOKEN_RE =
  /(\[[^\[\]\r\n]+\]|\{[^{}\r\n]+\}|\|\|:|\|:|:\|\||:\||\||\([1-9]\d*x\))/g;
const HAS_CHORD_TOKEN_RE = /\[[^\[\]\r\n]+\]/;
const BARE_CHORD_RE = new RegExp(`^${CHORD_SYMBOL_SOURCE}$`);
const CHORD_PLACEHOLDER_ATTRIBUTE = 'data-ol-chord-placeholder';
const FONT_COLOR_TAG_RE = /<\/font\s*>|<font\b[^>]*>/gi;
const FONT_COLOR_ATTRIBUTE_RE =
  /\bcolor\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/i;
const MARKDOWN_PROTOCOL_LINK_RE =
  /(!?\[[^\]\r\n]*\]\()([A-Za-z][A-Za-z0-9+.-]*:\/\/[^)\r\n]+)(\))/g;
const STANDALONE_PROTOCOL_URL_RE =
  /^(\s*)([A-Za-z][A-Za-z0-9+.-]*:\/\/\S[^\r\n]*)(\s*)$/;
const STRUMMING_DOWN_SYMBOLS = new Set(['d', 'D', 'v', 'V']);
const STRUMMING_UP_SYMBOLS = new Set(['u', 'U', '^']);
const STRUMMING_DEFAULT_SYMBOLS = new Set(['x', 'X', '1', '*', '+']);
const STRUMMING_REST_SYMBOLS = new Set(['-', '_', '.', '0']);
const DEFAULT_STRUMMING_PATTERN_TEXT = '---- | ---- | ---- | ----';
const PREVIEW_TAB_WIDTH = 4;
const OL_FENCE_HEADER_CONTENT_COLUMN = '```ol:'.length + 1;
const STRUMMING_PATTERN_DIRECTIVE_RE = /^\{p:(\s*)#([1-9]\d*)(\s*)\}$/;
const OPEN_LYRIC_PATTERN_TARGET_ID_PREFIX = 'ol-song-view-pattern';
let previewColorProbeElement = null;
const STRUMMING_TIME_SIGNATURES = new Map([
  ['4/4', { labelMode: 'quarter', beatGroups: [4, 4, 4, 4] }],
  ['2/2', { labelMode: 'quarter', beatGroups: [8, 8] }],
  ['2/4', { labelMode: 'quarter', beatGroups: [4, 4] }],
  ['3/4', { labelMode: 'quarter', beatGroups: [4, 4, 4] }],
  ['3/8', { labelMode: 'eighth', beatGroups: [2, 2, 2] }],
  ['6/8', { labelMode: 'eighth', beatGroups: [6, 6] }],
  ['9/8', { labelMode: 'eighth', beatGroups: [6, 6, 6] }],
  ['12/8', { labelMode: 'eighth', beatGroups: [6, 6, 6, 6] }],
]);

function escapeHtml(input) {
  return String(input ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function normalizeExternalLinkAttributes(element) {
  if (!(element instanceof HTMLAnchorElement)) {
    return;
  }

  const href = element.getAttribute('href')?.trim() || '';
  if (!href || href.startsWith('#')) {
    return;
  }

  element.setAttribute('target', '_blank');

  const relValues = new Set(
    (element.getAttribute('rel') || '')
      .split(/\s+/)
      .map((value) => value.trim())
      .filter(Boolean),
  );
  relValues.add('noopener');
  relValues.add('noreferrer');
  element.setAttribute('rel', Array.from(relValues).join(' '));
}

function sanitizeHtml(html) {
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');

  doc
    .querySelectorAll('script, style, iframe, object, embed, link, meta')
    .forEach((node) => {
      node.remove();
    });

  doc.querySelectorAll('*').forEach((element) => {
    Array.from(element.attributes).forEach((attribute) => {
      const name = attribute.name.toLowerCase();
      const value = attribute.value.toLowerCase().trim();

      if (name.startsWith('on')) {
        element.removeAttribute(attribute.name);
        return;
      }

      if (
        (name === 'href' || name === 'src') &&
        value.startsWith('javascript:')
      ) {
        element.removeAttribute(attribute.name);
      }
    });

    normalizeExternalLinkAttributes(element);
  });

  return doc.body.innerHTML;
}

function normalizeNewlines(value) {
  return String(value).replace(/\r\n?/g, '\n');
}

function encodeSpacesInProtocolUrl(value) {
  return String(value ?? '').replace(/ /g, '%20');
}

function normalizeMarkdownRenderableUrls(value) {
  const source = String(value ?? '');

  if (!source.includes(' ')) {
    return source;
  }

  const normalizedLinks = source.replace(
    MARKDOWN_PROTOCOL_LINK_RE,
    (_match, prefix, url, suffix) => {
      return `${prefix}${encodeSpacesInProtocolUrl(url)}${suffix}`;
    },
  );
  const standaloneUrlMatch = normalizedLinks.match(STANDALONE_PROTOCOL_URL_RE);

  if (!standaloneUrlMatch) {
    return normalizedLinks;
  }

  return `${standaloneUrlMatch[1]}${encodeSpacesInProtocolUrl(
    standaloneUrlMatch[2],
  )}${standaloneUrlMatch[3]}`;
}

function createPreviewTargetId(value) {
  const slug = String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  return slug ? `ol-preview-target-${slug}` : '';
}

function getLineNumberAtOffset(text, offset) {
  if (offset <= 0) {
    return 1;
  }

  return text.slice(0, offset).split('\n').length;
}

function getEditorDataAttributes(lineNumber, column = 1) {
  if (!lineNumber) {
    return '';
  }

  return ` data-editor-line="${escapeHtml(lineNumber)}" data-editor-column="${escapeHtml(column || 1)}"`;
}

function getFenceHeaderEditorDataAttributes(startLineNumber) {
  if (!startLineNumber) {
    return '';
  }

  return getEditorDataAttributes(
    startLineNumber,
    OL_FENCE_HEADER_CONTENT_COLUMN,
  );
}

function resolveAllowZwspSeparators(value, allowZwspSeparators) {
  return typeof allowZwspSeparators === 'boolean'
    ? allowZwspSeparators
    : shouldAllowInvisibleWordSeparators(value);
}

function isCommentLine(line, allowZwspSeparators = true) {
  return trimSpaceLikeStart(line, allowZwspSeparators).startsWith('//');
}

function getFirstContentColumn(line, allowZwspSeparators = true) {
  const source = String(line ?? '');
  let firstContentIndex = 0;

  while (
    firstContentIndex < source.length &&
    isSpaceLikeCharacter(source[firstContentIndex], allowZwspSeparators)
  ) {
    firstContentIndex += 1;
  }

  return firstContentIndex >= source.length ? 1 : firstContentIndex + 1;
}

function createPreviewLineEntries(
  body,
  sourceLocation = null,
  allowZwspSeparators = shouldAllowInvisibleWordSeparators(body),
) {
  const normalizedBody = String(body ?? '').replace(/\r\n?/g, '\n');
  const trimmedBody = normalizedBody.endsWith('\n')
    ? normalizedBody.slice(0, -1)
    : normalizedBody;

  if (!trimmedBody.length) {
    return [];
  }

  const startLineNumber = sourceLocation?.startLineNumber || 0;

  return trimmedBody.split('\n').flatMap((line, index) => {
    if (isCommentLine(line, allowZwspSeparators)) {
      return [];
    }

    return [
      {
        text: line,
        lineNumber: startLineNumber ? startLineNumber + 1 + index : null,
        column: getFirstContentColumn(line, allowZwspSeparators),
      },
    ];
  });
}

function getPreviewSourceLocation(body, startLineNumber) {
  const bodyLines = normalizeNewlines(body).split('\n');
  const allowZwspSeparators = shouldAllowInvisibleWordSeparators(body);

  for (let index = 0; index < bodyLines.length; index += 1) {
    const line = bodyLines[index];
    if (
      !trimSpaceLikeText(line, allowZwspSeparators) ||
      isCommentLine(line, allowZwspSeparators)
    ) {
      continue;
    }

    return {
      startLineNumber,
      bodyLineNumber: startLineNumber + 1 + index,
      bodyColumn: getFirstContentColumn(line, allowZwspSeparators),
    };
  }

  return {
    startLineNumber,
    bodyLineNumber: startLineNumber + 1,
    bodyColumn: 1,
  };
}

function renderStructureDeclarePartAction(insertIndex = 0) {
  return [
    '<div class="ol-preview-config__structure-action">',
    `<button class="ol-preview-config__part-action" type="button" data-preview-action="toggle-declare-part-menu" data-structure-insert-index="${escapeHtml(insertIndex)}" aria-haspopup="menu" aria-expanded="false" aria-label="Add part to Structure" title="Add part to Structure">+</button>`,
    '</div>',
  ].join('');
}

function renderStructureInsertAction(insertIndex, previousStep, nextStep) {
  const previousLabel =
    previousStep.partName || previousStep.partText || 'part';
  const nextLabel = nextStep.partName || nextStep.partText || 'part';
  const actionLabel = `Insert part between ${previousLabel} and ${nextLabel}`;

  return `<button class="ol-preview-structure-arrow ol-preview-structure-arrow-button" type="button" data-preview-action="toggle-declare-part-menu" data-structure-insert-index="${escapeHtml(insertIndex)}" aria-haspopup="menu" aria-expanded="false" aria-label="${escapeHtml(actionLabel)}" title="${escapeHtml(actionLabel)}">&rarr;</button>`;
}

function renderStructureRepeatControls(step, stepIndex) {
  const repeatCount = step.repeatText
    ? Number.parseInt(step.repeatText, 10)
    : 1;
  const partName = step.partName || step.partText || 'part';
  const decreaseLabel =
    repeatCount > 1
      ? `Decrease repeat for ${partName}`
      : `Remove ${partName} from Structure`;

  return [
    '<span class="ol-preview-structure-repeat-controls">',
    `<button class="ol-preview-structure-repeat-button" type="button" data-preview-action="decrease-structure-repeat" data-structure-step-index="${escapeHtml(stepIndex)}" aria-label="${escapeHtml(decreaseLabel)}" title="${escapeHtml(decreaseLabel)}">-</button>`,
    `<button class="ol-preview-structure-repeat-button" type="button" data-preview-action="increase-structure-repeat" data-structure-step-index="${escapeHtml(stepIndex)}" aria-label="Increase repeat for ${escapeHtml(partName)}" title="Increase repeat for ${escapeHtml(partName)}">+</button>`,
    '</span>',
  ].join('');
}

function renderStructureValue(values) {
  if (!Array.isArray(values) || values.length !== 1) {
    return (values || [])
      .map(
        (value) =>
          `<span${getEditorDataAttributes(
            value.lineEntry?.lineNumber,
            value.valueColumn || value.lineEntry?.column,
          )}>${renderInlineOlText(value.text)}</span>`,
      )
      .join('<br>');
  }

  const [value] = values;
  const parsedStructure = parseStructureValue(value.text);
  if (parsedStructure.error) {
    return `<span${getEditorDataAttributes(
      value.lineEntry?.lineNumber,
      value.valueColumn || value.lineEntry?.column,
    )}>${renderInlineOlText(value.text)}</span>`;
  }

  if (!parsedStructure.steps.length) {
    return `<div class="ol-preview-config__structure-value ol-preview-config__structure-value--empty"${getEditorDataAttributes(
      value.lineEntry?.lineNumber,
      value.valueColumn || value.lineEntry?.column,
    )}>${renderStructureDeclarePartAction(0)}</div>`;
  }

  const declarePartActionHtml = renderStructureDeclarePartAction(
    parsedStructure.steps.length,
  );

  const stepHtml = parsedStructure.steps
    .map((step, index) => {
      const targetId = step.parsedHeader
        ? createPreviewTargetId(step.partName)
        : '';
      const editorLine = value.lineEntry?.lineNumber;
      const editorColumn =
        (value.valueColumn || value.lineEntry?.column || 1) + step.startOffset;
      const label = formatStructureStepLabel(step);
      const stepLabelHtml = targetId
        ? `<a class="ol-preview-structure-step" href="#${escapeHtml(targetId)}" data-preview-target-id="${escapeHtml(targetId)}"${getEditorDataAttributes(
            editorLine,
            editorColumn,
          )}${
            step.header ? ` data-ol-header="${escapeHtml(step.header)}"` : ''
          }>${renderInlineOlText(label)}</a>`
        : `<span class="ol-preview-structure-step"${getEditorDataAttributes(
            editorLine,
            editorColumn,
          )}${
            step.header ? ` data-ol-header="${escapeHtml(step.header)}"` : ''
          }>${renderInlineOlText(label)}</span>`;

      return `<span class="ol-preview-structure-link">${`<span class="ol-preview-structure-step-shell">${stepLabelHtml}${renderStructureRepeatControls(
        step,
        index,
      )}</span>`}${
        index < parsedStructure.steps.length - 1
          ? renderStructureInsertAction(
              index + 1,
              step,
              parsedStructure.steps[index + 1],
            )
          : ''
      }</span>`;
    })
    .join('');

  return `<div class="ol-preview-config__structure-value"><div class="ol-preview-structure-line">${stepHtml}</div>${declarePartActionHtml}</div>`;
}

function renderOlSpecialToken(token, viewOptions = {}) {
  if (token.startsWith('{')) {
    return (
      renderPatternDirectiveToken(token, viewOptions) ||
      `<span class="ol-preview-directive">${escapeHtml(token)}</span>`
    );
  }

  if (token.startsWith('(')) {
    return `<span class="ol-preview-repeat">${escapeHtml(token.replace(/^\((.*)\)$/, '$1'))}</span>`;
  }

  return renderPreviewBarToken(token);
}

function renderPreviewBarToken(token, options = {}) {
  const classNames = ['ol-preview-bar'];

  if (options.hidden) {
    classNames.push('ol-preview-bar--hidden');
  }

  return `<span class="${classNames.join(' ')}"${options.hidden ? ' aria-hidden="true"' : ''}>${escapeHtml(token)}</span>`;
}

function normalizePreviewViewOptions(viewOptions) {
  const normalizedViewOptions =
    viewOptions && typeof viewOptions === 'object' ? viewOptions : {};
  const hideBracketedKeys = Boolean(normalizedViewOptions.hideBracketedKeys);

  return {
    hideBracketedKeys,
    hideLeadingBars: Boolean(
      normalizedViewOptions.hideLeadingBars || hideBracketedKeys,
    ),
    patternPreviewContext: normalizedViewOptions.patternPreviewContext || null,
    patternPreviewTargetIdPrefix: String(
      normalizedViewOptions.patternPreviewTargetIdPrefix ?? '',
    ).trim(),
  };
}

function parseConfigPreviewValueMap(configBody, allowZwspSeparators = true) {
  const configValueMap = new Map();
  let activeFieldName = '';

  for (const line of normalizeNewlines(configBody).split('\n')) {
    if (!trimSpaceLikeText(line, allowZwspSeparators)) {
      continue;
    }

    const fieldMatch = line.match(/^\s*-\s*([^:]+):\s*(.*)$/);
    if (fieldMatch) {
      activeFieldName = normalizeConfigFieldName(fieldMatch[1]);
      configValueMap.set(activeFieldName, [
        trimSpaceLikeText(fieldMatch[2], allowZwspSeparators),
      ]);
      continue;
    }

    if (!activeFieldName || !/^[ \t]+/.test(line)) {
      activeFieldName = '';
      continue;
    }

    const activeValues = configValueMap.get(activeFieldName);
    if (!Array.isArray(activeValues)) {
      activeFieldName = '';
      continue;
    }

    activeValues.push(trimSpaceLikeText(line, allowZwspSeparators));
  }

  return configValueMap;
}

function getConfigPreviewValueLines(configValueMap, fieldName) {
  const values = configValueMap.get(normalizeConfigFieldName(fieldName));

  if (!Array.isArray(values)) {
    return [];
  }

  return values.map((value) => trimSpaceLikeText(value)).filter(Boolean);
}

function getConfigPreviewValue(configValueMap, fieldName) {
  return getConfigPreviewValueLines(configValueMap, fieldName).join(' ');
}

function getConfigPreviewFieldLineEntries(configBody, fieldName, options = {}) {
  const normalizedFieldName = normalizeConfigFieldName(fieldName);
  const allowZwspSeparators = resolveAllowZwspSeparators(
    configBody,
    options.allowZwspSeparators,
  );

  if (!normalizedFieldName) {
    return [];
  }

  const normalizedBody = normalizeNewlines(configBody);
  const trimmedBody = normalizedBody.endsWith('\n')
    ? normalizedBody.slice(0, -1)
    : normalizedBody;

  if (!trimmedBody.length) {
    return [];
  }

  const preserveComments = Boolean(options.preserveComments);
  const startLineNumber = options.sourceLocation?.startLineNumber || 0;
  const valueEntries = [];
  let activeFieldName = '';

  trimmedBody.split('\n').forEach((line, index) => {
    if (!trimSpaceLikeText(line, allowZwspSeparators)) {
      return;
    }

    const fieldMatch = line.match(/^\s*-\s*([^:]+):\s*(.*)$/);
    if (fieldMatch) {
      activeFieldName = normalizeConfigFieldName(fieldMatch[1]);

      if (activeFieldName !== normalizedFieldName) {
        return;
      }

      const separatorOffset = line.indexOf(':');
      const valueOffset =
        separatorOffset === -1 ? line.length : separatorOffset + 1;
      const valueIndentLength = getLeadingSpaceLikeLength(
        line.slice(valueOffset),
        allowZwspSeparators,
      );
      const lineNumber = startLineNumber ? startLineNumber + 1 + index : null;

      valueEntries.push({
        text: fieldMatch[2],
        lineEntry: {
          text: line,
          lineNumber,
          column: getFirstContentColumn(line, allowZwspSeparators),
        },
        valueColumn: valueOffset + valueIndentLength + 1,
        sourceIndex: valueEntries.length,
      });
      return;
    }

    if (!activeFieldName || !/^[ \t]+/.test(line)) {
      activeFieldName = '';
      return;
    }

    if (activeFieldName !== normalizedFieldName) {
      return;
    }

    if (isCommentLine(line, allowZwspSeparators) && !preserveComments) {
      return;
    }

    const lineNumber = startLineNumber ? startLineNumber + 1 + index : null;

    valueEntries.push({
      text: trimSpaceLikeText(line, allowZwspSeparators),
      lineEntry: {
        text: line,
        lineNumber,
        column: getFirstContentColumn(line, allowZwspSeparators),
      },
      valueColumn: getFirstContentColumn(line, allowZwspSeparators),
      sourceIndex: valueEntries.length,
    });
  });

  return valueEntries;
}

function createStrummingPatternPreviewContextFromConfigBody(
  configBody,
  options = {},
) {
  const allowZwspSeparators = resolveAllowZwspSeparators(
    configBody,
    options.allowZwspSeparators,
  );

  if (!trimSpaceLikeText(configBody, allowZwspSeparators)) {
    return null;
  }

  const configValueMap = parseConfigPreviewValueMap(
    configBody,
    allowZwspSeparators,
  );
  const patternLines = getConfigPreviewFieldLineEntries(
    configBody,
    'Strumming Patterns',
    {
      allowZwspSeparators,
      preserveComments: true,
      sourceLocation: options.sourceLocation,
    },
  );
  const patterns = parseStrummingPatterns(patternLines, {
    allowZwspSeparators,
  }).map((pattern, zeroBasedIndex) => ({
    ...pattern,
    allowZwspSeparators,
    referenceIndex: zeroBasedIndex + 1,
  }));

  if (!patterns.length) {
    return null;
  }

  const keyTextOverride = trimSpaceLikeText(
    options.keyTextOverride,
    allowZwspSeparators,
  );

  return {
    allowZwspSeparators,
    keyText: keyTextOverride || getConfigPreviewValue(configValueMap, 'Key'),
    patterns,
    patternsByIndex: new Map(
      patterns.map((pattern) => [pattern.referenceIndex, pattern]),
    ),
    tempoText: getConfigPreviewValue(configValueMap, 'Tempo'),
    timeSignatureText: getConfigPreviewValue(configValueMap, 'Time') || '4/4',
  };
}

function createStrummingPatternPreviewContextFromMarkdown(
  markdown,
  options = {},
) {
  const normalizedMarkdown = normalizeNewlines(markdown);

  OL_FENCE_BLOCK_RE.lastIndex = 0;

  for (const match of normalizedMarkdown.matchAll(OL_FENCE_BLOCK_RE)) {
    const info = String(match[1] || '').trim();

    if (parseFenceHeader(info)?.kind !== 'config') {
      continue;
    }

    const matchOffset = match.index || 0;

    return createStrummingPatternPreviewContextFromConfigBody(match[2] || '', {
      ...options,
      sourceLocation: {
        startLineNumber: getLineNumberAtOffset(normalizedMarkdown, matchOffset),
      },
    });
  }

  return null;
}

function renderPatternDirectiveToken(token, viewOptions = {}) {
  const directiveMatch = String(token ?? '').match(
    STRUMMING_PATTERN_DIRECTIVE_RE,
  );

  if (!directiveMatch) {
    return '';
  }

  const [, leadingWhitespace, patternIndexText, trailingWhitespace] =
    directiveMatch;
  const normalizedViewOptions = normalizePreviewViewOptions(viewOptions);
  const patternPreviewContext = normalizedViewOptions.patternPreviewContext;
  const patternIndex = Number.parseInt(patternIndexText, 10);
  const pattern = patternPreviewContext?.patternsByIndex?.get(patternIndex);

  if (!pattern) {
    return '';
  }

  const patternLabel =
    String(pattern.label ?? '').trim() || `Pattern ${patternIndex}`;
  const targetId = createPatternPreviewTargetId(
    normalizedViewOptions.patternPreviewTargetIdPrefix,
    patternIndex,
  );
  const targetAttribute = targetId
    ? ` data-preview-target-id="${escapeHtml(targetId)}"`
    : '';
  const interactionLabel = targetId
    ? `Jump to ${patternLabel} preview`
    : `Preview ${patternLabel}`;

  return [
    '<span class="ol-preview-directive">',
    '{p:',
    escapeHtml(leadingWhitespace),
    `<button class="ol-preview-pattern-reference" type="button" data-pattern-reference-index="${escapeHtml(patternIndexText)}" data-pattern-reference-label="${escapeHtml(patternLabel)}" data-pattern-reference-source="${escapeHtml(pattern.pattern)}"${targetAttribute}${getStrummingPatternPreviewDataAttributes(
      {
        keyText: patternPreviewContext.keyText,
        tempoText: patternPreviewContext.tempoText,
        timeSignatureText: patternPreviewContext.timeSignatureText,
      },
    )} aria-label="${escapeHtml(interactionLabel)}" title="${escapeHtml(interactionLabel)}">#${escapeHtml(patternIndexText)}</button>`,
    escapeHtml(trailingWhitespace),
    '}',
    '</span>',
  ].join('');
}

function createPatternPreviewTargetId(prefix, patternIndex) {
  const normalizedPrefix = String(prefix ?? '').trim();

  if (
    !normalizedPrefix ||
    !Number.isInteger(patternIndex) ||
    patternIndex < 1
  ) {
    return '';
  }

  return `${normalizedPrefix}-${patternIndex}`;
}

function createFontColorState() {
  return {
    stack: [],
  };
}

function getPreviewColorProbeElement() {
  if (typeof document === 'undefined') {
    return null;
  }

  if (!previewColorProbeElement) {
    previewColorProbeElement = document.createElement('span');
  }

  return previewColorProbeElement;
}

function normalizePreviewTextColor(value) {
  const trimmedValue = String(value ?? '').trim();

  if (!trimmedValue) {
    return '';
  }

  const probeElement = getPreviewColorProbeElement();
  if (!probeElement) {
    return trimmedValue;
  }

  probeElement.style.color = '';
  probeElement.style.color = trimmedValue;
  return probeElement.style.color ? trimmedValue : '';
}

function getFontColorTagValue(tagText) {
  const colorMatch = String(tagText ?? '').match(FONT_COLOR_ATTRIBUTE_RE);
  const rawColorValue =
    colorMatch?.[1] || colorMatch?.[2] || colorMatch?.[3] || '';

  return normalizePreviewTextColor(rawColorValue);
}

function getInlineTextSegmentsWithFontColors(value, state) {
  const source = String(value ?? '');
  const fontColorState = state || createFontColorState();
  const segments = [];
  let currentText = '';
  let lastIndex = 0;

  const pushCurrentText = () => {
    if (!currentText) {
      return;
    }

    segments.push({
      color: fontColorState.stack[fontColorState.stack.length - 1]?.color || '',
      text: currentText,
    });
    currentText = '';
  };

  FONT_COLOR_TAG_RE.lastIndex = 0;

  for (const match of source.matchAll(FONT_COLOR_TAG_RE)) {
    const matchIndex = match.index ?? 0;
    const tagText = match[0] || '';

    currentText += source.slice(lastIndex, matchIndex);

    if (/^<font\b/i.test(tagText)) {
      const color = getFontColorTagValue(tagText);

      if (color) {
        pushCurrentText();
        fontColorState.stack.push({
          color,
        });
      } else {
        currentText += tagText;
      }
    } else if (/^<\/font/i.test(tagText) && fontColorState.stack.length) {
      pushCurrentText();
      fontColorState.stack.pop();
    } else {
      currentText += tagText;
    }

    lastIndex = matchIndex + tagText.length;
  }

  currentText += source.slice(lastIndex);
  pushCurrentText();

  return segments;
}

function buildLineSourceFromTextSegments(segments) {
  return (segments || [])
    .map((segment) => {
      if (!segment?.text) {
        return '';
      }

      if (!segment.color) {
        return segment.text;
      }

      return `<span style="color: ${escapeHtml(segment.color)}">${segment.text}</span>`;
    })
    .join('');
}

function renderTextSegments(segments, renderText) {
  return (segments || [])
    .map((segment) => {
      if (!segment?.text) {
        return '';
      }

      const renderedSegment = renderText(segment.text);
      if (!segment.color) {
        return renderedSegment;
      }

      return `<span style="color: ${escapeHtml(segment.color)}">${renderedSegment}</span>`;
    })
    .join('');
}

function preserveTextNodeWhitespace(value) {
  return String(value ?? '')
    .replace(/\t/g, '\u00A0'.repeat(PREVIEW_TAB_WIDTH))
    .replace(/(^|[\r\n])( +)/g, (_match, prefix, spaces) => {
      return `${prefix}${'\u00A0'.repeat(spaces.length)}`;
    })
    .replace(/ {2,}/g, (match) => '\u00A0'.repeat(match.length))
    .replace(/( +)(?=$|[\r\n])/g, (match) => '\u00A0'.repeat(match.length));
}

function preserveRenderedWhitespace(html) {
  const source = String(html ?? '');

  if (!source || typeof document === 'undefined') {
    return source;
  }

  const container = document.createElement('div');
  container.innerHTML = source;

  const textNodes = [];
  const collectTextNodes = (node) => {
    node.childNodes.forEach((childNode) => {
      if (childNode.nodeType === Node.TEXT_NODE) {
        textNodes.push(childNode);
        return;
      }

      if (childNode.nodeType === Node.ELEMENT_NODE) {
        collectTextNodes(childNode);
      }
    });
  };

  collectTextNodes(container);

  textNodes.forEach((textNode) => {
    const preservedText = preserveTextNodeWhitespace(textNode.nodeValue || '');

    if (preservedText !== textNode.nodeValue) {
      textNode.nodeValue = preservedText;
    }
  });

  return container.innerHTML;
}

function renderInlineMarkdownText(value) {
  const source = normalizeMarkdownRenderableUrls(value);

  if (!source) {
    return '';
  }

  if (!source.trim()) {
    return escapeHtml(source);
  }

  return sanitizeHtml(
    marked.parseInline(source, {
      gfm: true,
      breaks: true,
    }),
  );
}

function renderHtmlFragmentPlainText(html) {
  const source = String(html ?? '');

  if (!source) {
    return '';
  }

  if (typeof DOMParser === 'undefined') {
    return source.replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '');
  }

  const parser = new DOMParser();
  const doc = parser.parseFromString(
    source.replace(/<br\s*\/?>/gi, '\n'),
    'text/html',
  );

  return doc.body.textContent || '';
}

function renderInlineTextPlainText(value) {
  return getInlineTextSegmentsWithFontColors(value)
    .map((segment) => {
      return renderHtmlFragmentPlainText(
        renderInlineMarkdownText(segment.text),
      );
    })
    .join('')
    .replace(/\u00A0/g, ' ');
}

function renderPlainOlText(value, viewOptions = {}) {
  const source = String(value ?? '');
  let html = '';
  let lastIndex = 0;

  for (const match of source.matchAll(PLAIN_OL_TOKEN_RE)) {
    const matchIndex = match.index ?? 0;
    const token = match[0];

    html += renderInlineMarkdownText(source.slice(lastIndex, matchIndex));

    html += renderOlSpecialToken(token, viewOptions);

    lastIndex = matchIndex + token.length;
  }

  html += renderInlineMarkdownText(source.slice(lastIndex));
  return html;
}

function getChordKey(chordToken) {
  return String(chordToken ?? '')
    .trim()
    .replace(/^\[/, '')
    .replace(/\]$/, '');
}

function renderChordToken(chordToken, options = {}) {
  const chordKey = getChordKey(chordToken);
  const escapedChordKey = escapeHtml(chordKey);
  const chordTitle = escapeHtml(describeChordKey(chordKey));
  const preserveBracketSpacing = Boolean(options.preserveBracketSpacing);
  const hidden = Boolean(options.hidden);
  const classNames = ['ol-preview-chord'];

  if (preserveBracketSpacing) {
    classNames.push('ol-preview-chord--with-brackets');
  }

  if (hidden) {
    classNames.push('ol-preview-chord--hidden');
  }

  if (preserveBracketSpacing) {
    return `<button class="${classNames.join(' ')}" type="button" data-chord-key="${escapedChordKey}" data-chord-title="${chordTitle}" aria-label="Show ${chordTitle}"${hidden ? ' aria-hidden="true"' : ''}><span class="ol-preview-chord__bracket" aria-hidden="true">[</span><span class="ol-preview-chord__label">${escapedChordKey}</span><span class="ol-preview-chord__bracket" aria-hidden="true">]</span></button>`;
  }

  return `<button class="${classNames.join(' ')}" type="button" data-chord-key="${escapedChordKey}" data-chord-title="${chordTitle}" aria-label="Show ${chordTitle}"${hidden ? ' aria-hidden="true"' : ''}>${escapedChordKey}</button>`;
}

function renderChordedLyricChordToken(chordToken, viewOptions = {}) {
  const normalizedChordToken = String(chordToken ?? '');
  const { hideLeadingBars } = normalizePreviewViewOptions(viewOptions);

  if (!normalizedChordToken) {
    return '';
  }

  if (normalizedChordToken.startsWith('|')) {
    if (hideLeadingBars) {
      return `${renderPreviewBarToken('|', { hidden: true })}${renderInlineOlText(normalizedChordToken.slice(1), viewOptions)}`;
    }

    return renderInlineOlText(normalizedChordToken, viewOptions);
  }

  return `${renderPreviewBarToken('|', { hidden: true })}${renderInlineOlText(normalizedChordToken, viewOptions)}`;
}

function shouldHideInlineBarToken(matches, matchIndex, source) {
  const currentMatch = matches[matchIndex];
  const nextMatch = matches[matchIndex + 1];

  if (!currentMatch || currentMatch[0] !== '|' || !nextMatch) {
    return false;
  }

  const nextToken = nextMatch[0] || '';
  const isChordToken = CHORD_TOKEN_RE.test(nextToken);
  CHORD_TOKEN_RE.lastIndex = 0;

  if (!isChordToken) {
    return false;
  }

  const nextIndex = nextMatch.index ?? 0;
  const currentIndex = currentMatch.index ?? 0;
  const betweenText = source.slice(currentIndex + 1, nextIndex);

  return !trimSpaceLikeText(betweenText);
}

function renderInlineOlText(value, viewOptions = {}) {
  const source = String(value ?? '');
  const { hideBracketedKeys } = normalizePreviewViewOptions(viewOptions);
  const matches = Array.from(source.matchAll(INLINE_OL_TOKEN_RE));
  let html = '';
  let lastIndex = 0;

  matches.forEach((match, index) => {
    const matchIndex = match.index ?? 0;
    const token = match[0];

    html += renderPlainOlText(source.slice(lastIndex, matchIndex), viewOptions);

    if (CHORD_TOKEN_RE.test(token)) {
      html += renderChordToken(token, {
        preserveBracketSpacing: true,
        hidden: hideBracketedKeys,
      });
      CHORD_TOKEN_RE.lastIndex = 0;
    } else if (
      hideBracketedKeys &&
      shouldHideInlineBarToken(matches, index, source)
    ) {
      html += renderPreviewBarToken(token, { hidden: true });
    } else {
      html += renderOlSpecialToken(token, viewOptions);
    }

    lastIndex = matchIndex + token.length;
  });

  html += renderPlainOlText(source.slice(lastIndex), viewOptions);
  return html;
}

function renderChordProgressionSegment(value) {
  return String(value ?? '')
    .split(/([\s\u200B]+)/u)
    .map((segment) => {
      if (!segment) {
        return '';
      }

      if (!trimSpaceLikeText(segment)) {
        return escapeHtml(segment);
      }

      return BARE_CHORD_RE.test(segment)
        ? renderChordToken(segment)
        : escapeHtml(segment);
    })
    .join('');
}

function renderChordProgressionText(value, viewOptions = {}) {
  const source = String(value ?? '');
  let html = '';
  let lastIndex = 0;

  for (const match of source.matchAll(PLAIN_OL_TOKEN_RE)) {
    const matchIndex = match.index ?? 0;
    const token = match[0];

    html += renderChordProgressionSegment(source.slice(lastIndex, matchIndex));
    html += renderOlSpecialToken(token, viewOptions);
    lastIndex = matchIndex + token.length;
  }

  html += renderChordProgressionSegment(source.slice(lastIndex));
  return html;
}

function hasChordedLyricText(value) {
  const source = String(value ?? '');
  if (!HAS_CHORD_TOKEN_RE.test(source)) {
    return false;
  }

  const lyricText = source
    .replace(CHORD_TOKEN_RE, '')
    .replace(BAR_TOKEN_RE, '')
    .replace(REPEAT_TOKEN_RE, '')
    .replace(DIRECTIVE_TOKEN_RE, '')
    .trim();

  return lyricText.length > 0;
}

// "Hide keys" has to take the whole key note with it, not just the bracketed
// chords: a progression line (`| G | D/F# | Em | C |` in an Intro/Outro) or a
// bracket-only line carries no lyric, so hiding its chords would leave a row of
// naked bars behind. Directives stay content — a `{c: Guitar}` cue is not a key.
function isChordOnlyLineText(value) {
  const source = String(value ?? '');

  if (!HAS_CHORD_TOKEN_RE.test(source) && !hasChordProgressionText(source)) {
    return false;
  }

  return !source
    .replace(CHORD_TOKEN_RE, ' ')
    .replace(BAR_TOKEN_RE, ' ')
    .replace(REPEAT_TOKEN_RE, ' ')
    .split(/[\s\u200B]+/u)
    .some((segment) => segment && !BARE_CHORD_RE.test(segment));
}

function shouldFloatLeadingBar(value, chordStart, lastTextIndex) {
  const barIndex = chordStart - 1;

  if (barIndex < lastTextIndex || value[barIndex] !== '|') {
    return false;
  }

  const previousCharacter = value[barIndex - 1] || '';
  return previousCharacter !== '|' && previousCharacter !== ':';
}

function createChordPlaceholderHtml(index) {
  return `<span ${CHORD_PLACEHOLDER_ATTRIBUTE}="${escapeHtml(index)}"></span>`;
}

function renderHtmlFragment(fragment) {
  const container = document.createElement('div');
  container.append(fragment);
  return container.innerHTML;
}

function createChordedLyricSegments(value, viewOptions = {}) {
  const source = String(value ?? '');
  const chordTokens = [];
  let placeholderSource = '';
  let lastIndex = 0;

  for (const match of source.matchAll(CHORD_TOKEN_RE)) {
    const chordStart = match.index ?? 0;
    const chordEnd = chordStart + match[0].length;
    const labelStart = shouldFloatLeadingBar(source, chordStart, lastIndex)
      ? chordStart - 1
      : chordStart;

    placeholderSource += source.slice(lastIndex, labelStart);
    placeholderSource += createChordPlaceholderHtml(chordTokens.length);
    chordTokens.push(source.slice(labelStart, chordEnd));
    lastIndex = chordEnd;
  }

  if (!chordTokens.length) {
    return [];
  }

  placeholderSource += source.slice(lastIndex);

  const renderedHtml = renderPlainOlText(placeholderSource, viewOptions);
  const container = document.createElement('div');
  container.innerHTML = renderedHtml;

  const placeholders = Array.from(
    container.querySelectorAll(`[${CHORD_PLACEHOLDER_ATTRIBUTE}]`),
  );

  if (!placeholders.length) {
    return [];
  }

  const segments = [];
  const range = document.createRange();

  range.setStart(container, 0);
  range.setEndBefore(placeholders[0]);
  const leadingLyricHtml = renderHtmlFragment(range.cloneContents());

  if (leadingLyricHtml) {
    segments.push({
      chord: '',
      lyricHtml: leadingLyricHtml,
    });
  }

  placeholders.forEach((placeholder, index) => {
    const placeholderIndex = Number(
      placeholder.getAttribute(CHORD_PLACEHOLDER_ATTRIBUTE),
    );

    range.setStartAfter(placeholder);

    if (placeholders[index + 1]) {
      range.setEndBefore(placeholders[index + 1]);
    } else {
      range.setEnd(container, container.childNodes.length);
    }

    segments.push({
      chord: chordTokens[placeholderIndex] || '',
      lyricHtml: renderHtmlFragment(range.cloneContents()),
    });
  });

  return segments;
}

function createChordedLyricTextLines(value, viewOptions = {}) {
  const source = String(value ?? '');
  const { hideBracketedKeys, hideLeadingBars } =
    normalizePreviewViewOptions(viewOptions);

  if (!hasChordedLyricText(source)) {
    return [trimSpaceLikeEnd(source)];
  }

  const chordPlacements = [];
  let lyricLine = '';
  let lastTextIndex = 0;

  for (const match of source.matchAll(CHORD_TOKEN_RE)) {
    const chordStart = match.index ?? 0;
    const chordEnd = chordStart + match[0].length;
    const floatedLeadingBar = shouldFloatLeadingBar(
      source,
      chordStart,
      lastTextIndex,
    );
    const labelStart = floatedLeadingBar ? chordStart - 1 : chordStart;

    lyricLine += source.slice(lastTextIndex, labelStart);
    if (!hideBracketedKeys) {
      chordPlacements.push({
        label: `${floatedLeadingBar && !hideLeadingBars ? '|' : ''}${getChordKey(match[0])}`,
        position: lyricLine.length,
      });
    }
    lastTextIndex = chordEnd;
  }

  lyricLine += source.slice(lastTextIndex);
  const normalizedLyricLine = trimSpaceLikeEnd(lyricLine);

  if (hideBracketedKeys) {
    return normalizedLyricLine ? [normalizedLyricLine] : [];
  }

  let chordLine = '';

  chordPlacements.forEach(({ label, position }) => {
    const safePosition = Math.max(position, chordLine.length);

    if (safePosition > chordLine.length) {
      chordLine += ' '.repeat(safePosition - chordLine.length);
    }

    chordLine += label;
  });

  return [trimSpaceLikeEnd(chordLine), normalizedLyricLine];
}

function renderChordedLyricText(value, viewOptions = {}) {
  // With keys hidden the chord tokens are already `display: none`, but the row
  // that held them still reserved its `min-height` — a blank band above every
  // lyric line. Collapse the container itself; the markers stay in the DOM so
  // `key-note` renderer contributions keep their anchors.
  const { hideBracketedKeys } = normalizePreviewViewOptions(viewOptions);
  const hiddenChordClassName = hideBracketedKeys
    ? ' ol-preview-lyric-segment__chord--hidden'
    : '';

  return createChordedLyricSegments(value, viewOptions)
    .map((segment) => {
      const chordHtml = segment.chord
        ? renderChordedLyricChordToken(segment.chord, viewOptions)
        : '&nbsp;';
      const lyricHtml = segment.lyricHtml?.length
        ? preserveRenderedWhitespace(segment.lyricHtml)
        : '&nbsp;';

      return [
        '<span class="ol-preview-lyric-segment">',
        `<span class="ol-preview-lyric-segment__chord${segment.chord ? '' : ' ol-preview-lyric-segment__chord--empty'}${hiddenChordClassName}">${chordHtml}</span>`,
        `<span class="ol-preview-lyric-segment__text">${lyricHtml}</span>`,
        '</span>',
      ].join('');
    })
    .join('');
}

function renderEmptyFenceBody() {
  return '<div class="ol-preview-empty">Empty section</div>';
}

function renderLineCollection(lines, options = {}) {
  const viewOptions = normalizePreviewViewOptions(options.viewOptions);

  if (!lines.length) {
    return renderEmptyFenceBody();
  }

  const fontColorState = createFontColorState();
  const renderedLines = lines
    .map((line) => {
      const entry =
        typeof line === 'string'
          ? { text: line, lineNumber: null, column: 1 }
          : line;
      const textSegments = getInlineTextSegmentsWithFontColors(
        entry.text,
        fontColorState,
      );
      const visibleText = textSegments.map((segment) => segment.text).join('');

      if (viewOptions.hideBracketedKeys && isChordOnlyLineText(visibleText)) {
        return '';
      }

      const usesChordedLyricLayout =
        options.useChordedLyricLayout && hasChordedLyricText(visibleText);
      const renderedLineText =
        typeof options.renderLineText === 'function'
          ? preserveRenderedWhitespace(
              renderTextSegments(textSegments, options.renderLineText),
            )
          : preserveRenderedWhitespace(
              renderTextSegments(textSegments, (value) =>
                renderInlineOlText(value, viewOptions),
              ),
            );
      const content = !entry.text.length
        ? '&nbsp;'
        : !visibleText.length
          ? ''
          : usesChordedLyricLayout
            ? `<span class="ol-preview-line__content ol-preview-line__content--chorded">${renderChordedLyricText(buildLineSourceFromTextSegments(textSegments), viewOptions)}</span>`
            : renderedLineText;

      if (!content) {
        return '';
      }

      const classNames = usesChordedLyricLayout
        ? 'ol-preview-line ol-preview-line--chorded'
        : 'ol-preview-line';
      return `<div class="${classNames}"${getEditorDataAttributes(entry.lineNumber, entry.column)}>${content}</div>`;
    })
    .filter(Boolean);

  if (!renderedLines.length) {
    // Every line was a key note that "hide keys" took away — the section is not
    // empty in the source, so say nothing rather than claim "Empty section".
    return viewOptions.hideBracketedKeys ? '' : renderEmptyFenceBody();
  }

  return ['<div class="ol-preview-lines">', ...renderedLines, '</div>'].join(
    '',
  );
}

function renderLyricLineCollection(lines, viewOptions = {}) {
  return renderLineCollection(lines, {
    useChordedLyricLayout: true,
    viewOptions,
  });
}

function renderMixedLineCollection(lines, viewOptions = {}) {
  return renderLineCollection(lines, {
    useChordedLyricLayout: true,
    viewOptions,
    renderLineText(value) {
      return hasChordProgressionText(value)
        ? renderChordProgressionText(value, viewOptions)
        : renderInlineOlText(value, viewOptions);
    },
  });
}

function renderChordProgressionLineCollection(lines, viewOptions = {}) {
  return renderLineCollection(lines, {
    viewOptions,
    renderLineText(value) {
      return hasChordProgressionText(value)
        ? renderChordProgressionText(value, viewOptions)
        : renderInlineOlText(value, viewOptions);
    },
  });
}

function normalizeStrummingPatternLine(line) {
  if (line && typeof line === 'object') {
    return {
      allowZwspSeparators: Boolean(line.allowZwspSeparators),
      text: line.text,
      lineNumber: line.lineEntry?.lineNumber ?? line.lineNumber ?? null,
      column: line.valueColumn || line.lineEntry?.column || line.column || 1,
      rawLine: line.rawLine || '',
      sourceIndex: Number.isInteger(line.sourceIndex) ? line.sourceIndex : null,
    };
  }

  return {
    allowZwspSeparators: false,
    text: line,
    lineNumber: null,
    column: 1,
    rawLine: String(line ?? ''),
    sourceIndex: null,
  };
}

function parseStrummingPatterns(lines, options = {}) {
  const patterns = [];
  let pendingLabel = '';
  let pendingLabelSourceIndex = null;
  const fallbackAllowZwspSeparators = resolveAllowZwspSeparators(
    (lines || [])
      .map((line) => {
        return typeof line === 'object' ? line?.text : line;
      })
      .join('\n'),
    options.allowZwspSeparators,
  );

  (lines || []).forEach((line, sourceIndex) => {
    const normalizedLine = normalizeStrummingPatternLine(line);
    const allowZwspSeparators =
      normalizedLine.allowZwspSeparators || fallbackAllowZwspSeparators;
    const trimmedLine = trimSpaceLikeText(
      normalizedLine.text,
      allowZwspSeparators,
    );
    const resolvedSourceIndex = Number.isInteger(normalizedLine.sourceIndex)
      ? normalizedLine.sourceIndex
      : sourceIndex;

    if (!trimmedLine) {
      return;
    }

    if (isCommentLine(trimmedLine, allowZwspSeparators)) {
      pendingLabel = trimmedLine.replace(/^\/\/\s*/, '').trim();
      pendingLabelSourceIndex = resolvedSourceIndex;
      return;
    }

    patterns.push({
      label: pendingLabel || `Pattern #${patterns.length + 1}`,
      labelSourceIndex: pendingLabel ? pendingLabelSourceIndex : null,
      allowZwspSeparators,
      pattern: trimmedLine,
      lineNumber: normalizedLine.lineNumber,
      column: normalizedLine.column,
      sourceIndex: resolvedSourceIndex,
    });
    pendingLabel = '';
    pendingLabelSourceIndex = null;
  });

  return patterns;
}

function getStrummingTimeSignatureDefinition(timeSignatureText) {
  return (
    STRUMMING_TIME_SIGNATURES.get(String(timeSignatureText ?? '').trim()) ||
    STRUMMING_TIME_SIGNATURES.get('4/4')
  );
}

function getDefaultStrummingDirection(stepIndex) {
  return stepIndex % 2 === 0 ? 'down' : 'up';
}

function getStrummingStepLabel(stepIndex, timeSignature) {
  if (timeSignature.labelMode === 'eighth') {
    return {
      text: stepIndex % 2 === 0 ? String(Math.floor(stepIndex / 2) + 1) : '&',
      accent: stepIndex % 2 === 0,
    };
  }

  const phase = stepIndex % 4;

  if (phase === 0) {
    return {
      text: String(Math.floor(stepIndex / 4) + 1),
      accent: true,
    };
  }

  return {
    text: ['', 'e', '&', 'a'][phase],
    accent: false,
  };
}

function getStrummingBeatGuideGroups(stepCount, timeSignature) {
  if (!Number.isInteger(stepCount) || stepCount < 1) {
    return [];
  }

  const baseGroups = Array.isArray(timeSignature?.beatGroups)
    ? timeSignature.beatGroups.filter(
        (groupSize) => Number.isInteger(groupSize) && groupSize > 0,
      )
    : [];
  const resolvedBaseGroups = baseGroups.length ? baseGroups : [stepCount];
  const beatGuideGroups = [];
  let remainingSteps = stepCount;

  while (remainingSteps > 0) {
    resolvedBaseGroups.forEach((groupSize, index) => {
      if (remainingSteps < 1) {
        return;
      }

      const span = Math.min(groupSize, remainingSteps);

      beatGuideGroups.push({
        label: String(index + 1),
        span,
      });
      remainingSteps -= span;
    });
  }

  return beatGuideGroups;
}

function renderStrummingBeatGuideRow(stepCount, timeSignature) {
  const beatGuideGroups = getStrummingBeatGuideGroups(stepCount, timeSignature);

  if (beatGuideGroups.length < 2) {
    return '';
  }

  return [
    '<div class="ol-song-view__pattern-row ol-song-view__pattern-row--guide" aria-hidden="true">',
    ...beatGuideGroups.map((group, groupIndex) => {
      const classNames = ['ol-song-view__pattern-guide-cell'];

      if (groupIndex > 0) {
        classNames.push('ol-song-view__pattern-guide-cell--break');
      }

      return `<span class="${classNames.join(' ')}" style="grid-column: span ${group.span}">${escapeHtml(group.label)}</span>`;
    }),
    '</div>',
  ].join('');
}

function parseStrummingPatternSteps(patternText, options = {}) {
  const steps = [];
  const breakBefore = new Set();
  let stepIndex = 0;
  const allowZwspSeparators = resolveAllowZwspSeparators(
    patternText,
    options.allowZwspSeparators,
  );
  const normalizedPatternText = normalizeStrummingPatternValue(
    patternText,
    allowZwspSeparators,
  );

  for (
    let sourceOffset = 0;
    sourceOffset < normalizedPatternText.length;
    sourceOffset += 1
  ) {
    const character = normalizedPatternText[sourceOffset];

    if (isSpaceLikeCharacter(character, allowZwspSeparators)) {
      continue;
    }

    if (character === '|') {
      if (stepIndex > 0) {
        breakBefore.add(stepIndex);
      }

      continue;
    }

    let direction = null;

    if (STRUMMING_DOWN_SYMBOLS.has(character)) {
      direction = 'down';
    } else if (STRUMMING_UP_SYMBOLS.has(character)) {
      direction = 'up';
    } else if (STRUMMING_DEFAULT_SYMBOLS.has(character)) {
      direction = getDefaultStrummingDirection(stepIndex);
    } else if (!STRUMMING_REST_SYMBOLS.has(character)) {
      continue;
    }

    steps.push({
      index: stepIndex,
      direction,
      breakBefore: breakBefore.has(stepIndex),
      sourceOffset,
    });
    stepIndex += 1;
  }

  return steps;
}

function describeStrummingPatternStepDirection(direction) {
  if (direction === 'down') {
    return 'down';
  }

  if (direction === 'up') {
    return 'up';
  }

  return 'none';
}

function renderStrummingPatternGrid(
  patternText,
  timeSignatureText,
  options = {},
) {
  const timeSignature = getStrummingTimeSignatureDefinition(timeSignatureText);
  const steps = parseStrummingPatternSteps(patternText, options);
  const interactive = Boolean(options.interactive);
  const patternIndex = Number.isInteger(options.patternIndex)
    ? options.patternIndex
    : null;
  const patternLabel =
    String(options.patternLabel ?? 'pattern').trim() || 'pattern';

  if (!steps.length) {
    return '';
  }

  const countCells = steps
    .map((step) => {
      const label = getStrummingStepLabel(step.index, timeSignature);
      const classNames = ['ol-song-view__pattern-cell'];

      if (label.accent) {
        classNames.push('ol-song-view__pattern-cell--accent');
      }

      if (step.breakBefore) {
        classNames.push('ol-song-view__pattern-cell--break');
      }

      if (!interactive || patternIndex == null) {
        return `<span class="${classNames.join(' ')}">${escapeHtml(label.text)}</span>`;
      }

      const stateText = describeStrummingPatternStepDirection(step.direction);
      const stepLabel = label.text || String(step.index + 1);

      return `<button class="${classNames.join(' ')} ol-song-view__pattern-cell-button" type="button" data-preview-action="toggle-strumming-pattern-step" data-pattern-index="${escapeHtml(patternIndex)}" data-pattern-step-index="${escapeHtml(step.index)}" aria-label="${escapeHtml(`Toggle ${patternLabel} step ${stepLabel}. Current state: ${stateText}.`)}" title="${escapeHtml(`${patternLabel} ${stepLabel}: ${stateText}`)}">${escapeHtml(stepLabel)}</button>`;
    })
    .join('');

  const strokeCells = steps
    .map((step) => {
      const classNames = [
        'ol-song-view__pattern-cell',
        'ol-song-view__pattern-cell--stroke',
      ];

      if (step.direction === 'down') {
        classNames.push('ol-song-view__pattern-cell--down');
      } else if (step.direction === 'up') {
        classNames.push('ol-song-view__pattern-cell--up');
      } else {
        classNames.push('ol-song-view__pattern-cell--rest');
      }

      if (step.breakBefore) {
        classNames.push('ol-song-view__pattern-cell--break');
      }

      const symbol =
        step.direction === 'down'
          ? '&darr;'
          : step.direction === 'up'
            ? '&uarr;'
            : '&nbsp;';

      return `<span class="${classNames.join(' ')}">${symbol}</span>`;
    })
    .join('');
  const beatGuideRow = renderStrummingBeatGuideRow(steps.length, timeSignature);

  return [
    `<div class="ol-song-view__pattern-display" style="--pattern-column-count: ${steps.length}">`,
    beatGuideRow,
    `<div class="ol-song-view__pattern-row ol-song-view__pattern-row--stroke">${strokeCells}</div>`,
    `<div class="ol-song-view__pattern-row ol-song-view__pattern-row--count">${countCells}</div>`,
    '</div>',
  ].join('');
}

function renderStrummingPatternCards(
  patternLines,
  timeSignatureText,
  options = {},
) {
  const patterns = Array.isArray(options.patterns)
    ? options.patterns
    : parseStrummingPatterns(patternLines, {
        allowZwspSeparators: options.allowZwspSeparators,
      });
  const resolvedTimeSignatureText =
    String(timeSignatureText ?? '').trim() || '4/4';
  const sharedPatternDataAttributes = getStrummingPatternPreviewDataAttributes({
    keyText: options.keyText,
    tempoText: options.tempoText,
    timeSignatureText: resolvedTimeSignatureText,
  });

  if (!patterns.length) {
    return '';
  }

  const containerClassName =
    options.containerClassName || 'ol-song-view__pattern-grid';
  const cardClassName = options.cardClassName || 'ol-song-view__pattern-card';

  return [
    `<div class="${escapeHtml(containerClassName)}"${sharedPatternDataAttributes}>`,
    ...patterns.map((pattern, patternIndex) => {
      const editorDataAttributes = options.includeEditorData
        ? getEditorDataAttributes(pattern.lineNumber, pattern.column)
        : '';
      const patternIndexText = `#${patternIndex + 1}`;
      const usesFallbackLabel =
        String(pattern.label ?? '').trim() === `Pattern #${patternIndex + 1}`;
      const patternLabelText = usesFallbackLabel ? '' : pattern.label;
      const patternHeadingAriaLabel = usesFallbackLabel
        ? `${pattern.label}: ${pattern.pattern}`
        : `${patternIndexText} ${pattern.label}: ${pattern.pattern}`;
      const patternActionHtml =
        typeof options.renderPatternActions === 'function'
          ? options.renderPatternActions(pattern, patternIndex)
          : '';
      const patternDataAttributes = [
        sharedPatternDataAttributes,
        ` data-pattern-index="${escapeHtml(patternIndex)}"`,
        ` data-pattern-label="${escapeHtml(pattern.label)}"`,
        ` data-pattern-source="${escapeHtml(pattern.pattern)}"`,
      ].join('');
      const patternTargetId = createPatternPreviewTargetId(
        options.patternTargetIdPrefix,
        patternIndex + 1,
      );

      return [
        `<section class="${escapeHtml(cardClassName)}"${patternTargetId ? ` id="${escapeHtml(patternTargetId)}"` : ''}${editorDataAttributes}${patternDataAttributes}>`,
        '<div class="ol-song-view__pattern-header">',
        '<div class="ol-song-view__pattern-heading">',
        `<h3 class="ol-song-view__pattern-title" title="${escapeHtml(pattern.pattern)}" aria-label="${escapeHtml(patternHeadingAriaLabel)}"><span class="ol-song-view__pattern-index">${escapeHtml(patternIndexText)}</span>${patternLabelText ? ` <span class="ol-song-view__pattern-label">${escapeHtml(patternLabelText)}</span>` : ''}</h3>`,
        '</div>',
        patternActionHtml,
        '</div>',
        renderStrummingPatternGrid(pattern.pattern, resolvedTimeSignatureText, {
          allowZwspSeparators: pattern.allowZwspSeparators,
          interactive: Boolean(options.includeStepActions),
          patternIndex,
          patternLabel: pattern.label,
        }),
        '</section>',
      ].join('');
    }),
    '</div>',
  ].join('');
}

function renderStrummingPatternsAddAction() {
  return [
    '<div class="ol-preview-config__patterns-action">',
    '<button class="ol-preview-config__part-action" type="button" data-preview-action="add-strumming-pattern" aria-label="Add strumming pattern" title="Add strumming pattern">+</button>',
    '</div>',
  ].join('');
}

function getStrummingPatternPreviewDataAttributes(options = {}) {
  const keyText = String(options.keyText ?? '').trim();
  const tempoText = String(options.tempoText ?? '').trim();
  const timeText = String(
    options.timeSignatureText ?? options.timeText ?? '',
  ).trim();
  const attributes = [];

  if (keyText) {
    attributes.push(` data-pattern-preview-key="${escapeHtml(keyText)}"`);
  }

  if (timeText) {
    attributes.push(` data-pattern-preview-time="${escapeHtml(timeText)}"`);
  }

  if (tempoText) {
    attributes.push(` data-pattern-preview-tempo="${escapeHtml(tempoText)}"`);
  }

  return attributes.join('');
}

function renderConfigStrummingPatternValue(
  patternLines,
  timeSignatureText,
  options = {},
) {
  const patterns = Array.isArray(options.patterns)
    ? options.patterns
    : parseStrummingPatterns(patternLines, {
        allowZwspSeparators: options.allowZwspSeparators,
      });
  const cardsHtml = renderStrummingPatternCards(
    patternLines,
    timeSignatureText,
    {
      cardClassName:
        'ol-song-view__pattern-card ol-preview-config__pattern-card',
      containerClassName:
        'ol-song-view__pattern-grid ol-preview-config__pattern-grid',
      includeEditorData: true,
      includeStepActions: true,
      keyText: options.keyText,
      patterns,
      patternTargetIdPrefix: options.patternPreviewTargetIdPrefix,
      tempoText: options.tempoText,
      renderPatternActions(pattern, patternIndex) {
        return [
          '<div class="ol-preview-config__pattern-actions">',
          `<button class="ol-preview-config__pattern-duplicate" type="button" data-preview-action="duplicate-strumming-pattern" data-pattern-index="${escapeHtml(patternIndex)}" aria-label="Duplicate ${escapeHtml(pattern.label)}" title="Duplicate ${escapeHtml(pattern.label)}"><span class="ol-preview-config__pattern-duplicate-icon" aria-hidden="true"></span></button>`,
          `<button class="ol-preview-config__pattern-remove" type="button" data-preview-action="remove-strumming-pattern" data-pattern-index="${escapeHtml(patternIndex)}" aria-label="Remove ${escapeHtml(pattern.label)}" title="Remove ${escapeHtml(pattern.label)}">&times;</button>`,
          '</div>',
        ].join('');
      },
    },
  );

  return `<div class="ol-preview-config__patterns-value${patterns.length ? '' : ' ol-preview-config__patterns-value--empty'}">${cardsHtml}${renderStrummingPatternsAddAction()}</div>`;
}

function createPreviewHelpers(viewOptions = {}) {
  const normalizedViewOptions = normalizePreviewViewOptions(viewOptions);

  return {
    createStrummingPatternPreviewContextFromConfigBody(
      configBody,
      options = {},
    ) {
      return createStrummingPatternPreviewContextFromConfigBody(
        configBody,
        options,
      );
    },
    createPreviewTargetId,
    createPreviewLineEntries,
    escapeHtml,
    getEditorDataAttributes,
    getFenceHeaderEditorDataAttributes,
    hasChordProgressionText,
    renderChordProgressionLineCollection(lines) {
      return renderChordProgressionLineCollection(lines, normalizedViewOptions);
    },
    renderConfigStrummingPatternValue(
      patternLines,
      timeSignatureText,
      options,
    ) {
      return renderConfigStrummingPatternValue(
        patternLines,
        timeSignatureText,
        {
          ...options,
          patternPreviewTargetIdPrefix:
            options.patternPreviewTargetIdPrefix ||
            normalizedViewOptions.patternPreviewTargetIdPrefix,
        },
      );
    },
    renderInlineText(value) {
      return renderInlineOlText(value, normalizedViewOptions);
    },
    renderEmptyBody: renderEmptyFenceBody,
    renderLineCollection(lines, options = {}) {
      return renderLineCollection(lines, {
        ...options,
        viewOptions: normalizedViewOptions,
      });
    },
    renderLyricLineCollection(lines) {
      return renderLyricLineCollection(lines, normalizedViewOptions);
    },
    renderMixedLineCollection(lines) {
      return renderMixedLineCollection(lines, normalizedViewOptions);
    },
    renderStrummingPatternCards,
    renderStructureValue,
  };
}

const previewHelpers = createPreviewHelpers();

function renderUnknownFenceHtml(
  info,
  body,
  sourceLocation = null,
  helpers = previewHelpers,
) {
  const lines = createPreviewLineEntries(body, sourceLocation);
  const header = info || 'unknown';
  const kind = 'unknown';
  const title = info ? `ol:${info}` : 'ol';
  const targetId = createPreviewTargetId(title);
  const editorLine = sourceLocation?.bodyLineNumber || '';
  const editorColumn = sourceLocation?.bodyColumn || '';
  const titleEditorAttributes = getFenceHeaderEditorDataAttributes(
    sourceLocation?.startLineNumber || '',
  );

  return [
    `<details class="ol-preview-fence ol-preview-fence--${escapeHtml(kind)}" data-ol-kind="${escapeHtml(kind)}" data-ol-header="${escapeHtml(header)}"${targetId ? ` id="${escapeHtml(targetId)}"` : ''}${getEditorDataAttributes(editorLine, editorColumn)} open>`,
    '<summary class="ol-preview-fence__summary">',
    `<span class="ol-preview-fence__title"${titleEditorAttributes}>${escapeHtml(title)}</span>`,
    '</summary>',
    `<div class="ol-preview-fence__body">${helpers.renderLineCollection(lines)}</div>`,
    '</details>',
  ].join('');
}

function renderOpenLyricFenceHtml(
  info,
  body,
  sourceLocation = null,
  helpers = previewHelpers,
) {
  const parsedHeader = parseFenceHeader(info);
  const definition = parsedHeader?.definition || null;

  if (!definition) {
    return renderUnknownFenceHtml(info, body, sourceLocation, helpers);
  }

  return definition.renderPreview({
    body,
    parsedHeader,
    sourceLocation,
    helpers,
  });
}

