import { hideChordDiagramPopup } from '../../chord-popup.ts';
import { getOpenLyricPreviewApi } from '../../../../editor/scripts/open-lyric-plugin.ts';
import { refs, state } from '../../../../editor/scripts/shared.ts';
import { DEFAULT_PREVIEW_TYPOGRAPHY } from '../../../../editor/scripts/app/preview-controllers/constants.ts';
import { OPEN_LYRIC_PATTERN_TARGET_ID_PREFIX } from '../helpers.ts';

function getSingleLinePreviewChangeLineNumber(contentChangeEvent) {
  if (contentChangeEvent?.isFlush) {
    return 0;
  }

  const changes = Array.isArray(contentChangeEvent?.changes)
    ? contentChangeEvent.changes
    : [];

  if (changes.length !== 1) {
    return 0;
  }

  const [change] = changes;
  const startLineNumber = Number(change?.range?.startLineNumber) || 0;
  const endLineNumber = Number(change?.range?.endLineNumber) || startLineNumber;
  const normalizedText = String(change?.text || '').replace(/\r\n?/g, '\n');

  if (
    !startLineNumber ||
    startLineNumber !== endLineNumber ||
    normalizedText.includes('\n')
  ) {
    return 0;
  }

  return startLineNumber;
}

function createElementsFromHtml(html, selector) {
  const template = document.createElement('template');
  template.innerHTML = String(html || '').trim();
  return Array.from(template.content.querySelectorAll(selector));
}

// Pixels of overflow below which a section is treated as fitting a single block.
const OPEN_LYRIC_SECTION_OVERFLOW_TOLERANCE = 1;

// Widest hidden overflow inside a section: either the section itself spilling or
// a chorded lyric line clipped inside its own horizontal scroll container.
function measureOpenLyricSectionOverflow(section) {
  let overflow = section.scrollWidth - section.clientWidth;

  section.querySelectorAll('.ol-preview-line--chorded').forEach((line) => {
    if (line instanceof HTMLElement) {
      overflow = Math.max(overflow, line.scrollWidth - line.clientWidth);
    }
  });

  return overflow;
}

// For a song-view sections grid, widen any section whose content would be
// clipped so it spans enough blocks to show everything (capped at the number of
// columns). Section order is preserved (no dense packing) so the song still
// reads top-to-bottom, left-to-right.
function balanceOpenLyricSectionSpans(container) {
  const sections = Array.from(
    container.querySelectorAll(':scope > .ol-song-view__section'),
  ).filter((section) => section instanceof HTMLElement);

  if (!sections.length) {
    return;
  }

  // Reset to a single-block baseline so measurements reflect one column.
  sections.forEach((section) => {
    section.style.removeProperty('grid-column');
  });

  const styles = getComputedStyle(container);
  const trackWidths = styles.gridTemplateColumns
    .split(' ')
    .map((value) => Number.parseFloat(value))
    .filter((value) => Number.isFinite(value) && value > 0.5);
  const columnCount = trackWidths.length;

  if (columnCount < 2) {
    return;
  }

  const columnWidth = trackWidths[0];
  const columnGap = Number.parseFloat(styles.columnGap) || 0;
  const columnStride = columnWidth + columnGap;

  if (columnStride <= 0) {
    return;
  }

  // Measure every section against the single-block baseline before mutating, so
  // widening an earlier section cannot skew a later section's measurement.
  const spans = sections.map((section) => {
    const overflow = measureOpenLyricSectionOverflow(section);

    if (overflow <= OPEN_LYRIC_SECTION_OVERFLOW_TOLERANCE) {
      return 1;
    }

    return Math.min(1 + Math.ceil(overflow / columnStride), columnCount);
  });

  sections.forEach((section, index) => {
    if (spans[index] > 1) {
      section.style.gridColumn = `span ${spans[index]}`;
    }
  });
}

function getSelectedStructureKeys() {
  return state.openLyricStructureKeys &&
    typeof state.openLyricStructureKeys === 'object'
    ? state.openLyricStructureKeys
    : {};
}

function applyOpenLyricPreviewControllerSetupMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    getPreviewStructureControlState(this: any) {
      const previewApi = getOpenLyricPreviewApi();

      if (
        typeof previewApi?.createOpenLyricStructureControlState !== 'function'
      ) {
        return null;
      }

      return previewApi.createOpenLyricStructureControlState(
        this.getCurrentValue(),
        {
          selectedStructureKeys: getSelectedStructureKeys(),
        },
      );
    },

    getOpenLyricRenderOptions(this: any) {
      return {
        hideBracketedKeys: Boolean(state.openLyricHideKeys),
        hideLeadingBars: Boolean(state.openLyricHideLeadingBars),
        simplifyChords: Boolean(state.openLyricSimplifyChords),
        selectedStructureKeys: getSelectedStructureKeys(),
      };
    },

    syncPreviewStructureControls(this: any) {
      const controlState = this.getPreviewStructureControlState();
      const keyLabel = controlState?.title || 'Default Config';
      const pluginAvailable = Boolean(state.openLyricPluginAvailable);

      if (refs.previewStructureKeySelect instanceof HTMLSelectElement) {
        refs.previewStructureKeySelect.replaceChildren();

        for (const keyValue of controlState?.keyOptions || []) {
          const option = document.createElement('option');
          option.value = keyValue;
          option.textContent = keyValue;
          option.selected = keyValue === controlState?.selectedKeyText;
          refs.previewStructureKeySelect.append(option);
        }

        if (!refs.previewStructureKeySelect.options.length) {
          const option = document.createElement('option');
          option.value = '';
          option.textContent = 'No key';
          option.selected = true;
          refs.previewStructureKeySelect.append(option);
        }

        refs.previewStructureKeySelect.disabled =
          !pluginAvailable || !controlState?.keyOptions.length;
        refs.previewStructureKeySelect.dataset.structureKeyId =
          controlState?.structureKeyId || '';
        refs.previewStructureKeySelect.setAttribute(
          'aria-label',
          `Change ${keyLabel} main key`,
        );
      }

      [
        [
          refs.previewStructureKeyPreviousBtn,
          controlState?.previousKeyText || '',
          'down',
        ],
        [
          refs.previewStructureKeyNextBtn,
          controlState?.nextKeyText || '',
          'up',
        ],
      ].forEach(([button, nextKeyValue, direction]) => {
        if (!(button instanceof HTMLButtonElement)) {
          return;
        }

        const canStep = Boolean(
          pluginAvailable && controlState?.structureKeyId && nextKeyValue,
        );

        button.disabled = !canStep;
        button.dataset.structureKeyId = canStep
          ? controlState.structureKeyId
          : '';

        if (canStep) {
          button.dataset.structureKeyValue = nextKeyValue;
        } else {
          button.removeAttribute('data-structure-key-value');
        }

        button.setAttribute(
          'aria-label',
          `Transpose ${keyLabel} ${direction} one step`,
        );
        button.title = `Transpose ${direction} one step`;
      });

      [
        [
          refs.previewOpenLyricSimplifyBtn,
          Boolean(state.openLyricSimplifyChords),
        ],
        [
          refs.previewOpenLyricHideBarsBtn,
          Boolean(state.openLyricHideLeadingBars),
        ],
        [refs.previewOpenLyricHideKeysBtn, Boolean(state.openLyricHideKeys)],
      ].forEach(([button, isPressed]) => {
        if (!(button instanceof HTMLButtonElement)) {
          return;
        }

        button.disabled = !pluginAvailable;
        button.setAttribute('aria-pressed', isPressed ? 'true' : 'false');
      });
    },

    syncOpenLyricPluginControls(this: any) {
      const pluginAvailable = Boolean(state.openLyricPluginAvailable);

      if (refs.openLyricPluginToggle instanceof HTMLInputElement) {
        refs.openLyricPluginToggle.checked = pluginAvailable;
        refs.openLyricPluginToggle.setAttribute(
          'aria-checked',
          String(pluginAvailable),
        );
        refs.openLyricPluginToggle.setAttribute(
          'aria-label',
          pluginAvailable
            ? 'Disable Open Lyric plugin'
            : 'Enable Open Lyric plugin',
        );
        refs.openLyricPluginToggle.title = pluginAvailable
          ? 'Disable Open Lyric plugin'
          : 'Enable Open Lyric plugin';
      }

      if (refs.openLyricPluginStatusNote) {
        refs.openLyricPluginStatusNote.hidden = pluginAvailable;
      }

      if (refs.openLyricOptions instanceof HTMLElement) {
        refs.openLyricOptions.hidden = !pluginAvailable;
      }

      if (!pluginAvailable) {
        this.closeOpenLyricOptionsMenu?.();
      }
    },

    handlePreviewStructureKeyStepClick(this: any, event) {
      const button = event?.currentTarget || event?.target || null;
      const structureKeyId =
        button?.getAttribute?.('data-structure-key-id') ||
        button?.dataset?.structureKeyId ||
        '';
      const nextKeyValue =
        button?.getAttribute?.('data-structure-key-value') ||
        button?.dataset?.structureKeyValue ||
        '';

      if (!structureKeyId || !nextKeyValue) {
        return;
      }

      event.preventDefault();

      state.openLyricStructureKeys = {
        ...(state.openLyricStructureKeys || {}),
        [structureKeyId]: nextKeyValue,
      };

      hideChordDiagramPopup();
      this.renderOpenLyric(this.getCurrentValue());
    },

    handlePreviewStructureKeyChange(this: any, event) {
      const keySelect = event?.currentTarget || event?.target || null;
      const structureKeyId =
        keySelect?.getAttribute?.('data-structure-key-id') ||
        keySelect?.dataset?.structureKeyId ||
        '';
      const nextValue =
        keySelect instanceof HTMLSelectElement
          ? keySelect.value
          : keySelect?.getAttribute('value') || '';

      if (!structureKeyId || !nextValue) {
        return;
      }

      state.openLyricStructureKeys = {
        ...(state.openLyricStructureKeys || {}),
        [structureKeyId]: nextValue,
      };

      hideChordDiagramPopup();
      this.renderOpenLyric(this.getCurrentValue());
    },

    handleOpenLyricPluginToggleChange(this: any, event) {
      const input = event?.currentTarget;

      if (!(input instanceof HTMLInputElement)) {
        return;
      }

      try {
        this.onOpenLyricPluginEnabledChange?.(input.checked);
      } catch (error) {
        console.error('Failed to toggle Open Lyric plugin.', error);
      }
    },

    handlePreviewOpenLyricToggleClick(this: any, event) {
      const button = event.currentTarget;

      if (
        !(button instanceof HTMLButtonElement) ||
        !state.openLyricPluginAvailable
      ) {
        return;
      }

      event.preventDefault();

      switch (button.dataset.openLyricSetting) {
        case 'simplify':
          state.openLyricSimplifyChords = !state.openLyricSimplifyChords;
          break;
        case 'hide-leading-bars':
          state.openLyricHideLeadingBars = !state.openLyricHideLeadingBars;
          break;
        case 'hide-keys':
          state.openLyricHideKeys = !state.openLyricHideKeys;
          break;
        default:
          return;
      }

      hideChordDiagramPopup();
      this.renderOpenLyric(this.getCurrentValue());
    },

    handlePreviewTypographyResetClick(this: any) {
      state.openLyricHideKeys = false;
      state.openLyricHideLeadingBars = false;
      state.openLyricSimplifyChords = false;
      state.openLyricStructureKeys = {};
      this.setPreviewTypographyPreference(DEFAULT_PREVIEW_TYPOGRAPHY);

      hideChordDiagramPopup();
      this.renderOpenLyric(this.getCurrentValue());
    },

    renderOpenLyricIncrementally(
      this: any,
      markdown,
      contentChangeEvent = null,
    ) {
      const previewApi = getOpenLyricPreviewApi();

      if (
        !(refs.openLyricPreview instanceof Element) ||
        !state.openLyricVisible ||
        !state.openLyricPluginAvailable ||
        typeof previewApi?.renderOpenLyricPreviewSectionsForLine !== 'function'
      ) {
        return false;
      }

      const targetLineNumber =
        getSingleLinePreviewChangeLineNumber(contentChangeEvent);

      if (!targetLineNumber) {
        return false;
      }

      const sectionUpdate = previewApi.renderOpenLyricPreviewSectionsForLine(
        markdown,
        targetLineNumber,
        this.getOpenLyricRenderOptions(),
      );

      if (!sectionUpdate?.partName || !sectionUpdate.html) {
        return false;
      }

      const currentSections = Array.from(
        refs.openLyricPreview.querySelectorAll('.ol-song-view__section'),
      ).filter((sectionElement) => {
        return (
          sectionElement.getAttribute('data-ol-part-name') ===
          sectionUpdate.partName
        );
      });
      const nextSections = createElementsFromHtml(
        sectionUpdate.html,
        '.ol-song-view__section',
      );

      if (
        !currentSections.length ||
        nextSections.length !== currentSections.length
      ) {
        return false;
      }

      currentSections.forEach((sectionElement, index) => {
        const nextSection = nextSections[index];

        if (!(nextSection instanceof Element)) {
          return;
        }

        sectionElement.replaceWith(nextSection);
      });

      this.hydrateOpenLyricPatternTargets();
      this.syncPreviewSettingsControls();
      this.applyOpenLyricSectionSpans();
      return true;
    },

    renderOpenLyric(this: any, markdown, contentChangeEvent = null) {
      const previewApi = getOpenLyricPreviewApi();

      if (!refs.openLyricPreview || !state.openLyricVisible) {
        return;
      }

      if (
        !state.openLyricPluginAvailable ||
        typeof previewApi?.renderOpenLyricPreview !== 'function'
      ) {
        // Safe with an adopt-mode component attached too: its render root IS
        // this container, so clearing children never removes component DOM.
        refs.openLyricPreview.innerHTML = '';
        this.syncPreviewSettingsControls();
        return;
      }

      if (this.renderOpenLyricIncrementally(markdown, contentChangeEvent)) {
        // Same as the markdown panel: the fast path wrote the DOM itself, so
        // the component still has to be told what the document says (the
        // locale-matched plugin font is resolved from it).
        this.openLyricPreviewComponent?.syncRenderedValue?.(markdown);
        return;
      }

      const lyricComponent = this.openLyricPreviewComponent;

      if (lyricComponent?.isMounted) {
        lyricComponent.extraRenderOptions = this.getOpenLyricRenderOptions();

        if (lyricComponent.value !== markdown) {
          lyricComponent.value = markdown;
        } else {
          lyricComponent.reload();
        }
      } else {
        refs.openLyricPreview.innerHTML = previewApi.renderOpenLyricPreview(
          markdown,
          this.getOpenLyricRenderOptions(),
        );
      }

      this.hydrateOpenLyricPatternTargets();

      this.syncPreviewSettingsControls();
      this.applyOpenLyricSectionSpans();
    },

    // Schedule a block-span balance pass (after layout) and make sure the
    // preview is observed so spans stay correct when the panel is resized.
    applyOpenLyricSectionSpans(this: any) {
      if (!(refs.openLyricPreview instanceof HTMLElement)) {
        return;
      }

      this.ensureOpenLyricSectionSpanObserver();

      if (typeof globalThis.requestAnimationFrame === 'function') {
        globalThis.requestAnimationFrame(() => {
          this.balanceOpenLyricSectionSpans();
        });
      } else {
        this.balanceOpenLyricSectionSpans();
      }
    },

    balanceOpenLyricSectionSpans(this: any) {
      if (!(refs.openLyricPreview instanceof HTMLElement)) {
        return;
      }

      refs.openLyricPreview
        .querySelectorAll('.ol-song-view__sections')
        .forEach((container) => {
          if (container instanceof HTMLElement) {
            balanceOpenLyricSectionSpans(container);
          }
        });
    },

    ensureOpenLyricSectionSpanObserver(this: any) {
      if (
        this.openLyricSectionSpanObserver ||
        typeof ResizeObserver === 'undefined' ||
        !(refs.openLyricPreview instanceof HTMLElement)
      ) {
        return;
      }

      let scheduled = false;
      const observer = new ResizeObserver(() => {
        if (scheduled) {
          return;
        }

        scheduled = true;
        globalThis.requestAnimationFrame(() => {
          scheduled = false;
          this.balanceOpenLyricSectionSpans();
        });
      });

      observer.observe(refs.openLyricPreview);
      this.openLyricSectionSpanObserver = observer;

      // Web fonts change text metrics after the first paint, so re-balance once
      // they finish loading (chorded lyric widths shift when the real font swaps
      // in). Fires once; the observer handles every later width change.
      const fontsReady = globalThis.document?.fonts?.ready;

      if (fontsReady && typeof fontsReady.then === 'function') {
        fontsReady.then(() => {
          this.balanceOpenLyricSectionSpans();
        });
      }
    },

    hydrateOpenLyricPatternTargets(this: any) {
      if (!(refs.openLyricPreview instanceof Element)) {
        return;
      }

      refs.openLyricPreview
        .querySelectorAll('.ol-song-view__pattern-card')
        .forEach((cardElement) => {
          const patternIndexText =
            cardElement.getAttribute('data-pattern-index') || '';
          const patternIndex = Number.parseInt(patternIndexText, 10);

          if (!Number.isInteger(patternIndex) || patternIndex < 0) {
            return;
          }

          if (!cardElement.id) {
            cardElement.id = `${OPEN_LYRIC_PATTERN_TARGET_ID_PREFIX}-${patternIndex + 1}`;
          }
        });

      refs.openLyricPreview
        .querySelectorAll('[data-pattern-reference-index]')
        .forEach((triggerElement) => {
          const patternIndexText =
            triggerElement.getAttribute('data-pattern-reference-index') || '';
          const patternIndex = Number.parseInt(patternIndexText, 10);

          if (!Number.isInteger(patternIndex) || patternIndex < 1) {
            return;
          }

          const targetId = `${OPEN_LYRIC_PATTERN_TARGET_ID_PREFIX}-${patternIndex}`;
          const hasTarget = Array.from(
            refs.openLyricPreview.querySelectorAll('[id]'),
          ).some((element) => element.id === targetId);

          if (!hasTarget) {
            return;
          }

          triggerElement.setAttribute('data-preview-target-id', targetId);
        });
    },

    handleOpenLyricPluginAvailabilityChange(this: any) {
      if (!state.openLyricPluginAvailable && refs.openLyricPreview) {
        refs.openLyricPreview.innerHTML = '';
      }

      this.closeOpenLyricOptionsMenu?.();
      this.syncPreviewSettingsControls();
    },

    getOpenLyricPresentationData(this: any) {
      const previewApi = getOpenLyricPreviewApi();

      if (typeof previewApi?.createOpenLyricPresentationData !== 'function') {
        return null;
      }

      return previewApi.createOpenLyricPresentationData(
        this.getCurrentValue(),
        {
          hideBracketedKeys: Boolean(state.openLyricHideKeys),
          hideLeadingBars: Boolean(state.openLyricHideLeadingBars),
          simplifyChords: Boolean(state.openLyricSimplifyChords),
          selectedStructureKeys: getSelectedStructureKeys(),
        },
      );
    },
  });
}

export { applyOpenLyricPreviewControllerSetupMethods };
