import { state } from '../../editor/scripts/shared.ts';
import { DEFAULT_PREVIEW_TYPOGRAPHY } from '../../editor/scripts/app/preview-controllers/constants.ts';
import { applyPreviewControllerInteractionMethods } from '../../editor/scripts/app/preview-controllers/interaction.ts';
import { applyPreviewControllerMenuMethods } from '../../editor/scripts/app/preview-controllers/menus.ts';
import { applyPreviewControllerSetupMethods } from '../../editor/scripts/app/preview-controllers/setup-and-render.ts';
import { applyPreviewControllerConfigEditingMethods } from './preview/controller/config-editing.ts';
import { applyPreviewControllerConfigPopupMethods } from './preview/controller/config-popups.ts';
import { applyPreviewControllerExportCommonMethods } from './preview/controller/export-common.ts';
import { applyPreviewControllerDocxExportMethods } from './preview/controller/export-docx.ts';
import { applyPreviewControllerPowerPointMethods } from './preview/controller/export-powerpoint.ts';
import { applyPreviewControllerSurfaceExportMethods } from './preview/controller/export-surface.ts';
import { applyOpenLyricPreviewControllerInteractionMethods } from './preview/controller/interaction.ts';
import { applyOpenLyricPreviewControllerMenuMethods } from './preview/controller/menus.ts';
import { applyOpenLyricPreviewControllerSetupMethods } from './preview/controller/setup-and-render.ts';

/**
 * Owns preview rendering, preview-to-editor navigation, and chord popup
 * interactions for both preview panes.
 */
class PreviewController {
  [key: string]: any;

  constructor({
    getCurrentValue,
    onOpenLyricPluginEnabledChange = null,
    preferences = null,
  }) {
    this.getCurrentValue = getCurrentValue;
    this.onOpenLyricPluginEnabledChange = onOpenLyricPluginEnabledChange;
    this.preferences = preferences;
    this.lastPanelVisibility = {
      openLyricVisible: Boolean(state.openLyricVisible),
      previewVisible: Boolean(state.previewVisible),
    };
    // Drives the lyric panel's settings popup only. The markdown panel's popup
    // is the component's own — `OpenLyricMarkdownStandaloneChrome`, filled into
    // that panel's settings mount — and keeps its typography there.
    this.previewTypography = {
      ...DEFAULT_PREVIEW_TYPOGRAPHY,
    };
    this.previewJumpHighlightTimer = 0;
    this.previewClickTimer = 0;
    this.pendingConfigFieldActivation = '';
    this.pendingConfigFieldActivationFrame = 0;
    this.declarePartPopup = null;
    this.activeDeclarePartButton = null;
    this.configAddPopup = null;
    this.activeConfigAddButton = null;
    this.configKeyPopup = null;
    this.activeConfigKeyButton = null;
    this.configAttachmentPopup = null;
    this.activeConfigAttachmentButton = null;
    this.configLocalePopup = null;
    this.activeConfigLocaleButton = null;
    this.configTimePopup = null;
    this.activeConfigTimeButton = null;
    this.configTempoPopup = null;
    this.activeConfigTempoButton = null;
    this.isOpenLyricActionPending = false;
    this.isMarkdownPreviewActionPending = false;
    this.markdownPreviewProgressResetTimer = 0;
    this.openLyricProgressResetTimer = 0;

    this.handlePreviewClick = this.handlePreviewClick.bind(this);
    this.handlePreviewDoubleClick = this.handlePreviewDoubleClick.bind(this);
    this.handlePreviewChange = this.handlePreviewChange.bind(this);
    this.handleChordPointerOver = this.handleChordPointerOver.bind(this);
    this.handleChordPointerOut = this.handleChordPointerOut.bind(this);
    this.handleChordFocusIn = this.handleChordFocusIn.bind(this);
    this.handleChordFocusOut = this.handleChordFocusOut.bind(this);
    this.handleDocumentPointerDown = this.handleDocumentPointerDown.bind(this);
    this.handleDocumentKeyDown = this.handleDocumentKeyDown.bind(this);
    this.handleDeclarePartPopupClick =
      this.handleDeclarePartPopupClick.bind(this);
    this.handleConfigAddPopupClick = this.handleConfigAddPopupClick.bind(this);
    this.handleConfigKeyPopupClick = this.handleConfigKeyPopupClick.bind(this);
    this.handleConfigAttachmentPopupInput =
      this.handleConfigAttachmentPopupInput.bind(this);
    this.handleConfigAttachmentPopupSubmit =
      this.handleConfigAttachmentPopupSubmit.bind(this);
    this.handleConfigLocalePopupClick =
      this.handleConfigLocalePopupClick.bind(this);
    this.handleConfigLocalePopupInput =
      this.handleConfigLocalePopupInput.bind(this);
    this.handleConfigLocalePopupSubmit =
      this.handleConfigLocalePopupSubmit.bind(this);
    this.handleConfigTimePopupClick =
      this.handleConfigTimePopupClick.bind(this);
    this.handleConfigTempoPopupInput =
      this.handleConfigTempoPopupInput.bind(this);
    this.handleConfigTempoPopupChange =
      this.handleConfigTempoPopupChange.bind(this);
    this.handleDeclarePartViewportChange =
      this.handleDeclarePartViewportChange.bind(this);
    this.handlePreviewFontFamilyInput =
      this.handlePreviewFontFamilyInput.bind(this);
    this.handlePreviewFontSizeInput =
      this.handlePreviewFontSizeInput.bind(this);
    this.handleTopbarActionsFocusOut =
      this.handleTopbarActionsFocusOut.bind(this);
    this.handleTopbarActionsMenuClick =
      this.handleTopbarActionsMenuClick.bind(this);
    this.handleTopbarActionsToggleClick =
      this.handleTopbarActionsToggleClick.bind(this);
    this.handlePreviewSettingsFocusOut =
      this.handlePreviewSettingsFocusOut.bind(this);
    this.handlePreviewSettingsToggleClick =
      this.handlePreviewSettingsToggleClick.bind(this);
    this.handlePreviewStructureKeyChange =
      this.handlePreviewStructureKeyChange.bind(this);
    this.handlePreviewStructureKeyStepClick =
      this.handlePreviewStructureKeyStepClick.bind(this);
    this.handlePreviewTypographyResetClick =
      this.handlePreviewTypographyResetClick.bind(this);
    this.handleOpenLyricPluginToggleChange =
      this.handleOpenLyricPluginToggleChange.bind(this);
    this.handlePreviewOpenLyricToggleClick =
      this.handlePreviewOpenLyricToggleClick.bind(this);
    this.handleMarkdownPreviewOptionsToggleClick =
      this.handleMarkdownPreviewOptionsToggleClick.bind(this);
    this.handleMarkdownPreviewOptionsFocusOut =
      this.handleMarkdownPreviewOptionsFocusOut.bind(this);
    this.handleMarkdownPreviewImageDownloadClick =
      this.handleMarkdownPreviewImageDownloadClick.bind(this);
    this.handleMarkdownPreviewDocxDownloadClick =
      this.handleMarkdownPreviewDocxDownloadClick.bind(this);
    this.handleMarkdownDocClick = this.handleMarkdownDocClick.bind(this);
    this.handleMarkdownPreviewPrintClick =
      this.handleMarkdownPreviewPrintClick.bind(this);
    this.handleOpenLyricOptionsToggleClick =
      this.handleOpenLyricOptionsToggleClick.bind(this);
    this.handleOpenLyricOptionsFocusOut =
      this.handleOpenLyricOptionsFocusOut.bind(this);
    this.handleOpenLyricTextCopyClick =
      this.handleOpenLyricTextCopyClick.bind(this);
    this.handleOpenLyricImageDownloadClick =
      this.handleOpenLyricImageDownloadClick.bind(this);
    this.handleOpenLyricPowerPointDownloadClick =
      this.handleOpenLyricPowerPointDownloadClick.bind(this);
    this.handleOpenLyricPrintClick = this.handleOpenLyricPrintClick.bind(this);
  }
}

applyPreviewControllerSetupMethods(PreviewController);
applyOpenLyricPreviewControllerSetupMethods(PreviewController);
applyPreviewControllerMenuMethods(PreviewController);
applyOpenLyricPreviewControllerMenuMethods(PreviewController);
applyPreviewControllerExportCommonMethods(PreviewController);
applyPreviewControllerDocxExportMethods(PreviewController);
applyPreviewControllerPowerPointMethods(PreviewController);
applyPreviewControllerSurfaceExportMethods(PreviewController);
applyPreviewControllerConfigEditingMethods(PreviewController);
applyPreviewControllerConfigPopupMethods(PreviewController);
applyPreviewControllerInteractionMethods(PreviewController);
applyOpenLyricPreviewControllerInteractionMethods(PreviewController);

export { PreviewController };
