import {
  DEFAULT_THEME,
  LANGUAGE_THEME,
  MONACO_THEME_BY_APP_THEME,
  refs,
  runtime,
  state,
} from '../shared.ts';
import {
  OPEN_LYRIC_THEME_LABELS,
  OPEN_LYRIC_THEMES,
  getOpenLyricThemeBase,
} from '../../components/internal/theme.ts';
import { closeFloatingMenu, openFloatingMenu } from '../floating-menu.ts';
import { defineOpenLyricMonacoThemes } from '../monaco-theme.ts';
import { hideChordDiagramPopup } from '../../../plugins/OpenLyric/chord-popup.ts';

const SYSTEM_DARK_THEME_MEDIA_QUERY = '(prefers-color-scheme: dark)';

/**
 * Keeps theme state and UI synchronized while exposing a small surface to the
 * composition root.
 *
 * Four themes, not two: `light`/`dark` plus the `light-bs`/`dark-bs` pair
 * painted in Bootstrap's palette. Two attributes carry that on `<html>` —
 * `data-theme` holds the full name (what the stylesheets scope on) and
 * `data-bs-theme` only ever holds the light/dark base, because that is all
 * Bootstrap's own stylesheet understands.
 */
class ThemeController {
  constructor({ monaco, preferences, onThemeApplied = null }) {
    this.monaco = monaco;
    this.preferences = preferences;
    this.onThemeApplied = onThemeApplied;
    this.systemThemeMediaQuery = null;
    this.systemThemeListenerBound = false;
    this.handleSystemThemeChange = this.handleSystemThemeChange.bind(this);
    this.handleDocumentPointerDown = this.handleDocumentPointerDown.bind(this);
    this.handleDocumentKeydown = this.handleDocumentKeydown.bind(this);
  }

  setMonaco(monaco) {
    this.monaco = monaco;
    this.ensureEditorThemesRegistered();
  }

  ensureEditorThemesRegistered() {
    if (!this.monaco?.editor || runtime.languageRegistered) {
      return;
    }

    defineOpenLyricMonacoThemes(this.monaco.editor);
  }

  getEditorTheme(theme = state.theme) {
    return MONACO_THEME_BY_APP_THEME[theme] ?? LANGUAGE_THEME;
  }

  getSystemThemeMediaQuery() {
    if (this.systemThemeMediaQuery) {
      return this.systemThemeMediaQuery;
    }

    if (typeof globalThis.matchMedia !== 'function') {
      return null;
    }

    try {
      this.systemThemeMediaQuery = globalThis.matchMedia(
        SYSTEM_DARK_THEME_MEDIA_QUERY,
      );
    } catch (_error) {
      return null;
    }

    return this.systemThemeMediaQuery;
  }

  getSystemThemePreference() {
    const systemThemeMediaQuery = this.getSystemThemeMediaQuery();

    if (typeof systemThemeMediaQuery?.matches === 'boolean') {
      return systemThemeMediaQuery.matches ? 'dark' : 'light';
    }

    return this.preferences.loadThemePreference();
  }

  bindSystemThemeListener() {
    if (this.systemThemeListenerBound) {
      return;
    }

    const systemThemeMediaQuery = this.getSystemThemeMediaQuery();

    if (!systemThemeMediaQuery) {
      return;
    }

    if (typeof systemThemeMediaQuery.addEventListener === 'function') {
      systemThemeMediaQuery.addEventListener(
        'change',
        this.handleSystemThemeChange,
      );
      this.systemThemeListenerBound = true;
      return;
    }

    if (typeof systemThemeMediaQuery.addListener === 'function') {
      systemThemeMediaQuery.addListener(this.handleSystemThemeChange);
      this.systemThemeListenerBound = true;
    }
  }

  handleSystemThemeChange() {
    if (this.preferences.hasStoredThemePreference()) {
      return;
    }

    this.applyTheme(this.getSystemThemePreference());
  }

  applyPreferredTheme() {
    const storedTheme = this.preferences.loadStoredThemePreference();

    this.bindSystemThemeListener();
    this.applyTheme(storedTheme ?? this.getSystemThemePreference(), {
      notifyThemeApplied: false,
    });
  }

  bindEvents() {
    refs.themeToggleBtn?.addEventListener('click', () => {
      // With no menu in the markup (an inlined shell that predates the picker)
      // the trigger keeps its original job and cycles through the themes.
      if (refs.themeMenu) {
        this.toggleThemeMenu();
        return;
      }

      this.toggleTheme();
    });

    for (const option of this.getThemeMenuOptions()) {
      option.addEventListener('click', () => {
        this.setTheme(option.dataset.olThemeOption);
        this.closeThemeMenu({ restoreFocus: true });
      });
    }

    if (refs.themeMenu) {
      document.addEventListener('pointerdown', this.handleDocumentPointerDown);
      document.addEventListener('keydown', this.handleDocumentKeydown);
    }
  }

  /** The picker's option buttons, in markup order. */
  getThemeMenuOptions() {
    return Array.from(
      refs.themeMenu?.querySelectorAll('[data-ol-theme-option]') ?? [],
    );
  }

  isThemeMenuOpen() {
    return Boolean(refs.themeMenu && !refs.themeMenu.hidden);
  }

  toggleThemeMenu() {
    if (this.isThemeMenuOpen()) {
      this.closeThemeMenu({ restoreFocus: true });
      return;
    }

    this.openThemeMenu();
  }

  openThemeMenu() {
    if (!refs.themeMenu || !refs.themeToggleBtn) {
      return;
    }

    refs.themeMenu.hidden = false;
    refs.themeToggleBtn.setAttribute('aria-expanded', 'true');
    openFloatingMenu(refs.themeMenu, refs.themeToggleBtn, { align: 'end' });
    // No auto-focus: these are `menuitemradio` buttons, and focusing a button
    // right after a touch-opened menu swallows the next tap on iOS/iPadOS (see
    // `focusElement`'s `skipTouchIosForButtons` in the copilot instructions).
  }

  closeThemeMenu({ restoreFocus = false } = {}) {
    if (!refs.themeMenu) {
      return;
    }

    closeFloatingMenu(refs.themeMenu);
    refs.themeMenu.hidden = true;
    refs.themeToggleBtn?.setAttribute('aria-expanded', 'false');

    if (restoreFocus) {
      refs.themeToggleBtn?.focus({ preventScroll: true });
    }
  }

  handleDocumentPointerDown(event) {
    if (!this.isThemeMenuOpen()) {
      return;
    }

    const target = event.target;

    if (
      refs.themeMenu?.contains(target) ||
      refs.themeToggleBtn?.contains(target)
    ) {
      return;
    }

    this.closeThemeMenu();
  }

  handleDocumentKeydown(event) {
    if (event.key === 'Escape' && this.isThemeMenuOpen()) {
      this.closeThemeMenu({ restoreFocus: true });
    }
  }

  applyTheme(theme, { notifyThemeApplied = true } = {}) {
    const nextTheme = this.preferences.normalizeTheme(theme);
    const themeBase = getOpenLyricThemeBase(nextTheme);
    const isDarkTheme = themeBase === 'dark';
    const themeLabel = `Theme: ${OPEN_LYRIC_THEME_LABELS[nextTheme]}`;

    state.theme = nextTheme;
    document.documentElement.dataset.theme = nextTheme;
    // Bootstrap's own stylesheet only knows `light` and `dark`, so it gets the
    // base — `dark-bs` would read as an unknown value and fall back to light.
    document.documentElement.setAttribute('data-bs-theme', themeBase);
    hideChordDiagramPopup();

    if (refs.themeToggleBtn) {
      refs.themeToggleBtn.setAttribute('aria-pressed', String(isDarkTheme));
      refs.themeToggleBtn.setAttribute('aria-label', themeLabel);
      refs.themeToggleBtn.setAttribute('title', themeLabel);
      refs.themeToggleBtn.querySelector(
        '[data-theme-toggle-label]',
      ).textContent = themeLabel;
    }

    for (const option of this.getThemeMenuOptions()) {
      option.setAttribute(
        'aria-checked',
        String(option.dataset.olThemeOption === nextTheme),
      );
    }

    this.ensureEditorThemesRegistered();

    if (this.monaco?.editor) {
      this.monaco.editor.setTheme(this.getEditorTheme(nextTheme));
    }

    if (notifyThemeApplied) {
      this.onThemeApplied?.(nextTheme);
    }
  }

  setTheme(theme) {
    const nextTheme = this.preferences.normalizeTheme(theme);
    this.applyTheme(nextTheme);
    this.preferences.saveThemePreference(nextTheme);
  }

  /** Advance to the next theme in `OPEN_LYRIC_THEMES`, wrapping around. */
  toggleTheme() {
    const currentIndex = OPEN_LYRIC_THEMES.indexOf(
      state.theme ?? DEFAULT_THEME,
    );
    const nextIndex = (currentIndex + 1) % OPEN_LYRIC_THEMES.length;

    this.setTheme(OPEN_LYRIC_THEMES[nextIndex]);
  }
}

export { ThemeController };
