import {
  hideChordDiagramPopup,
  isChordPopupElement,
  scheduleHideChordDiagramPopup,
  showChordDiagramPopup,
  showPreviewPopupForElement,
} from '../../../../plugins/OpenLyric/chord-popup.ts';
import { normalizeConfigFieldName, refs, state } from '../../shared.ts';
import {
  CONFIG_ADD_ACTION_ROOT_SELECTOR,
  CONFIG_ATTACHMENT_ACTION_ROOT_SELECTOR,
  CONFIG_KEY_ACTION_ROOT_SELECTOR,
  CONFIG_LOCALE_ACTION_ROOT_SELECTOR,
  CONFIG_TEMPO_ACTION_ROOT_SELECTOR,
  CONFIG_TIME_ACTION_ROOT_SELECTOR,
  DECLARE_PART_ACTION_ROOT_SELECTOR,
  PREVIEW_CLICK_DELAY_MS,
  PREVIEW_JUMP_HIGHLIGHT_CLASS,
  PREVIEW_POPUP_TRIGGER_SELECTOR,
} from './constants.ts';

function applyPreviewControllerInteractionMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    showChordKey(this: any, key, triggerElement = null) {
      showChordDiagramPopup(key, triggerElement, {
        title:
          triggerElement instanceof Element
            ? triggerElement.getAttribute('data-chord-title') || ''
            : '',
      });
    },

    jumpToPreviewFence(this: any, targetId, container = refs.preview) {
      if (!targetId) {
        return;
      }

      if (!(container instanceof Element)) {
        return;
      }

      const target = Array.from(container.querySelectorAll('[id]')).find(
        (element) => element.id === targetId,
      );
      if (!target) {
        return;
      }

      const targetFence = target.closest('.ol-preview-fence');
      if (targetFence instanceof HTMLDetailsElement) {
        targetFence.open = true;
      }

      clearTimeout(this.previewJumpHighlightTimer);
      [refs.preview, refs.openLyricPreview].forEach((previewContainer) => {
        previewContainer
          ?.querySelectorAll(`.${PREVIEW_JUMP_HIGHLIGHT_CLASS}`)
          .forEach((element) => {
            element.classList.remove(PREVIEW_JUMP_HIGHLIGHT_CLASS);
          });
      });

      target.classList.add(PREVIEW_JUMP_HIGHLIGHT_CLASS);
      target.scrollIntoView({
        behavior: 'smooth',
        block: 'start',
        inline: 'nearest',
      });

      this.previewJumpHighlightTimer = globalThis.setTimeout(() => {
        target.classList.remove(PREVIEW_JUMP_HIGHLIGHT_CLASS);
      }, 1800);
    },

    jumpToEditorFence(this: any, lineNumber, column = 1) {
      if (!state.editor) {
        return;
      }

      const model = state.editor.getModel();
      if (!model) {
        return;
      }

      const nextLineNumber = Math.min(
        Math.max(Number(lineNumber) || 1, 1),
        model.getLineCount(),
      );
      const nextColumn = Math.min(
        Math.max(Number(column) || 1, 1),
        model.getLineMaxColumn(nextLineNumber),
      );

      state.editor.focus();
      state.editor.setPosition({
        lineNumber: nextLineNumber,
        column: nextColumn,
      });
      state.editor.setSelection({
        startLineNumber: nextLineNumber,
        startColumn: nextColumn,
        endLineNumber: nextLineNumber,
        endColumn: nextColumn,
      });
      state.editor.revealPositionInCenter({
        lineNumber: nextLineNumber,
        column: nextColumn,
      });
    },

    handlePreviewClick(this: any, event) {
      if (event.defaultPrevented) {
        return;
      }

      const container =
        event.currentTarget instanceof Element
          ? event.currentTarget
          : refs.preview;
      const eventTarget = this.getEventTargetElement(event);
      const addStrummingPatternButton = eventTarget?.closest(
        '[data-preview-action="add-strumming-pattern"]',
      );

      if (
        addStrummingPatternButton &&
        container?.contains(addStrummingPatternButton)
      ) {
        event.preventDefault();
        this.closeDeclarePartMenus();
        this.appendStrummingPattern();
        return;
      }

      const duplicateStrummingPatternButton = eventTarget?.closest(
        '[data-preview-action="duplicate-strumming-pattern"]',
      );

      if (
        duplicateStrummingPatternButton &&
        container?.contains(duplicateStrummingPatternButton)
      ) {
        const patternIndex =
          duplicateStrummingPatternButton.getAttribute('data-pattern-index') ||
          '';

        event.preventDefault();
        this.closeDeclarePartMenus();
        this.duplicateStrummingPattern(patternIndex);
        return;
      }

      const removeStrummingPatternButton = eventTarget?.closest(
        '[data-preview-action="remove-strumming-pattern"]',
      );

      if (
        removeStrummingPatternButton &&
        container?.contains(removeStrummingPatternButton)
      ) {
        const patternIndex =
          removeStrummingPatternButton.getAttribute('data-pattern-index') || '';

        event.preventDefault();
        this.closeDeclarePartMenus();
        this.removeStrummingPattern(patternIndex);
        return;
      }

      const toggleStrummingPatternStepButton = eventTarget?.closest(
        '[data-preview-action="toggle-strumming-pattern-step"]',
      );

      if (
        toggleStrummingPatternStepButton &&
        container?.contains(toggleStrummingPatternStepButton)
      ) {
        const patternIndex =
          toggleStrummingPatternStepButton.getAttribute('data-pattern-index') ||
          '';
        const stepIndex =
          toggleStrummingPatternStepButton.getAttribute(
            'data-pattern-step-index',
          ) || '';

        event.preventDefault();
        this.closeDeclarePartMenus();
        this.toggleStrummingPatternStep(patternIndex, stepIndex);
        return;
      }

      const removeAttachmentButton = eventTarget?.closest(
        '[data-preview-action="remove-config-attachment"]',
      );

      if (
        removeAttachmentButton &&
        container?.contains(removeAttachmentButton)
      ) {
        const attachmentSourceIndex =
          removeAttachmentButton.getAttribute('data-attachment-source-index') ||
          '';

        event.preventDefault();
        this.closeDeclarePartMenus();
        this.removeAttachmentValue(attachmentSourceIndex);
        return;
      }

      const removeLocaleButton = eventTarget?.closest(
        '[data-preview-action="remove-config-locale"]',
      );

      if (removeLocaleButton && container?.contains(removeLocaleButton)) {
        const localeTag =
          removeLocaleButton.getAttribute('data-config-locale') || '';

        event.preventDefault();
        this.closeDeclarePartMenus();
        this.removeConfigLocale(localeTag);
        return;
      }

      const repeatDecreaseButton = eventTarget?.closest(
        '[data-preview-action="decrease-structure-repeat"]',
      );

      if (repeatDecreaseButton && container?.contains(repeatDecreaseButton)) {
        const stepIndex =
          repeatDecreaseButton.getAttribute('data-structure-step-index') || '';

        event.preventDefault();
        this.closeDeclarePartMenus();
        this.updateStructureStepRepeat(stepIndex, -1);
        return;
      }

      const repeatIncreaseButton = eventTarget?.closest(
        '[data-preview-action="increase-structure-repeat"]',
      );

      if (repeatIncreaseButton && container?.contains(repeatIncreaseButton)) {
        const stepIndex =
          repeatIncreaseButton.getAttribute('data-structure-step-index') || '';

        event.preventDefault();
        this.closeDeclarePartMenus();
        this.updateStructureStepRepeat(stepIndex, 1);
        return;
      }

      const declarePartToggle = eventTarget?.closest(
        '[data-preview-action="toggle-declare-part-menu"]',
      );

      if (declarePartToggle && container?.contains(declarePartToggle)) {
        const wasExpanded =
          declarePartToggle.getAttribute('aria-expanded') === 'true' &&
          this.activeDeclarePartButton === declarePartToggle &&
          Boolean(this.declarePartPopup && !this.declarePartPopup.hidden);

        event.preventDefault();
        this.closeDeclarePartMenus();

        if (wasExpanded) {
          return;
        }

        this.showDeclarePartPopup(declarePartToggle);
        return;
      }

      const configAddToggle = eventTarget?.closest(
        '[data-preview-action="toggle-config-add-menu"]',
      );

      if (configAddToggle && container?.contains(configAddToggle)) {
        const wasExpanded =
          configAddToggle.getAttribute('aria-expanded') === 'true' &&
          this.activeConfigAddButton === configAddToggle &&
          Boolean(this.configAddPopup && !this.configAddPopup.hidden);

        event.preventDefault();
        this.closeDeclarePartMenus();

        if (wasExpanded) {
          return;
        }

        this.showConfigAddPopup(configAddToggle);
        return;
      }

      const configKeyToggle = eventTarget?.closest(
        '[data-preview-action="toggle-config-key-menu"]',
      );

      if (configKeyToggle && container?.contains(configKeyToggle)) {
        const wasExpanded =
          configKeyToggle.getAttribute('aria-expanded') === 'true' &&
          this.activeConfigKeyButton === configKeyToggle &&
          Boolean(this.configKeyPopup && !this.configKeyPopup.hidden);

        event.preventDefault();
        this.closeDeclarePartMenus();
        hideChordDiagramPopup();

        if (wasExpanded) {
          return;
        }

        this.showConfigKeyPopup(configKeyToggle);
        return;
      }

      const configAttachmentToggle = eventTarget?.closest(
        '[data-preview-action="toggle-config-attachment-menu"]',
      );

      if (
        configAttachmentToggle &&
        container?.contains(configAttachmentToggle)
      ) {
        const wasExpanded =
          configAttachmentToggle.getAttribute('aria-expanded') === 'true' &&
          this.activeConfigAttachmentButton === configAttachmentToggle &&
          Boolean(
            this.configAttachmentPopup && !this.configAttachmentPopup.hidden,
          );

        event.preventDefault();
        this.closeDeclarePartMenus();

        if (wasExpanded) {
          return;
        }

        this.showConfigAttachmentPopup(configAttachmentToggle);
        return;
      }

      const configLocaleToggle = eventTarget?.closest(
        '[data-preview-action="toggle-config-locale-menu"]',
      );

      if (configLocaleToggle && container?.contains(configLocaleToggle)) {
        const wasExpanded =
          configLocaleToggle.getAttribute('aria-expanded') === 'true' &&
          this.activeConfigLocaleButton === configLocaleToggle &&
          Boolean(this.configLocalePopup && !this.configLocalePopup.hidden);

        event.preventDefault();
        this.closeDeclarePartMenus();

        if (wasExpanded) {
          return;
        }

        this.showConfigLocalePopup(configLocaleToggle);
        return;
      }

      const configTimeToggle = eventTarget?.closest(
        '[data-preview-action="toggle-config-time-menu"]',
      );

      if (configTimeToggle && container?.contains(configTimeToggle)) {
        const wasExpanded =
          configTimeToggle.getAttribute('aria-expanded') === 'true' &&
          this.activeConfigTimeButton === configTimeToggle &&
          Boolean(this.configTimePopup && !this.configTimePopup.hidden);

        event.preventDefault();
        this.closeDeclarePartMenus();

        if (wasExpanded) {
          return;
        }

        this.showConfigTimePopup(configTimeToggle);
        return;
      }

      const configTempoToggle = eventTarget?.closest(
        '[data-preview-action="toggle-config-tempo-menu"]',
      );

      if (configTempoToggle && container?.contains(configTempoToggle)) {
        const wasExpanded =
          configTempoToggle.getAttribute('aria-expanded') === 'true' &&
          this.activeConfigTempoButton === configTempoToggle &&
          Boolean(this.configTempoPopup && !this.configTempoPopup.hidden);

        event.preventDefault();
        this.closeDeclarePartMenus();

        if (wasExpanded) {
          return;
        }

        this.showConfigTempoPopup(configTempoToggle);
        return;
      }

      if (this.handleOpenLyricPreviewClick?.(eventTarget, event)) {
        return;
      }

      const popupTrigger = eventTarget?.closest(PREVIEW_POPUP_TRIGGER_SELECTOR);

      if (popupTrigger && container?.contains(popupTrigger)) {
        if (this.shouldJumpToPatternPreview(container, popupTrigger)) {
          const targetId = popupTrigger.getAttribute('data-preview-target-id');

          if (targetId) {
            event.preventDefault();
            clearTimeout(this.previewClickTimer);
            this.previewClickTimer = 0;
            hideChordDiagramPopup();
            this.jumpToPreviewFence(targetId, container);
          }

          return;
        }

        event.preventDefault();
        showPreviewPopupForElement(popupTrigger);
        return;
      }

      const link = eventTarget?.closest('[data-preview-target-id]');
      if (!link || !container?.contains(link)) {
        return;
      }

      const targetId = link.getAttribute('data-preview-target-id');
      if (!targetId) {
        return;
      }

      event.preventDefault();
      clearTimeout(this.previewClickTimer);
      this.previewClickTimer = globalThis.setTimeout(() => {
        this.jumpToPreviewFence(targetId, container);
        this.previewClickTimer = 0;
      }, PREVIEW_CLICK_DELAY_MS);
    },

    getDistanceToRectSquared(this: any, clientX, clientY, rect) {
      const deltaX =
        clientX < rect.left
          ? rect.left - clientX
          : clientX > rect.right
            ? clientX - rect.right
            : 0;
      const deltaY =
        clientY < rect.top
          ? rect.top - clientY
          : clientY > rect.bottom
            ? clientY - rect.bottom
            : 0;

      return deltaX * deltaX + deltaY * deltaY;
    },

    findNearestPreviewSourceElement(this: any, container, event) {
      if (!container) {
        return null;
      }

      const sourceElements = Array.from(
        container.querySelectorAll('[data-editor-line]'),
      );
      if (!sourceElements.length) {
        return null;
      }

      const preferredSourceElements = sourceElements.filter(
        (element) => !element.classList.contains('ol-preview-fence'),
      );
      const candidateElements = preferredSourceElements.length
        ? preferredSourceElements
        : sourceElements;

      let nearestElement = null;
      let nearestDistance = Number.POSITIVE_INFINITY;

      for (const element of candidateElements) {
        const rect = element.getBoundingClientRect();
        const distance = this.getDistanceToRectSquared(
          event.clientX,
          event.clientY,
          rect,
        );

        if (distance >= nearestDistance) {
          continue;
        }

        nearestDistance = distance;
        nearestElement = element;
      }

      return nearestElement;
    },

    handlePreviewDoubleClick(this: any, event) {
      clearTimeout(this.previewClickTimer);
      this.previewClickTimer = 0;

      const container =
        event.currentTarget instanceof Element
          ? event.currentTarget
          : refs.preview;
      const eventTarget = this.getEventTargetElement(event);
      if (
        eventTarget?.closest(
          '.ol-preview-config__patterns-action, .ol-preview-config__pattern-actions, .ol-preview-config__pattern-duplicate, .ol-preview-config__pattern-remove, [data-preview-action="toggle-strumming-pattern-step"]',
        )
      ) {
        return;
      }

      if (eventTarget?.closest('.ol-preview-structure-repeat-controls')) {
        return;
      }

      if (eventTarget?.closest(DECLARE_PART_ACTION_ROOT_SELECTOR)) {
        return;
      }

      if (
        eventTarget?.closest(CONFIG_ADD_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_KEY_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_ATTACHMENT_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_LOCALE_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_TIME_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_TEMPO_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(
          '.ol-preview-config__attachment-item a, .ol-preview-config__attachment-remove, .ol-preview-config__locale-remove',
        ) ||
        this.isConfigAddPopupElement(eventTarget) ||
        this.isConfigKeyPopupElement(eventTarget) ||
        this.isConfigAttachmentPopupElement(eventTarget) ||
        this.isConfigLocalePopupElement(eventTarget) ||
        this.isConfigTimePopupElement(eventTarget) ||
        this.isConfigTempoPopupElement(eventTarget)
      ) {
        return;
      }

      if (eventTarget?.closest(PREVIEW_POPUP_TRIGGER_SELECTOR)) {
        return;
      }

      const sourceElement =
        eventTarget?.closest('[data-editor-line]:not(.ol-preview-fence)') ||
        this.findNearestPreviewSourceElement(container, event);
      if (!sourceElement || !container?.contains(sourceElement)) {
        return;
      }

      const editorLine = sourceElement.getAttribute('data-editor-line');
      if (!editorLine) {
        return;
      }

      const editorColumn =
        sourceElement.getAttribute('data-editor-column') || '1';

      event.preventDefault();
      this.jumpToEditorFence(editorLine, editorColumn);
    },

    handlePreviewChange(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const configFieldControl = eventTarget?.closest(
        '[data-preview-action="update-config-field"]',
      );

      if (
        (configFieldControl instanceof HTMLInputElement ||
          configFieldControl instanceof HTMLSelectElement) &&
        refs.preview?.contains(configFieldControl)
      ) {
        const fieldName = normalizeConfigFieldName(
          configFieldControl.getAttribute('data-config-field') || '',
        );

        if (!fieldName) {
          return;
        }

        const nextValue =
          fieldName === 'Tempo'
            ? this.normalizeTempoConfigValue(configFieldControl.value)
            : configFieldControl.value;

        if (nextValue === null) {
          this.renderPreview(this.getCurrentValue());
          return;
        }

        this.updateConfigFieldValue(fieldName, nextValue);
        return;
      }

      if (this.handleOpenLyricPreviewChange?.(eventTarget, event)) {
        return;
      }
    },

    getPopupTriggerFromEvent(this: any, container, event) {
      const eventTarget = this.getEventTargetElement(event);
      const popupTrigger = eventTarget?.closest(PREVIEW_POPUP_TRIGGER_SELECTOR);

      if (!popupTrigger || !container?.contains(popupTrigger)) {
        return null;
      }

      return popupTrigger;
    },

    shouldJumpToPatternPreview(this: any, _container, popupTrigger) {
      return Boolean(
        popupTrigger?.hasAttribute('data-pattern-reference-index') &&
        popupTrigger.getAttribute('data-preview-target-id'),
      );
    },

    shouldOpenPopupForTrigger(this: any, container, popupTrigger) {
      return !this.shouldJumpToPatternPreview(container, popupTrigger);
    },

    handleChordPointerOver(this: any, event) {
      const container =
        event.currentTarget instanceof Element
          ? event.currentTarget
          : refs.preview;
      const popupTrigger = this.getPopupTriggerFromEvent(container, event);

      if (!popupTrigger) {
        return;
      }

      const relatedTrigger =
        event.relatedTarget instanceof Element
          ? event.relatedTarget.closest(PREVIEW_POPUP_TRIGGER_SELECTOR)
          : null;

      if (relatedTrigger === popupTrigger) {
        return;
      }

      if (!this.shouldOpenPopupForTrigger(container, popupTrigger)) {
        hideChordDiagramPopup();
        return;
      }

      showPreviewPopupForElement(popupTrigger);
    },

    handleChordPointerOut(this: any, event) {
      const container =
        event.currentTarget instanceof Element
          ? event.currentTarget
          : refs.preview;
      const popupTrigger = this.getPopupTriggerFromEvent(container, event);

      if (!popupTrigger) {
        return;
      }

      const relatedTrigger =
        event.relatedTarget instanceof Element
          ? event.relatedTarget.closest(PREVIEW_POPUP_TRIGGER_SELECTOR)
          : null;

      if (relatedTrigger === popupTrigger) {
        return;
      }

      if (!this.shouldOpenPopupForTrigger(container, popupTrigger)) {
        return;
      }

      scheduleHideChordDiagramPopup();
    },

    handleChordFocusIn(this: any, event) {
      const container =
        event.currentTarget instanceof Element
          ? event.currentTarget
          : refs.preview;
      const popupTrigger = this.getPopupTriggerFromEvent(container, event);

      if (!popupTrigger) {
        return;
      }

      if (!this.shouldOpenPopupForTrigger(container, popupTrigger)) {
        hideChordDiagramPopup();
        return;
      }

      showPreviewPopupForElement(popupTrigger);
    },

    handleChordFocusOut(this: any, event) {
      const container =
        event.currentTarget instanceof Element
          ? event.currentTarget
          : refs.preview;
      const popupTrigger = this.getPopupTriggerFromEvent(container, event);

      if (!popupTrigger) {
        return;
      }

      const nextFocusedTrigger =
        event.relatedTarget instanceof Element
          ? event.relatedTarget.closest(PREVIEW_POPUP_TRIGGER_SELECTOR)
          : null;

      if (isChordPopupElement(event.relatedTarget)) {
        return;
      }

      if (nextFocusedTrigger === popupTrigger) {
        return;
      }

      if (!this.shouldOpenPopupForTrigger(container, popupTrigger)) {
        return;
      }

      hideChordDiagramPopup();
    },

    wireChordPopupEvents(this: any, container) {
      container?.addEventListener('mouseover', this.handleChordPointerOver);
      container?.addEventListener('mouseout', this.handleChordPointerOut);
      container?.addEventListener('focusin', this.handleChordFocusIn);
      container?.addEventListener('focusout', this.handleChordFocusOut);
      container?.addEventListener('scroll', hideChordDiagramPopup, {
        passive: true,
      });
    },
  });
}

export { applyPreviewControllerInteractionMethods };
