// --- Lazy export dependencies ------------------------------------------------

// The rasterizer is heavy, so it loads on first use and the promise is
// memoized for later calls. The cache is cleared on failure so a transient
// chunk-load error (an offline blip) doesn't permanently wedge exports behind a
// memoized rejection. The caller passes an `import()` with a literal specifier
// so the bundler still sees the dependency.
function createLazyModuleLoader(importModule) {
  let modulePromise = null;

  return async function loadModule() {
    if (!modulePromise) {
      modulePromise = importModule().catch((error) => {
        modulePromise = null;
        throw error;
      });
    }

    return modulePromise;
  };
}

const loadHtmlToImageModule = createLazyModuleLoader(
  () => import('html-to-image'),
);

// --- Style helpers -----------------------------------------------------------

function isTransparentColor(colorValue) {
  const normalizedValue = String(colorValue ?? '')
    .trim()
    .toLowerCase();

  return (
    !normalizedValue ||
    normalizedValue === 'transparent' ||
    normalizedValue === 'rgba(0, 0, 0, 0)'
  );
}

function normalizeFontFamilyName(fontFamily) {
  return String(fontFamily ?? '')
    .trim()
    .replace(/^['"]+|['"]+$/g, '');
}

// Exported/printed markup is served from a different document, so relative
// `url()` references have to be rewritten to absolute ones against the page
// they came from. Data, blob and fragment urls already resolve on their own.
function resolveCssUrls(cssText, baseUrl) {
  return String(cssText ?? '').replace(
    /url\((['"]?)([^)'"\s][^)]*?)\1\)/g,
    (match, quote, rawUrl) => {
      const url = String(rawUrl ?? '').trim();

      if (
        !url ||
        url.startsWith('data:') ||
        url.startsWith('blob:') ||
        url.startsWith('#')
      ) {
        return match;
      }

      try {
        const resolvedUrl = new URL(url, baseUrl || document.baseURI).href;
        const wrappedQuote = quote || '"';

        return `url(${wrappedQuote}${resolvedUrl}${wrappedQuote})`;
      } catch (_error) {
        return match;
      }
    },
  );
}

// Guard against a stylesheet closing the `<style>` element it is inlined into.
function escapeStyleElementText(cssText) {
  return String(cssText ?? '').replace(/<\/style/giu, '<\\/style');
}

