import { marked } from 'marked';

import {
  CHORD_SYMBOL_SOURCE,
  CONFIG_KEY_VALUES,
  hasChordProgressionText,
  normalizeConfigFieldName,
  normalizeStrummingPatternValue,
} from '../../../editor/scripts/shared.ts';
import { OLParser } from '../domain/parser/OLParser.ts';
import { parseFenceHeader } from '../domain/parser/fences.ts';
import {
  formatStructureStepLabel,
  parseStructureValue,
} from '../domain/structure.ts';
import {
  createChordedLyricTextLines,
  createPreviewHelpers,
  createPreviewLineEntries,
  createStrummingPatternPreviewContextFromConfigBody,
  getPreviewSourceLocation,
  isChordOnlyLineText,
  normalizeMarkdownRenderableUrls,
  parseStrummingPatterns,
  previewHelpers,
  renderInlineTextPlainText,
  sanitizeHtml,
} from './helpers.ts';
import {
  createChordTransposition,
  describeChordKey,
  getAdjacentChromaticKey as getAdjacentChromaticKeyForConfig,
  normalizeStructureKeyOption,
  parseMainKey,
  simplifyChordSymbol,
  transposeChordSymbol,
} from '../domain/music-theory.ts';

const OL_FENCE_BLOCK_RE = /^```ol:([^\r\n]*)[ \t]*\r?\n([\s\S]*?)^```[ \t]*$/gm;
const BARE_CHORD_RE = new RegExp(`^${CHORD_SYMBOL_SOURCE}$`);
const PLAIN_OL_TOKEN_RE =
  /(\{[^{}\r\n]+\}|\|\|:|\|:|:\|\||:\||\||\([1-9]\d*x\))/g;
const OPEN_LYRIC_PATTERN_TARGET_ID_PREFIX = 'ol-song-view-pattern';
const OPEN_LYRIC_INLINE_MARKDOWN_SELECTOR = [
  '.ol-song-view__title',
  '.ol-song-view__subtitle',
  '.ol-song-view__copyright',
  '.ol-song-view__description > span',
  '.ol-song-view__detail-value > span',
  '.ol-song-view__attachment > span',
].join(', ');

function normalizeNewlines(value) {
  return String(value ?? '').replace(/\r\n?/g, '\n');
}

function normalizeInlinePlainText(value) {
  return renderInlineTextPlainText(String(value ?? ''));
}

function renderInlineMarkdownFragment(text) {
  return sanitizeHtml(
    marked.parseInline(normalizeMarkdownRenderableUrls(text), {
      gfm: true,
      breaks: true,
    }),
  );
}

function renderOpenLyricInlineMarkdown(html) {
  const parser = new DOMParser();
  const doc = parser.parseFromString(String(html ?? ''), 'text/html');

  doc.querySelectorAll(OPEN_LYRIC_INLINE_MARKDOWN_SELECTOR).forEach((root) => {
    const source = root.textContent || '';

    if (!source.trim()) {
      return;
    }

    root.innerHTML = renderInlineMarkdownFragment(source);
  });

  return doc.body.innerHTML;
}

function transposeInlineChordText(text, semitoneOffset, targetKeyText) {
  return String(text ?? '').replace(
    /\[([^\[\]\r\n]+)\]/g,
    (_match, chordText) => {
      return `[${transposeChordSymbol(chordText, semitoneOffset, targetKeyText)}]`;
    },
  );
}

function transposeChordProgressionSegment(text, semitoneOffset, targetKeyText) {
  return String(text ?? '')
    .split(/(\s+)/)
    .map((segment) => {
      if (!segment || /^\s+$/.test(segment)) {
        return segment;
      }

      return BARE_CHORD_RE.test(segment)
        ? transposeChordSymbol(segment, semitoneOffset, targetKeyText)
        : segment;
    })
    .join('');
}

function transposeChordProgressionText(text, semitoneOffset, targetKeyText) {
  const source = String(text ?? '');
  let transposedText = '';
  let lastIndex = 0;

  for (const match of source.matchAll(PLAIN_OL_TOKEN_RE)) {
    const matchIndex = match.index ?? 0;

    transposedText += transposeChordProgressionSegment(
      source.slice(lastIndex, matchIndex),
      semitoneOffset,
      targetKeyText,
    );
    transposedText += match[0];
    lastIndex = matchIndex + match[0].length;
  }

  transposedText += transposeChordProgressionSegment(
    source.slice(lastIndex),
    semitoneOffset,
    targetKeyText,
  );

  return transposedText;
}

function transposeSectionText(text, sectionKind, transposition) {
  if (!transposition?.isActive) {
    return String(text ?? '');
  }

  if (
    sectionKind === 'intro' ||
    sectionKind === 'instrumental' ||
    hasChordProgressionText(text)
  ) {
    return transposeChordProgressionText(
      text,
      transposition.semitoneOffset,
      transposition.targetKeyText,
    );
  }

  return transposeInlineChordText(
    text,
    transposition.semitoneOffset,
    transposition.targetKeyText,
  );
}

function simplifyInlineChordText(text) {
  return String(text ?? '').replace(
    /\[([^\[\]\r\n]+)\]/g,
    (_match, chordText) => {
      return `[${simplifyChordSymbol(chordText)}]`;
    },
  );
}

function simplifyChordProgressionSegment(text) {
  return String(text ?? '')
    .split(/(\s+)/)
    .map((segment) => {
      if (!segment || /^\s+$/.test(segment)) {
        return segment;
      }

      return BARE_CHORD_RE.test(segment)
        ? simplifyChordSymbol(segment)
        : segment;
    })
    .join('');
}

function simplifyChordProgressionText(text) {
  const source = String(text ?? '');
  let simplifiedText = '';
  let lastIndex = 0;

  for (const match of source.matchAll(PLAIN_OL_TOKEN_RE)) {
    const matchIndex = match.index ?? 0;

    simplifiedText += simplifyChordProgressionSegment(
      source.slice(lastIndex, matchIndex),
    );
    simplifiedText += match[0];
    lastIndex = matchIndex + match[0].length;
  }

  simplifiedText += simplifyChordProgressionSegment(source.slice(lastIndex));

  return simplifiedText;
}

function simplifySectionText(text, sectionKind) {
  if (
    sectionKind === 'intro' ||
    sectionKind === 'instrumental' ||
    hasChordProgressionText(text)
  ) {
    return simplifyChordProgressionText(text);
  }

  return simplifyInlineChordText(text);
}

function getAdjacentChromaticKey(keyText, stepOffset) {
  return getAdjacentChromaticKeyForConfig(
    keyText,
    stepOffset,
    CONFIG_KEY_VALUES,
  );
}

function getStructureKeyOptions(originalKeyText, selectedKeyText) {
  const parsedOriginalKey = parseMainKey(originalKeyText);
  const configKeyOptions = parsedOriginalKey
    ? CONFIG_KEY_VALUES.filter((value) => {
        return parseMainKey(value)?.isMinor === parsedOriginalKey.isMinor;
      })
    : CONFIG_KEY_VALUES;

  return Array.from(
    new Set(
      [originalKeyText, selectedKeyText, ...configKeyOptions]
        .map((value) => normalizeStructureKeyOption(value))
        .filter(Boolean),
    ),
  );
}

function createOpenLyricStructureControlState(markdown, options = {}) {
  const fences = parseOpenLyricFences(markdown);
  const configFence =
    fences.find((fence) => fence.parsedHeader.header === 'Config') || null;

  if (!configFence) {
    return null;
  }

  const configEntries = createConfigEntryMap(parseConfigEntries(configFence));
  const originalKeyText = getConfigValue(configEntries, 'Key');
  const structureKeyId = 'config-structure';
  const title = 'Default Config';
  const selectedStructureKeys =
    options.selectedStructureKeys &&
    typeof options.selectedStructureKeys === 'object'
      ? options.selectedStructureKeys
      : {};
  const selectedKeyText =
    normalizeStructureKeyOption(selectedStructureKeys[structureKeyId]) ||
    parseMainKey(originalKeyText)?.raw ||
    originalKeyText ||
    '';
  const parsedSelectedKey = parseMainKey(selectedKeyText);

  return {
    keyOptions: getStructureKeyOptions(originalKeyText, selectedKeyText),
    nextKeyText: parsedSelectedKey
      ? getAdjacentChromaticKey(selectedKeyText, 1)
      : '',
    previousKeyText: parsedSelectedKey
      ? getAdjacentChromaticKey(selectedKeyText, -1)
      : '',
    selectedKeyText,
    structureKeyId,
    title,
  };
}

function getLineNumberAtOffset(text, offset) {
  if (offset <= 0) {
    return 1;
  }

  return text.slice(0, offset).split('\n').length;
}

function getLineNumberAtEndOffset(text, endOffset) {
  if (endOffset <= 0) {
    return 1;
  }

  return getLineNumberAtOffset(text, Math.max(0, endOffset - 1));
}

function parseOpenLyricFences(markdown) {
  const normalizedMarkdown = normalizeNewlines(markdown);

  return Array.from(normalizedMarkdown.matchAll(OL_FENCE_BLOCK_RE))
    .map((match) => {
      const info = String(match[1] ?? '').trim();
      const parsedHeader = parseFenceHeader(info);

      if (!parsedHeader?.definition) {
        return null;
      }

      return {
        info,
        raw: match[0] || '',
        body: match[2] || '',
        parsedHeader,
        startLineNumber: getLineNumberAtOffset(
          normalizedMarkdown,
          match.index || 0,
        ),
        endLineNumber: getLineNumberAtEndOffset(
          normalizedMarkdown,
          (match.index || 0) + String(match[0] || '').length,
        ),
      };
    })
    .filter(Boolean);
}

function createDeclaredPartMap(fences) {
  const parts = new Map();

  fences.forEach((fence) => {
    const partName = fence.parsedHeader.partName;

    if (!partName || partName === 'Config') {
      return;
    }

    if (!parts.has(partName)) {
      parts.set(partName, fence);
    }
  });

  return parts;
}

function parseStructureSteps(structureEntry) {
  if (!structureEntry) {
    return [];
  }

  const primaryValue =
    structureEntry.values.find((value) => String(value.text ?? '').trim()) ||
    structureEntry.values[0] ||
    null;
  if (!primaryValue) {
    return [];
  }

  const parsedStructure = parseStructureValue(primaryValue.text);
  if (parsedStructure.error) {
    return [];
  }

  return parsedStructure.steps.map((step) => ({
    ...step,
    editorLine: primaryValue.lineEntry.lineNumber,
    editorColumn:
      (primaryValue.valueColumn || primaryValue.lineEntry.column) +
      step.startOffset,
  }));
}

/**
 * The `partNameFilter` view option: the one section (part) name a render is
 * scoped to, or `''` for the whole song. Callers that only need one section —
 * `getValue({ key })` / `getElementMap({ key })` on the component — pass it so
 * the pipeline never builds the rest of the song.
 */
function normalizePartNameFilter(options) {
  return String(options?.partNameFilter ?? '').trim();
}

/**
 * The structure steps a `partNameFilter` keeps: the FIRST step naming that
 * part, so a part repeated in the flow (`IV1CV2CO` plays Chorus twice) renders
 * once — the same uniqueness the section maps have. Empty when the name is not
 * in the structure at all, which renders nothing rather than the whole song.
 */
function filterStepsByPartName(steps, partNameFilter) {
  if (!partNameFilter) {
    return steps;
  }

  const match = steps.find(
    (step) => (step.partName || step.partText) === partNameFilter,
  );

  return match ? [match] : [];
}

function parseConfigEntries(configFence) {
  if (!configFence) {
    return [];
  }

  const entries = [];
  let currentEntry = null;

  for (const lineEntry of createPreviewLineEntries(configFence.body, {
    startLineNumber: configFence.startLineNumber,
  })) {
    const line = lineEntry.text;

    if (!line.trim()) {
      continue;
    }

    const fieldMatch = line.match(/^\s*-\s*([^:]+):\s*(.*)$/);
    if (fieldMatch) {
      const separatorOffset = line.indexOf(':');
      const valueOffset =
        separatorOffset === -1 ? line.length : separatorOffset + 1;
      const valueIndentLength =
        line.slice(valueOffset).match(/^\s*/)?.[0].length || 0;
      currentEntry = {
        key: normalizeConfigFieldName(fieldMatch[1]),
        lineEntry,
        values: [
          {
            text: fieldMatch[2],
            lineEntry,
            valueColumn: valueOffset + valueIndentLength + 1,
          },
        ],
      };
      entries.push(currentEntry);
      continue;
    }

    if (currentEntry) {
      currentEntry.values.push({
        text: line.trim(),
        lineEntry,
        valueColumn: lineEntry.column,
      });
    }
  }

  return entries;
}

function createConfigEntryMap(entries) {
  return new Map(entries.map((entry) => [entry.key, entry]));
}

function getPlainTextConfigValueLines(entryMap, key) {
  const entry = entryMap.get(key);
  if (!entry) {
    return [];
  }

  return entry.values
    .map((value) => normalizeInlinePlainText(value.text).trim())
    .filter(Boolean);
}

function getPlainTextConfigValue(entryMap, key) {
  return getPlainTextConfigValueLines(entryMap, key).join(' ');
}

function getConfigValueLines(entryMap, key) {
  const entry = entryMap.get(key);
  if (!entry) {
    return [];
  }

  return entry.values
    .map((value) => String(value.text ?? '').trim())
    .filter(Boolean);
}

function getConfigValue(entryMap, key) {
  return getConfigValueLines(entryMap, key).join(' ');
}

function renderTextBlock(lines) {
  if (!lines.length) {
    return '';
  }

  return lines
    .map((line) => `<span>${previewHelpers.escapeHtml(line)}</span>`)
    .join('<br>');
}

function renderMetaEntryValue(field, value) {
  const escapedField = previewHelpers.escapeHtml(field);
  const escapedValue = previewHelpers.escapeHtml(value);

  if (field !== 'Key') {
    return `<span class="ol-song-view__meta-entry"><strong>${escapedField}:</strong> ${escapedValue}</span>`;
  }

  const chordTitle = previewHelpers.escapeHtml(describeChordKey(value));

  return `<span class="ol-song-view__meta-entry"><strong>${escapedField}:</strong> <button class="ol-preview-chord ol-song-view__meta-chord" type="button" data-chord-key="${escapedValue}" data-chord-title="${chordTitle}" aria-label="Show ${chordTitle}" title="Show ${chordTitle}">${escapedValue}</button></span>`;
}

function createMetaSummaryEntries(entryMap, options = {}) {
  const keyOverride = normalizeStructureKeyOption(options.keyTextOverride);
  const metaFields = ['Key', 'Time', 'Tempo'];

  return metaFields
    .map((field) => {
      const value =
        field === 'Key'
          ? keyOverride || getConfigValue(entryMap, field)
          : getConfigValue(entryMap, field);

      if (!value) {
        return null;
      }

      return { field, value };
    })
    .filter(Boolean);
}

function createPlainTextMetaSummaryEntries(entryMap, options = {}) {
  const keyOverride = normalizeStructureKeyOption(options.keyTextOverride);
  const metaFields = ['Key', 'Time', 'Tempo'];

  return metaFields
    .map((field) => {
      const value =
        field === 'Key'
          ? keyOverride || getPlainTextConfigValue(entryMap, field)
          : getPlainTextConfigValue(entryMap, field);

      if (!value) {
        return null;
      }

      return { field, value };
    })
    .filter(Boolean);
}

function renderMetaSummary(entryMap, options = {}) {
  const items = createMetaSummaryEntries(entryMap, options).map(
    ({ field, value }) => {
      return renderMetaEntryValue(field, value);
    },
  );

  if (!items.length) {
    return '';
  }

  return `<div class="ol-song-view__meta-line">${items.join('<span class="ol-song-view__meta-separator">&middot;</span>')}</div>`;
}

function renderReadOnlyStructureValue(values) {
  if (!Array.isArray(values) || !values.length) {
    return '';
  }

  if (values.length !== 1) {
    return values
      .map((value) => {
        return `<span${previewHelpers.getEditorDataAttributes(
          value.lineEntry?.lineNumber,
          value.valueColumn || value.lineEntry?.column,
        )}>${previewHelpers.renderInlineText(value.text)}</span>`;
      })
      .join('<br>');
  }

  const [value] = values;
  const parsedStructure = parseStructureValue(value.text);
  const editorLine = value.lineEntry?.lineNumber;
  const baseColumn = value.valueColumn || value.lineEntry?.column || 1;

  if (parsedStructure.error) {
    return `<span${previewHelpers.getEditorDataAttributes(
      editorLine,
      baseColumn,
    )}>${previewHelpers.renderInlineText(value.text)}</span>`;
  }

  if (!parsedStructure.steps.length) {
    return '';
  }

  const stepHtml = parsedStructure.steps
    .map((step, index) => {
      const targetId = step.parsedHeader
        ? createSongSectionTargetId(step.partName)
        : '';
      const editorColumn = baseColumn + step.startOffset;
      const stepAttributes = `${previewHelpers.getEditorDataAttributes(
        editorLine,
        editorColumn,
      )}${
        step.header
          ? ` data-ol-header="${previewHelpers.escapeHtml(step.header)}"`
          : ''
      }`;
      const labelHtml = previewHelpers.renderInlineText(
        formatStructureStepLabel(step),
      );
      const stepLabelHtml = targetId
        ? `<a class="ol-preview-structure-step" href="#${previewHelpers.escapeHtml(targetId)}" data-preview-target-id="${previewHelpers.escapeHtml(targetId)}"${stepAttributes}>${labelHtml}</a>`
        : `<span class="ol-preview-structure-step"${stepAttributes}>${labelHtml}</span>`;

      return [
        '<span class="ol-preview-structure-link">',
        stepLabelHtml,
        index < parsedStructure.steps.length - 1
          ? '<span class="ol-preview-structure-arrow" aria-hidden="true">&rarr;</span>'
          : '',
        '</span>',
      ].join('');
    })
    .join('');

  return `<div class="ol-song-view__structure-overview-value"><div class="ol-preview-structure-line">${stepHtml}</div></div>`;
}

function renderPatternCards(entryMap, options = {}) {
  return previewHelpers.renderStrummingPatternCards(
    getConfigValueLines(entryMap, 'Strumming Patterns'),
    getConfigValue(entryMap, 'Time') || '4/4',
    {
      patterns: options.patternPreviewContext?.patterns,
      patternTargetIdPrefix: OPEN_LYRIC_PATTERN_TARGET_ID_PREFIX,
    },
  );
}

function formatRepeatText(repeatText) {
  return String(repeatText ?? '')
    .trim()
    .replace(/^\((.*)\)$/, '$1');
}

function createSongSectionTargetId(partName) {
  const previewTargetId = previewHelpers.createPreviewTargetId(partName);

  return previewTargetId
    ? previewTargetId.replace(/^ol-preview-target-/, 'ol-song-view-target-')
    : '';
}

const CONFIG_DETAIL_FIELDS = ['Theme', 'Genre', 'Style'];

function renderConfigDetailRows(entryMap) {
  const rows = CONFIG_DETAIL_FIELDS.map((field) => {
    const valueLines = getConfigValueLines(entryMap, field);

    if (!valueLines.length) {
      return '';
    }

    return [
      '<div class="ol-song-view__detail">',
      `<span class="ol-song-view__detail-label">${previewHelpers.escapeHtml(field)}:</span>`,
      `<span class="ol-song-view__detail-value">${renderTextBlock(valueLines)}</span>`,
      '</div>',
    ].join('');
  }).filter(Boolean);

  if (!rows.length) {
    return '';
  }

  return `<div class="ol-song-view__details">${rows.join('')}</div>`;
}

function renderConfigAttachments(entryMap) {
  const attachmentLines = getConfigValueLines(entryMap, 'Attachments');

  if (!attachmentLines.length) {
    return '';
  }

  const items = attachmentLines
    .map(
      (line) =>
        `<li class="ol-song-view__attachment"><span>${previewHelpers.escapeHtml(line)}</span></li>`,
    )
    .join('');

  return [
    '<div class="ol-song-view__attachments">',
    '<span class="ol-song-view__detail-label">Attachments:</span>',
    `<ul class="ol-song-view__attachment-list">${items}</ul>`,
    '</div>',
  ].join('');
}

function renderConfigHeaderMeta(entryMap, options = {}) {
  const patternsHtml = renderPatternCards(entryMap, options);
  const descriptionLines = getConfigValueLines(entryMap, 'Description');
  const copyrightText = getConfigValue(entryMap, 'Copyright');
  const proseHtml = [
    descriptionLines.length
      ? `<div class="ol-song-view__description">${renderTextBlock(descriptionLines)}</div>`
      : '',
    copyrightText
      ? `<p class="ol-song-view__copyright">${previewHelpers.escapeHtml(copyrightText)}</p>`
      : '',
  ]
    .filter(Boolean)
    .join('');
  const factsHtml = [
    renderConfigDetailRows(entryMap),
    renderConfigAttachments(entryMap),
  ]
    .filter(Boolean)
    .join('');

  const groups = [
    patternsHtml
      ? `<div class="ol-song-view__header-group ol-song-view__header-group--patterns">${patternsHtml}</div>`
      : '',
    proseHtml
      ? `<div class="ol-song-view__header-group ol-song-view__header-group--prose">${proseHtml}</div>`
      : '',
    factsHtml
      ? `<div class="ol-song-view__header-group ol-song-view__header-group--facts">${factsHtml}</div>`
      : '',
  ].filter(Boolean);

  if (!groups.length) {
    return '';
  }

  return `<div class="ol-song-view__header-meta">${groups.join('')}</div>`;
}

function renderConfigHeader(entryMap, options = {}) {
  const title = getConfigValue(entryMap, 'Title') || 'Untitled Song';
  const subtitle = getConfigValue(entryMap, 'Subtitle');
  const artist = getConfigValue(entryMap, 'Artist');
  const secondaryText = [subtitle, artist].filter(Boolean).join(' · ');

  return [
    '<header class="ol-song-view__header">',
    '<div class="ol-song-view__headline">',
    `<h4 class="ol-song-view__title">${previewHelpers.escapeHtml(title)}</h4>`,
    secondaryText
      ? `<p class="ol-song-view__subtitle">${previewHelpers.escapeHtml(secondaryText)}</p>`
      : '',
    '</div>',
    renderConfigHeaderMeta(entryMap, options),
    '</header>',
  ].join('');
}

function createSectionRenderContext(fence, transposition = null, options = {}) {
  const sourceLocation = getPreviewSourceLocation(
    fence.body,
    fence.startLineNumber,
  );
  const simplifyChords = Boolean(options.simplifyChords);
  const lineEntries = createPreviewLineEntries(fence.body, sourceLocation).map(
    (lineEntry) => {
      const transposedText = transposeSectionText(
        lineEntry.text,
        fence.parsedHeader.kind,
        transposition,
      );

      return {
        ...lineEntry,
        text: simplifyChords
          ? simplifySectionText(transposedText, fence.parsedHeader.kind)
          : transposedText,
      };
    },
  );

  return {
    fence,
    sourceLocation,
    lineEntries,
  };
}

function renderSectionBody(
  sectionContext,
  sectionPreviewHelpers = previewHelpers,
) {
  const { fence, sourceLocation, lineEntries } = sectionContext;

  return fence.parsedHeader.definition.renderPreviewBody({
    body: fence.body,
    header: fence.parsedHeader.header,
    helpers: sectionPreviewHelpers,
    kind: fence.parsedHeader.kind,
    lineEntries,
    lines: lineEntries.map((entry) => entry.text),
    parsedHeader: fence.parsedHeader,
    sourceLocation,
    targetId: createSongSectionTargetId(fence.parsedHeader.partName),
    title: fence.parsedHeader.partName,
  });
}

function isProgressionSection(sectionContext) {
  if (
    sectionContext.fence.parsedHeader.kind === 'intro' ||
    sectionContext.fence.parsedHeader.kind === 'instrumental'
  ) {
    return true;
  }

  return (
    sectionContext.fence.parsedHeader.kind === 'outro' &&
    sectionContext.lineEntries.length === 1 &&
    previewHelpers.hasChordProgressionText(sectionContext.lineEntries[0]?.text)
  );
}

function hasInlineKeyMarkers(text) {
  return /(\[[^\[\]\r\n]+\]|\{[^{}\r\n]+\}|\|\|:|\|:|:\|\||:\||\|)/.test(
    String(text ?? ''),
  );
}

function isInlinePlainTextSection(sectionContext) {
  if (sectionContext.lineEntries.length !== 1) {
    return false;
  }

  const text = String(sectionContext.lineEntries[0]?.text ?? '').trim();
  return Boolean(text) && !hasInlineKeyMarkers(text);
}

function getSongSectionDataAttributes(parsedHeader) {
  if (!parsedHeader) {
    return '';
  }

  const attributes = [];

  if (parsedHeader.kind) {
    attributes.push(
      `data-ol-kind="${previewHelpers.escapeHtml(parsedHeader.kind)}"`,
    );
  }

  if (parsedHeader.header) {
    attributes.push(
      `data-ol-header="${previewHelpers.escapeHtml(parsedHeader.header)}"`,
    );
  }

  return attributes.length ? ` ${attributes.join(' ')}` : '';
}

function getSongSectionTitleEditorDataAttributes(fence) {
  return previewHelpers.getFenceHeaderEditorDataAttributes(
    fence?.startLineNumber || '',
  );
}

function getSongSectionRangeDataAttributes(fence) {
  if (!fence?.startLineNumber || !fence?.endLineNumber) {
    return '';
  }

  return ` data-preview-start-line="${previewHelpers.escapeHtml(fence.startLineNumber)}" data-preview-end-line="${previewHelpers.escapeHtml(fence.endLineNumber)}"`;
}

function getSongSectionPartDataAttributes(partName) {
  const normalizedPartName = String(partName ?? '').trim();

  if (!normalizedPartName) {
    return '';
  }

  return ` data-ol-part-name="${previewHelpers.escapeHtml(normalizedPartName)}"`;
}

function getMissingSectionTitleEditorDataAttributes(step) {
  return previewHelpers.getEditorDataAttributes(
    step?.editorLine || '',
    step?.editorColumn || 1,
  );
}

function renderMissingSection(step) {
  const partName = step.partName || step.partText;
  const repeatText = formatRepeatText(step.repeatText);
  const sectionDataAttributes = getSongSectionDataAttributes(step.parsedHeader);
  const sectionTargetId = createSongSectionTargetId(partName);
  const titleEditorAttributes =
    getMissingSectionTitleEditorDataAttributes(step);

  return [
    `<section class="ol-song-view__section ol-song-view__section--missing"${sectionTargetId ? ` id="${previewHelpers.escapeHtml(sectionTargetId)}"` : ''}${sectionDataAttributes}${getSongSectionPartDataAttributes(partName)}>`,
    '<div class="ol-song-view__section-line">',
    `<h2 class="ol-song-view__section-title"${titleEditorAttributes}>${previewHelpers.escapeHtml(partName)}:</h2>`,
    repeatText
      ? `<span class="ol-preview-repeat ol-song-view__repeat">${previewHelpers.escapeHtml(repeatText)}</span>`
      : '',
    '</div>',
    `<div class="ol-song-view__section-body"><div class="ol-song-view__missing-note">Missing declared part for ${previewHelpers.escapeHtml(partName)}.</div></div>`,
    '</section>',
  ].join('');
}

function renderSongSection(step, partMap, transposition = null, options = {}) {
  const partName = step.partName || step.partText;
  const fence = partMap.get(partName);

  if (!fence) {
    return renderMissingSection(step);
  }

  const sectionContext = createSectionRenderContext(
    fence,
    transposition,
    options,
  );
  const sectionPreviewHelpers = options.previewHelpers || previewHelpers;
  const sectionBody = renderSectionBody(sectionContext, sectionPreviewHelpers);
  const repeatText = formatRepeatText(step.repeatText);
  const inlineProgression =
    isProgressionSection(sectionContext) &&
    sectionContext.lineEntries.length === 1;
  const inlinePlainText = isInlinePlainTextSection(sectionContext);
  const inlineSection = inlineProgression || inlinePlainText;
  const sectionDataAttributes = getSongSectionDataAttributes(
    fence.parsedHeader,
  );
  const sectionTargetId = createSongSectionTargetId(partName);
  const titleEditorAttributes = getSongSectionTitleEditorDataAttributes(fence);
  const classNames = inlineSection
    ? 'ol-song-view__section ol-song-view__section--inline'
    : 'ol-song-view__section';

  return [
    `<section class="${classNames}"${sectionTargetId ? ` id="${previewHelpers.escapeHtml(sectionTargetId)}"` : ''}${sectionDataAttributes}${getSongSectionPartDataAttributes(partName)}${getSongSectionRangeDataAttributes(fence)}>`,
    `<div class="ol-song-view__section-line${inlineProgression ? ' ol-song-view__section-line--inline' : ''}${inlinePlainText ? ' ol-song-view__section-line--inline-text' : ''}">`,
    `<h2 class="ol-song-view__section-title"${titleEditorAttributes}>${previewHelpers.escapeHtml(partName)}:</h2>`,
    repeatText
      ? `<span class="ol-preview-repeat ol-song-view__repeat">${previewHelpers.escapeHtml(repeatText)}</span>`
      : '',
    inlineSection
      ? `<div class="ol-song-view__section-inline-body${inlinePlainText ? ' ol-song-view__section-inline-body--text' : ''}">${sectionBody}</div>`
      : '',
    '</div>',
    inlineSection
      ? ''
      : `<div class="ol-song-view__section-body">${sectionBody}</div>`,
    '</section>',
  ].join('');
}

function renderSongSections(
  steps,
  partMap,
  transposition = null,
  options = {},
) {
  const sectionPreviewHelpers = options.previewHelpers || previewHelpers;

  if (!steps.length) {
    return '<div class="ol-song-view__empty">Add a valid - Structure: code to ol:Config to render the song flow.</div>';
  }

  return [
    '<div class="ol-song-view__sections">',
    ...steps.map((step) =>
      renderSongSection(step, partMap, transposition, {
        ...options,
        previewHelpers: sectionPreviewHelpers,
      }),
    ),
    '</div>',
  ].join('');
}

function renderOpenLyricPreviewSectionsForLine(
  markdown,
  lineNumber,
  options = {},
) {
  const targetLineNumber = Number(lineNumber);

  if (!Number.isInteger(targetLineNumber) || targetLineNumber < 1) {
    return null;
  }

  const fences = parseOpenLyricFences(markdown);
  const configFence =
    fences.find((fence) => fence.parsedHeader.header === 'Config') || null;

  if (!configFence) {
    return null;
  }

  const affectedFence = fences.find((fence) => {
    return (
      fence.parsedHeader.header !== 'Config' &&
      targetLineNumber >= fence.startLineNumber &&
      targetLineNumber <= fence.endLineNumber
    );
  });

  if (!affectedFence?.parsedHeader?.partName) {
    return null;
  }

  const configEntries = createConfigEntryMap(parseConfigEntries(configFence));
  const partMap = createDeclaredPartMap(fences);
  const structureEntry = configEntries.get('Structure') || null;
  const steps = parseStructureSteps(structureEntry).filter((step) => {
    return (
      (step.partName || step.partText) === affectedFence.parsedHeader.partName
    );
  });

  if (!steps.length) {
    return null;
  }

  const resolvedOptions = {
    ...options,
    patternPreviewContext:
      options.patternPreviewContext ||
      createStrummingPatternPreviewContextFromConfigBody(configFence.body),
  };
  const originalKeyText = getConfigValue(configEntries, 'Key');
  const parsedOriginalKey = parseMainKey(originalKeyText);
  const selectedStructureKeys =
    resolvedOptions.selectedStructureKeys &&
    typeof resolvedOptions.selectedStructureKeys === 'object'
      ? resolvedOptions.selectedStructureKeys
      : {};
  const structureKeyId = 'config-structure';
  const selectedKeyText =
    normalizeStructureKeyOption(selectedStructureKeys[structureKeyId]) ||
    parsedOriginalKey?.raw ||
    '';
  const transposition = createChordTransposition(
    parsedOriginalKey?.raw || '',
    selectedKeyText,
  );
  const sectionPreviewHelpers = createPreviewHelpers({
    hideBracketedKeys: Boolean(resolvedOptions.hideBracketedKeys),
    hideLeadingBars: Boolean(resolvedOptions.hideLeadingBars),
    patternPreviewContext: resolvedOptions.patternPreviewContext,
    patternPreviewTargetIdPrefix: OPEN_LYRIC_PATTERN_TARGET_ID_PREFIX,
  });

  return {
    header: affectedFence.parsedHeader.header,
    partName: affectedFence.parsedHeader.partName,
    html: steps
      .map((step) =>
        renderSongSection(step, partMap, transposition, {
          ...resolvedOptions,
          previewHelpers: sectionPreviewHelpers,
        }),
      )
      .join(''),
  };
}

function trimPlainTextLines(lines) {
  const normalizedLines = Array.isArray(lines)
    ? lines.map((line) => String(line ?? '').replace(/\s+$/g, ''))
    : [];
  let startIndex = 0;
  let endIndex = normalizedLines.length;

  while (
    startIndex < endIndex &&
    !String(normalizedLines[startIndex] ?? '').trim()
  ) {
    startIndex += 1;
  }

  while (
    endIndex > startIndex &&
    !String(normalizedLines[endIndex - 1] ?? '').trim()
  ) {
    endIndex -= 1;
  }

  return normalizedLines.slice(startIndex, endIndex);
}

function getSectionPlainTextBodyLines(sectionContext, options = {}) {
  const bodyLines = trimPlainTextLines(
    sectionContext.lineEntries.map((lineEntry) => lineEntry.text),
  ).map((line) => normalizeInlinePlainText(line).trimStart());

  // Same rule the preview follows: with keys hidden, a line that is nothing but
  // a key note (an Intro/Outro progression) leaves with them.
  if (!options.hideBracketedKeys) {
    return bodyLines;
  }

  return trimPlainTextLines(
    bodyLines.filter((line) => !isChordOnlyLineText(line)),
  );
}

function formatPlainTextRepeatSuffix(repeatText) {
  const normalizedRepeatText = formatRepeatText(repeatText);

  return normalizedRepeatText ? ` (${normalizedRepeatText})` : '';
}

function createMissingSectionPlainTextData(step) {
  const partName = step.partName || step.partText || 'Untitled Part';
  const repeatText = formatRepeatText(step.repeatText);

  return {
    partName,
    repeatText,
    heading: `${partName}:${formatPlainTextRepeatSuffix(step.repeatText)}`,
    isInline: false,
    lineGroups: [[`Missing declared part for ${partName}.`]],
  };
}

function createSongSectionPlainTextData(sectionContext, step, options = {}) {
  const partName = step.partName || step.partText || 'Untitled Part';
  const repeatText = formatRepeatText(step.repeatText);
  const heading = `${partName}:${formatPlainTextRepeatSuffix(step.repeatText)}`;
  const bodyLines = getSectionPlainTextBodyLines(sectionContext, options);
  const inlineProgression =
    isProgressionSection(sectionContext) && bodyLines.length === 1;
  const inlinePlainText =
    isInlinePlainTextSection(sectionContext) && bodyLines.length === 1;

  if (!bodyLines.length) {
    return {
      partName,
      repeatText,
      heading,
      isInline: false,
      lineGroups: [],
    };
  }

  if (inlineProgression || inlinePlainText) {
    return {
      partName,
      repeatText,
      heading,
      isInline: true,
      lineGroups: [[bodyLines[0]]],
    };
  }

  return {
    partName,
    repeatText,
    heading,
    isInline: false,
    lineGroups: bodyLines.map((line) => {
      if (!line) {
        return [''];
      }

      return createChordedLyricTextLines(line, {
        hideBracketedKeys: Boolean(options.hideBracketedKeys),
        hideLeadingBars: Boolean(options.hideLeadingBars),
      });
    }),
  };
}

function renderSongSectionPlainTextData(sectionData) {
  if (!sectionData) {
    return '';
  }

  const lineGroups = Array.isArray(sectionData.lineGroups)
    ? sectionData.lineGroups
    : [];
  const lines = lineGroups.flatMap((group) => {
    if (!Array.isArray(group) || !group.length) {
      return [''];
    }

    return group.map((line) => String(line ?? ''));
  });

  if (!lines.length) {
    return sectionData.heading;
  }

  if (sectionData.isInline && lines.length === 1) {
    return `${sectionData.heading} ${lines[0]}`;
  }

  return [
    sectionData.heading,
    ...lines.map((line) => {
      if (!line) {
        return '';
      }

      return `  ${line}`;
    }),
  ].join('\n');
}

function createSongSectionsPlainTextData(
  steps,
  partMap,
  transposition = null,
  options = {},
) {
  if (!steps.length) {
    return [];
  }

  return steps.map((step) => {
    const partName = step.partName || step.partText;
    const fence = partMap.get(partName);

    if (!fence) {
      return createMissingSectionPlainTextData(step);
    }

    const sectionContext = createSectionRenderContext(
      fence,
      transposition,
      options,
    );

    return createSongSectionPlainTextData(sectionContext, step, options);
  });
}

function createPlainTextStructureLine(structureEntry, parsedSteps = null) {
  const steps = Array.isArray(parsedSteps)
    ? parsedSteps
    : parseStructureSteps(structureEntry);

  if (steps.length) {
    return `Structure: ${steps
      .map((step) => step.partName || step.partText || 'Untitled Part')
      .join(' - ')}`;
  }

  const rawStructureValue = Array.isArray(structureEntry?.values)
    ? structureEntry.values
        .map((value) => normalizeInlinePlainText(value.text).trim())
        .filter(Boolean)
        .join(' ')
    : '';

  return rawStructureValue ? `Structure: ${rawStructureValue}` : '';
}

function createPlainTextStrummingPatternLines(entryMap, options = {}) {
  const entry = entryMap.get('Strumming Patterns');
  if (!entry) {
    return [];
  }

  const sourcePatterns = Array.isArray(options.patterns)
    ? options.patterns
    : parseStrummingPatterns(
        entry.values.map((value) => ({
          ...value,
          text: normalizeInlinePlainText(value.text),
        })),
      );
  const patterns = sourcePatterns.map((pattern) => ({
    ...pattern,
    label: normalizeInlinePlainText(pattern.label).trim(),
    pattern: normalizeStrummingPatternValue(
      normalizeInlinePlainText(pattern.pattern),
      pattern.allowZwspSeparators,
    ).trim(),
  }));

  if (
    patterns.length === 1 &&
    !Number.isInteger(patterns[0].labelSourceIndex)
  ) {
    return [`Strumming Pattern: ${patterns[0].pattern}`];
  }

  if (patterns.length) {
    return [
      'Strumming Patterns:',
      ...patterns
        .filter((pattern) => pattern.pattern)
        .map((pattern) => {
          return `  ${pattern.label ? `${pattern.label}: ${pattern.pattern}` : pattern.pattern}`;
        }),
    ];
  }

  const rawLines = getPlainTextConfigValueLines(entryMap, 'Strumming Patterns')
    .map((line) => normalizeStrummingPatternValue(line).trim())
    .filter(Boolean);

  if (!rawLines.length) {
    return [];
  }

  if (rawLines.length === 1) {
    return [`Strumming Pattern: ${rawLines[0]}`];
  }

  return ['Strumming Patterns:', ...rawLines.map((line) => `  ${line}`)];
}

function createPlainTextConfigFieldBlock(
  field,
  valueLines,
  { alwaysExpanded = false } = {},
) {
  const normalizedLines = Array.isArray(valueLines)
    ? valueLines.map((line) => String(line ?? '').trim()).filter(Boolean)
    : [];

  if (!normalizedLines.length) {
    return [];
  }

  if (!alwaysExpanded && normalizedLines.length === 1) {
    return [`- ${field}: ${normalizedLines[0]}`];
  }

  return [`- ${field}:`, ...normalizedLines.map((line) => `  ${line}`)];
}

function createPlainTextAdditionalConfigLines(entryMap) {
  const descriptionLines = getPlainTextConfigValueLines(
    entryMap,
    'Description',
  );
  const copyrightText = getPlainTextConfigValue(entryMap, 'Copyright');
  const themeText = getPlainTextConfigValue(entryMap, 'Theme');
  const genreText = getPlainTextConfigValue(entryMap, 'Genre');
  const styleText = getPlainTextConfigValue(entryMap, 'Style');
  const attachmentLines = getPlainTextConfigValueLines(entryMap, 'Attachments');

  return [
    ...createPlainTextConfigFieldBlock('Description', descriptionLines),
    ...(copyrightText ? [`- Copyright: ${copyrightText}`] : []),
    ...(themeText ? [`- Theme: ${themeText}`] : []),
    ...(genreText ? [`- Genre: ${genreText}`] : []),
    ...(styleText ? [`- Style: ${styleText}`] : []),
    ...createPlainTextConfigFieldBlock('Attachments', attachmentLines, {
      alwaysExpanded: true,
    }),
  ];
}

function createOpenLyricPresentationData(markdown, options = {}) {
  const fences = parseOpenLyricFences(markdown);
  const configFence =
    fences.find((fence) => fence.parsedHeader.header === 'Config') || null;

  if (!configFence) {
    return null;
  }

  const configEntries = createConfigEntryMap(parseConfigEntries(configFence));
  const patternPreviewContext =
    createStrummingPatternPreviewContextFromConfigBody(configFence.body);
  const partMap = createDeclaredPartMap(fences);
  const structureEntry = configEntries.get('Structure') || null;
  const originalKeyText = getConfigValue(configEntries, 'Key');
  const parsedOriginalKey = parseMainKey(originalKeyText);
  const selectedStructureKeys =
    options.selectedStructureKeys &&
    typeof options.selectedStructureKeys === 'object'
      ? options.selectedStructureKeys
      : {};
  const structureKeyId = 'config-structure';
  const selectedKeyText =
    normalizeStructureKeyOption(selectedStructureKeys[structureKeyId]) ||
    parsedOriginalKey?.raw ||
    originalKeyText;
  const transposition = createChordTransposition(
    parsedOriginalKey?.raw || '',
    selectedKeyText,
  );
  const allSteps = parseStructureSteps(structureEntry);
  // Scoped to one part when `partNameFilter` asks for it, so only that
  // section's lines are built. The song-level lines below still describe the
  // whole song — a filter narrows the sections, it does not rewrite the song.
  const steps = filterStepsByPartName(
    allSteps,
    normalizePartNameFilter(options),
  );
  const strummingPatternLines = createPlainTextStrummingPatternLines(
    configEntries,
    {
      patterns: patternPreviewContext?.patterns,
    },
  );
  const structureLine = createPlainTextStructureLine(structureEntry, allSteps);
  const title =
    getPlainTextConfigValue(configEntries, 'Title') || 'Untitled Song';
  const subtitle = getPlainTextConfigValue(configEntries, 'Subtitle');
  const artist = getPlainTextConfigValue(configEntries, 'Artist');
  const secondaryText = [subtitle, artist].filter(Boolean).join(' · ');
  const metaLine = createPlainTextMetaSummaryEntries(configEntries, {
    keyTextOverride: selectedKeyText,
  })
    .map(({ field, value }) => `${field}: ${value}`)
    .join(', ');
  const configFieldLines = createPlainTextAdditionalConfigLines(configEntries);

  return {
    configFieldLines,
    title,
    secondaryText,
    metaLine,
    strummingPatternLines,
    structureLine,
    sections: createSongSectionsPlainTextData(steps, partMap, transposition, {
      hideBracketedKeys: Boolean(options.hideBracketedKeys),
      hideLeadingBars: Boolean(options.hideLeadingBars),
      simplifyChords: Boolean(options.simplifyChords),
    }),
  };
}

function renderOpenLyricPlainText(markdown, options = {}) {
  const presentationData = createOpenLyricPresentationData(markdown, options);

  if (!presentationData) {
    return '';
  }

  // Scoped to one section: the song-level header (title, meta, structure) is
  // not part of that section, so a filtered render leaves it out entirely.
  const headerBlock = normalizePartNameFilter(options)
    ? ''
    : [
        presentationData.title,
        presentationData.secondaryText,
        presentationData.metaLine,
        ...(Array.isArray(presentationData.strummingPatternLines)
          ? presentationData.strummingPatternLines
          : []),
        presentationData.structureLine,
        ...(Array.isArray(presentationData.configFieldLines)
          ? presentationData.configFieldLines
          : []),
      ]
        .filter(Boolean)
        .join('\n');
  const sectionsBlock = presentationData.sections
    .map((sectionData) => renderSongSectionPlainTextData(sectionData))
    .filter(Boolean)
    .join('\n\n');

  return [headerBlock, sectionsBlock].filter(Boolean).join('\n\n').trim();
}

function renderConfigStructureCollection(entryMap, partMap, options = {}) {
  const structureEntry = entryMap.get('Structure') || null;

  const originalKeyText = getConfigValue(entryMap, 'Key');
  const parsedOriginalKey = parseMainKey(originalKeyText);
  const selectedStructureKeys =
    options.selectedStructureKeys &&
    typeof options.selectedStructureKeys === 'object'
      ? options.selectedStructureKeys
      : {};
  const structureKeyId = 'config-structure';
  const selectedKeyText =
    normalizeStructureKeyOption(selectedStructureKeys[structureKeyId]) ||
    parsedOriginalKey?.raw ||
    '';
  const metaSummary = renderMetaSummary(entryMap, {
    keyTextOverride: selectedKeyText,
  });
  const structureOverview = structureEntry
    ? renderReadOnlyStructureValue(structureEntry.values)
    : '';
  const hideBracketedKeys = Boolean(options.hideBracketedKeys);
  const simplifyChords = Boolean(options.simplifyChords);
  const hideLeadingBars = Boolean(options.hideLeadingBars);
  const sectionPreviewHelpers = createPreviewHelpers({
    hideBracketedKeys,
    hideLeadingBars,
    patternPreviewContext: options.patternPreviewContext || null,
    patternPreviewTargetIdPrefix: OPEN_LYRIC_PATTERN_TARGET_ID_PREFIX,
  });
  const transposition = createChordTransposition(
    parsedOriginalKey?.raw || '',
    selectedKeyText,
  );
  const partNameFilter = normalizePartNameFilter(options);
  const steps = filterStepsByPartName(
    parseStructureSteps(structureEntry),
    partNameFilter,
  );

  // A filter that matches nothing renders nothing — never the whole song, and
  // never `renderSongSections`' "add a Structure" placeholder, which would be
  // about the song rather than about the missing part.
  if (partNameFilter && !steps.length) {
    return '';
  }

  // Scoped to one section: the structure's own meta summary and overview
  // describe the whole song, so a filtered render drops them with the header.
  const structureBody = partNameFilter
    ? ''
    : `${metaSummary ? '<div class="ol-song-view__structure-meta">' + metaSummary + '</div>' : ''}${structureOverview ? '<div class="ol-song-view__structure-overview">' + structureOverview + '</div>' : ''}`;

  return [
    '<div class="ol-song-view__structures">',
    [
      `<div class="ol-song-view__structure" data-structure-key-id="${previewHelpers.escapeHtml(structureKeyId)}">`,
      `<div class="ol-song-view__structure-body">${structureBody}${renderSongSections(steps, partMap, transposition, { simplifyChords, previewHelpers: sectionPreviewHelpers })}</div>`,
      '</div>',
    ].join(''),
    '</div>',
  ].join('');
}

function renderOpenLyricPreviewHtml(markdown, context = {}) {
  const options =
    context.viewOptions && typeof context.viewOptions === 'object'
      ? context.viewOptions
      : {};
  const fences = parseOpenLyricFences(markdown);
  const configFence =
    fences.find((fence) => fence.parsedHeader.header === 'Config') || null;
  const configEntries = createConfigEntryMap(parseConfigEntries(configFence));
  const partMap = createDeclaredPartMap(fences);

  if (!configFence) {
    return '<div class="ol-song-view__empty">Add an ol:Config fence to render the Open Lyric view.</div>';
  }

  const resolvedOptions = {
    ...options,
    patternPreviewContext:
      options.patternPreviewContext ||
      createStrummingPatternPreviewContextFromConfigBody(configFence.body),
  };

  const sections = renderConfigStructureCollection(
    configEntries,
    partMap,
    resolvedOptions,
  );

  // Scoped to one section: no song header either — and nothing at all when the
  // name is not in the structure, so a caller asking for a part this song does
  // not have gets an empty render instead of the whole song.
  if (normalizePartNameFilter(resolvedOptions)) {
    return sections
      ? ['<section class="ol-song-view">', sections, '</section>'].join('')
      : '';
  }

  return [
    '<section class="ol-song-view">',
    renderConfigHeader(configEntries, resolvedOptions),
    sections,
    '</section>',
  ].join('');
}

const openLyricPreviewParser = new OLParser({
  marked: renderOpenLyricPreviewHtml,
  beforeMarked: normalizeNewlines,
  afterMarked: renderOpenLyricInlineMarkdown,
});

function renderOpenLyricPreview(markdown, options = {}) {
  return openLyricPreviewParser.parse(markdown, {
    context: {
      viewOptions: options,
    },
  });
}

export {
  createOpenLyricPresentationData,
  createOpenLyricStructureControlState,
  renderOpenLyricPlainText,
  renderOpenLyricPreview,
  renderOpenLyricPreviewSectionsForLine,
  renderSongSectionPlainTextData,
};
