/**
 * Confine a host-supplied stylesheet to one element's subtree.
 *
 * The image getters' `css` override has to reach the off-screen export surface
 * and nothing else. The shadow root that surface is staged in (see
 * `export-stage.ts`) is what makes that airtight — a `<style>` inside a shadow
 * tree cannot style anything outside it. This is the second layer: within that
 * tree the surface shares the stage with the replicated document stylesheets,
 * and on the fallback path (an engine with no shadow DOM, where the stage IS
 * the live document) it is the only layer — there a plain `<style>` carrying
 * `.ol-song-view__section-title { display: none }` would repaint the visible
 * preview, and every other embed on the page, for the duration of the raster.
 *
 * The rewrite runs through the browser's own CSS parser rather than regexes
 * over the source text: the rules are parsed by a `<style>` element whose
 * `media` matches nothing (parsed, never applied), each selector is prefixed
 * with the scope, and the probe is dropped again.
 */

/** Marks the scoped root; the generated selectors key off this attribute. */
const SCOPE_ATTRIBUTE = 'data-ol-css-scope';

/** Rule types, by the numeric `CSSRule.type` every engine still reports. */
const STYLE_RULE = 1;
const MEDIA_RULE = 4;
const SUPPORTS_RULE = 12;

let scopeSeed = 0;

/**
 * Stamp `root` with a fresh scope marker and append a `<style>` carrying `css`
 * rewritten to apply inside `root` only. Returns the injected element (removed
 * with the root it lives in), or `null` when there is nothing to inject.
 *
 * The scoped sheet wins over the preview stylesheet by specificity, but NOT
 * over the inline styles the components set themselves (the chord and section
 * title colours); those take `!important` to override.
 */
export function attachScopedStyle(
  root: HTMLElement,
  css: string,
): HTMLStyleElement | null {
  const source = String(css ?? '').trim();
  const document_ = root.ownerDocument;
  if (!source || !document_) {
    return null;
  }

  scopeSeed += 1;
  const scopeId = `ol-css-${scopeSeed}`;
  root.setAttribute(SCOPE_ATTRIBUTE, scopeId);

  const style = document_.createElement('style');
  style.textContent = scopeCssText(
    source,
    `[${SCOPE_ATTRIBUTE}="${scopeId}"]`,
    document_,
  );
  root.append(style);
  return style;
}

/**
 * `css` with every selector rewritten to match inside `scopeSelector` only.
 *
 * A selector that can attach to the scope root (`.card`, `[data-x]`, `:hover`)
 * yields both forms — `scope sel` and `scope+sel` — so a rule can restyle the
 * export surface itself as well as what it contains. A leading `&` names the
 * scope root explicitly.
 */
export function scopeCssText(
  css: string,
  scopeSelector: string,
  document_: Document = document,
): string {
  const probe = document_.createElement('style');
  // Parsed, never applied — nothing can flash on the live page while the rules
  // are being read back.
  probe.media = 'not all';
  probe.textContent = css;
  document_.head.append(probe);
  try {
    const rules = probe.sheet?.cssRules;
    if (!rules) {
      return fallbackScope(css, scopeSelector);
    }
    return Array.from(rules)
      .map((rule) => scopeRule(rule, scopeSelector))
      .filter(Boolean)
      .join('\n');
  } catch {
    return fallbackScope(css, scopeSelector);
  } finally {
    probe.remove();
  }
}

/**
 * With no readable rules to rewrite, hand the scoping to the engine itself.
 * `@scope` either applies or is dropped whole — which is the point: the rules
 * must never reach the page unscoped, so "not applied" is the safe failure.
 */
function fallbackScope(css: string, scopeSelector: string): string {
  return `@scope (${scopeSelector}) {\n${css}\n}`;
}

/** One parsed rule, re-serialized with its selectors scoped. */
function scopeRule(rule: CSSRule, scopeSelector: string): string {
  if (rule.type === STYLE_RULE) {
    const styleRule = rule as CSSStyleRule;
    const declarations = styleRule.style?.cssText?.trim() ?? '';
    // CSS Nesting: nested rules are relative to their parent, so scoping the
    // parent scopes them too — they only have to survive the re-serialization
    // (`style.cssText` covers the declarations alone).
    const nested = Array.from(
      (styleRule as unknown as { cssRules?: CSSRuleList }).cssRules ?? [],
    )
      .map((child) => child.cssText)
      .join('\n');
    if (!declarations && !nested) {
      return '';
    }
    const selector = scopeSelectorList(styleRule.selectorText, scopeSelector);
    if (!selector) {
      return '';
    }
    return `${selector} {\n${[declarations, nested].filter(Boolean).join('\n')}\n}`;
  }

  if (rule.type === MEDIA_RULE || rule.type === SUPPORTS_RULE) {
    const group = rule as CSSGroupingRule;
    const inner = Array.from(group.cssRules ?? [])
      .map((child) => scopeRule(child, scopeSelector))
      .filter(Boolean)
      .join('\n');
    if (!inner) {
      return '';
    }
    const condition =
      rule.type === MEDIA_RULE
        ? `@media ${(rule as CSSMediaRule).media?.mediaText ?? 'all'}`
        : `@supports ${(rule as CSSSupportsRule).conditionText}`;
    return `${condition} {\n${inner}\n}`;
  }

  // `@font-face`, `@keyframes`, `@import`, … carry no selectors to scope, and
  // are document-wide by nature; pass them through as written.
  return rule.cssText ?? '';
}

/** Scope every selector in a comma-separated list. */
function scopeSelectorList(
  selectorText: string,
  scopeSelector: string,
): string {
  return splitSelectorList(selectorText)
    .flatMap((selector) => scopeSelector_(selector, scopeSelector))
    .join(', ');
}

function scopeSelector_(selector: string, scopeSelector: string): string[] {
  const trimmed = selector.trim();
  if (!trimmed) {
    return [];
  }
  if (trimmed.startsWith('&')) {
    return [`${scopeSelector}${trimmed.slice(1)}`];
  }
  // A selector whose first compound is a class / id / attribute / pseudo can
  // also describe the scope root itself, so both forms are emitted. A type
  // selector (`div`) cannot be concatenated onto one, so it stays a descendant.
  return /^[.#[:]/u.test(trimmed)
    ? [`${scopeSelector} ${trimmed}`, `${scopeSelector}${trimmed}`]
    : [`${scopeSelector} ${trimmed}`];
}

/**
 * Split a selector list on its top-level commas only — the ones inside
 * `:is(a, b)`, `[title="a,b"]`, or a functional pseudo belong to that selector.
 */
function splitSelectorList(selectorText: string): string[] {
  const parts: string[] = [];
  let current = '';
  let depth = 0;
  let quote = '';

  for (const char of String(selectorText ?? '')) {
    if (quote) {
      current += char;
      if (char === quote) {
        quote = '';
      }
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      current += char;
      continue;
    }
    if (char === '(' || char === '[') {
      depth += 1;
    } else if (char === ')' || char === ']') {
      depth = Math.max(0, depth - 1);
    } else if (char === ',' && depth === 0) {
      parts.push(current);
      current = '';
      continue;
    }
    current += char;
  }
  parts.push(current);

  return parts.map((part) => part.trim()).filter(Boolean);
}
