import olDialogsStylesheetUrl from '../../styles/dialogs.scss?url';
import olPreviewStylesheetUrl from '../../styles/preview.scss?url';
import olResponsiveStylesheetUrl from '../../styles/responsive.scss?url';
import olShellStylesheetUrl from '../../styles/shell.scss?url';
import olThemeStylesheetUrl from '../../styles/theme.scss?url';

/**
 * The app-page shell stylesheets, installed by the surface classes'
 * `installShellStyle()` statics the same way `installShellMarkup()` installs
 * the shell markup: the class that owns a piece of chrome is what puts its
 * CSS on the page, so the HTML pages ship no `<link rel="stylesheet">` of
 * their own (they carry only a splash and the `dashboardShell` mount).
 *
 * Every sheet is a `<link>` (not inlined CSS) via the same reasoning as
 * `font-styles.ts`: the compiled sheets stay cacheable stylesheet requests
 * and out of the JS bundle, and each injection is keyed by element id so any
 * number of surface classes can ask for the same sheet and share one node.
 *
 * **Order is load-bearing.** The sheets cascade at equal specificity in
 * places — `responsive.scss`'s narrow-viewport rules override `shell.scss`
 * and `preview.scss` selectors purely by document order — so the canonical
 * sequence below (theme → shell → preview → dialogs → responsive, exactly the
 * order the pages used to link) must survive whatever order the classes
 * install in. `injectShellStylesheets` therefore never plain-appends: a sheet
 * is inserted before the first already-present sheet that follows it in the
 * canonical list.
 */

type ShellStylesheetKey =
  'theme' | 'shell' | 'preview' | 'dialogs' | 'responsive';

const SHELL_STYLESHEETS: ReadonlyArray<{
  key: ShellStylesheetKey;
  id: string;
  url: string;
}> = [
  {
    key: 'theme',
    id: 'open-lyric-shell-theme-styles',
    url: olThemeStylesheetUrl,
  },
  {
    key: 'shell',
    id: 'open-lyric-shell-styles',
    url: olShellStylesheetUrl,
  },
  {
    key: 'preview',
    id: 'open-lyric-shell-preview-styles',
    url: olPreviewStylesheetUrl,
  },
  {
    key: 'dialogs',
    id: 'open-lyric-shell-dialog-styles',
    url: olDialogsStylesheetUrl,
  },
  {
    key: 'responsive',
    id: 'open-lyric-shell-responsive-styles',
    url: olResponsiveStylesheetUrl,
  },
];

/** Head markers for the shell stylesheet links, keyed by sheet. */
export const SHELL_STYLE_ELEMENT_IDS: Readonly<
  Record<ShellStylesheetKey, string>
> = Object.fromEntries(
  SHELL_STYLESHEETS.map((sheet) => [sheet.key, sheet.id]),
) as Record<ShellStylesheetKey, string>;

/**
 * Link the requested shell stylesheets into `document.head`, idempotently and
 * in canonical order (see the module note). SSR-safe like `injectStyleOnce`:
 * with no `document` it does nothing.
 */
function injectShellStylesheets(keys: readonly ShellStylesheetKey[]): void {
  if (typeof document === 'undefined') {
    return;
  }

  const requested = new Set(keys);

  for (const [index, sheet] of SHELL_STYLESHEETS.entries()) {
    if (!requested.has(sheet.key) || document.getElementById(sheet.id)) {
      continue;
    }

    const link = document.createElement('link');
    link.id = sheet.id;
    link.rel = 'stylesheet';
    link.href = sheet.url;

    const nextPresent = SHELL_STYLESHEETS.slice(index + 1)
      .map((later) => document.getElementById(later.id))
      .find((element) => element !== null);

    if (nextPresent?.parentNode) {
      nextPresent.parentNode.insertBefore(link, nextPresent);
    } else {
      document.head.append(link);
    }
  }
}

/**
 * The dashboard shell's sheets: the page-level theme tokens + loading splash
 * (`theme.scss`), the shell chrome for all four scopes (`shell.scss`), the
 * app-level dialogs (`dialogs.scss`), and the narrow-viewport overrides
 * (`responsive.scss`). `OpenLyricDashboard.installShellStyle()`.
 */
export function ensureDashboardShellStylesInjected(): void {
  injectShellStylesheets(['theme', 'shell', 'dialogs', 'responsive']);
}

/**
 * The editor panel's sheets — its chrome lives in `shell.scss` (with the
 * theme tokens it consumes and the responsive overrides that reflow it).
 * `Editor.installShellStyle()`; the Latin font faces come separately via
 * `ensureFontFacesInjected`.
 */
export function ensureEditorShellStylesInjected(): void {
  injectShellStylesheets(['theme', 'shell', 'responsive']);
}

/**
 * A preview panel's sheets: the shared shell/panel chrome plus the render
 * styles (`preview.scss` — the markdown render root, the Open Lyric song
 * view, and the Monaco popup sizing). `OpenLyric.installShellStyle()` and
 * `OpenLyricMarkdownManager.installShellStyle()`.
 */
export function ensurePreviewShellStylesInjected(): void {
  injectShellStylesheets(['theme', 'shell', 'preview', 'responsive']);
}
