import { EditorPreferencesStore } from './app/EditorPreferencesStore.ts';
import {
  bootstrapMobileEruda,
  isLikelyMobileBrowser,
  shouldBootstrapMobileEruda,
} from './mobile-eruda.ts';
import { installPlainTextCopyHandler } from './plain-text-copy.ts';
import { getOpenLyricThemeBase } from '../components/internal/theme.ts';
import { DEFAULT_THEME } from './shared.ts';

const SYSTEM_DARK_THEME_MEDIA_QUERY = '(prefers-color-scheme: dark)';

const MOBILE_VIEWPORT_CONTENT = [
  'width=device-width',
  'initial-scale=1.0',
  'maximum-scale=1.0',
  'user-scalable=no',
].join(', ');
const MOBILE_GESTURE_ZOOM_EVENTS = [
  'gesturestart',
  'gesturechange',
  'gestureend',
];

type ClipboardWriteItemLike = {
  readonly types?: ArrayLike<string> | Iterable<string>;
  getType?: (type: string) => Promise<Blob>;
  [key: string]: unknown;
};

async function resolveClipboardPlainText(
  clipboardItem: ClipboardWriteItemLike,
) {
  const availableTypes = Array.from(clipboardItem.types || []);

  if (
    availableTypes.includes('text/plain') &&
    typeof clipboardItem.getType === 'function'
  ) {
    const textBlob = await clipboardItem.getType('text/plain');

    return textBlob.text();
  }

  if ('text/plain' in clipboardItem) {
    const textValue = await Promise.resolve(clipboardItem['text/plain']);

    if (textValue instanceof Blob) {
      return textValue.text();
    }

    return String(textValue ?? '');
  }

  throw new Error('Only text/plain clipboard writes are supported.');
}

function installClipboardWriteCompatibilityShim() {
  const clipboard = globalThis.navigator?.clipboard;

  if (
    !clipboard ||
    typeof clipboard.write === 'function' ||
    typeof clipboard.writeText !== 'function'
  ) {
    return;
  }

  const writeText = clipboard.writeText.bind(clipboard);
  const compatibleWrite = async (
    items:
      | Iterable<ClipboardWriteItemLike>
      | ArrayLike<ClipboardWriteItemLike>
      | null
      | undefined,
  ) => {
    for (const clipboardItem of Array.from(items || [])) {
      try {
        await writeText(await resolveClipboardPlainText(clipboardItem));
        return;
      } catch (_error) {
        // Continue until a text/plain item is found.
      }
    }

    throw new Error('Only text/plain clipboard writes are supported.');
  };

  try {
    Object.defineProperty(clipboard, 'write', {
      configurable: true,
      writable: true,
      value: compatibleWrite,
    });
    return;
  } catch (_error) {
    // Fall back to direct assignment below.
  }

  try {
    (clipboard as { write?: typeof compatibleWrite }).write = compatibleWrite;
    return;
  } catch (_error) {
    // Fall back to shadowing navigator.clipboard below.
  }

  try {
    Object.defineProperty(globalThis.navigator, 'clipboard', {
      configurable: true,
      value: {
        readText:
          typeof clipboard.readText === 'function'
            ? clipboard.readText.bind(clipboard)
            : undefined,
        write: compatibleWrite,
        writeText,
      },
    });
  } catch (_error) {
    // Ignore browsers that reject clipboard shims entirely.
  }
}

function lockMobileViewportZoom(isMobileDevice: boolean) {
  if (!isMobileDevice) {
    return;
  }

  const viewportMeta = document.querySelector('meta[name="viewport"]');

  if (viewportMeta instanceof HTMLMetaElement) {
    viewportMeta.setAttribute('content', MOBILE_VIEWPORT_CONTENT);
  }

  const preventGestureZoom = (event: Event) => {
    event.preventDefault();
  };

  for (const eventName of MOBILE_GESTURE_ZOOM_EVENTS) {
    document.addEventListener(eventName, preventGestureZoom, {
      passive: false,
    });
  }
}

function resolveSystemTheme() {
  try {
    if (typeof globalThis.matchMedia === 'function') {
      return globalThis.matchMedia(SYSTEM_DARK_THEME_MEDIA_QUERY).matches
        ? 'dark'
        : 'light';
    }
  } catch (_error) {
    // Ignore media query failures.
  }

  return null;
}

/**
 * Stamp the resolved theme (stored preference → legacy key → system → dark)
 * onto `<html>` before the app boots. Formerly an inline `<head>` script on
 * both pages; it now runs as the page entries' FIRST statement, so the
 * static markup's dark default is only visible while the entry module
 * loads. The app's `ThemeController` re-resolves the same preference and
 * binds the system/UI listeners during boot; this only covers the pre-boot
 * window.
 */
function initializePageTheme(): void {
  try {
    const storedTheme =
      new EditorPreferencesStore().loadStoredThemePreference();
    const theme = storedTheme ?? resolveSystemTheme() ?? DEFAULT_THEME;

    document.documentElement.dataset.theme = theme;
    // Bootstrap only understands `light`/`dark`, so it gets the base of a
    // `-bs` theme rather than its name (mirrors `ThemeController.applyTheme`).
    document.documentElement.setAttribute(
      'data-bs-theme',
      getOpenLyricThemeBase(theme),
    );
  } catch (_error) {
    // Ignore storage failures.
  }
}

/**
 * The page-environment shims shared by both page entries
 * (`editor/main-open-lyric.ts`, `editor/main-editor.ts`): a
 * `navigator.clipboard.write` compatibility shim for browsers that only
 * implement `writeText`, the plain-text copy interceptor, the mobile
 * viewport-zoom lock, and the mobile Eruda console (`?debug=true`).
 * Component composition stays in the page entries — this is the browser
 * environment noise around it.
 */
function preparePageEnvironment(): void {
  installClipboardWriteCompatibilityShim();
  installPlainTextCopyHandler();

  const isMobileDevice = isLikelyMobileBrowser();

  lockMobileViewportZoom(isMobileDevice);

  if (shouldBootstrapMobileEruda({ isMobileDevice })) {
    void bootstrapMobileEruda();
  }
}

export { initializePageTheme, preparePageEnvironment };
