import { getOpenLyricDocumentApi } from '../../open-lyric-plugin.ts';
import { refs, setStatus, state } from '../../shared.ts';
import { INVALID_MARKDOWN_CONFIRMATION_MESSAGE } from './constants.ts';

const RAW_TEXT_IMPORT_DEFAULT_MESSAGE =
  'Paste raw text generated by Copy as Text.';
const RAW_TEXT_IMPORT_DISABLED_MESSAGE =
  'Open Lyric plugin is disabled. Turn it on in Preview settings to parse raw text.';
const RAW_TEXT_IMPORT_EMPTY_MESSAGE =
  'Paste raw text before parsing it into Open Lyric markdown.';
const RAW_TEXT_IMPORT_CONFIRMATION_MESSAGE =
  'This text does not fully match the Open Lyric plain-text format. Import the best-effort markdown anyway?';
const RAW_TEXT_IMPORT_INVALID_CONFIRMATION_MESSAGE =
  'This text does not fully match the Open Lyric plain-text format, and the parsed markdown still has errors. Import it anyway?';

function formatRawTextImportStatus(placeholdersUsed) {
  const uniquePlaceholders = Array.from(new Set(placeholdersUsed || []));

  if (!uniquePlaceholders.length) {
    return 'Raw text parsed into Open Lyric markdown';
  }

  if (uniquePlaceholders.length === 1) {
    return `Raw text parsed into Open Lyric markdown using default ${uniquePlaceholders[0]}`;
  }

  if (uniquePlaceholders.length === 2) {
    return `Raw text parsed into Open Lyric markdown using default ${uniquePlaceholders[0]} and ${uniquePlaceholders[1]}`;
  }

  return 'Raw text parsed into Open Lyric markdown using several default fields';
}

function applyDocumentControllerRawTextImportMethods(DocumentControllerClass) {
  Object.assign(DocumentControllerClass.prototype, {
    setRawTextImportMessage(this: any, message, tone = 'muted') {
      if (!refs.rawTextImportMessage) {
        return;
      }

      refs.rawTextImportMessage.dataset.tone = tone;
      refs.rawTextImportMessage.textContent = message;
    },

    closeRawTextImportDialog(this: any, returnValue = 'cancel') {
      if (!refs.rawTextImportDialog?.open) {
        return;
      }

      refs.rawTextImportDialog.close(returnValue);
    },

    openRawTextImportDialog(this: any) {
      if (!refs.rawTextImportDialog || !refs.rawTextImportTextarea) {
        return;
      }

      this.setRawTextImportMessage(
        getOpenLyricDocumentApi()
          ? RAW_TEXT_IMPORT_DEFAULT_MESSAGE
          : RAW_TEXT_IMPORT_DISABLED_MESSAGE,
        getOpenLyricDocumentApi() ? 'muted' : 'error',
      );

      if (!refs.rawTextImportDialog.open) {
        refs.rawTextImportDialog.showModal();
      }

      refs.rawTextImportTextarea.focus();

      if (refs.rawTextImportTextarea.value) {
        refs.rawTextImportTextarea.select();
      }
    },

    handleRawTextImportDialogClose(this: any) {
      this.setRawTextImportMessage(RAW_TEXT_IMPORT_DEFAULT_MESSAGE);
      state.editor?.focus();
    },

    getRawTextImportConfirmationMessage(
      this: any,
      { matchesPlainTextFormat, isValidMarkdown },
    ) {
      if (!matchesPlainTextFormat && !isValidMarkdown) {
        return RAW_TEXT_IMPORT_INVALID_CONFIRMATION_MESSAGE;
      }

      if (!matchesPlainTextFormat) {
        return RAW_TEXT_IMPORT_CONFIRMATION_MESSAGE;
      }

      return INVALID_MARKDOWN_CONFIRMATION_MESSAGE;
    },

    handleRawTextImportSubmit(this: any, event) {
      event.preventDefault();

      const rawText = String(refs.rawTextImportTextarea?.value || '');

      if (!rawText.trim()) {
        this.setRawTextImportMessage(RAW_TEXT_IMPORT_EMPTY_MESSAGE, 'error');
        refs.rawTextImportTextarea?.focus();
        return;
      }

      const documentApi = getOpenLyricDocumentApi();

      if (
        typeof documentApi?.parsePlainText !== 'function' ||
        typeof documentApi?.checkMarkdown !== 'function'
      ) {
        this.setRawTextImportMessage(RAW_TEXT_IMPORT_DISABLED_MESSAGE, 'error');
        return;
      }

      const parsedDocument = documentApi.parsePlainText(rawText);

      if (!parsedDocument.markdown) {
        this.setRawTextImportMessage(
          'Unable to parse this text into Open Lyric markdown.',
          'error',
        );
        return;
      }

      const isValidMarkdown = documentApi.checkMarkdown(
        parsedDocument.markdown,
      );
      const requiresConfirmation =
        !parsedDocument.matchesPlainTextFormat ||
        parsedDocument.hasConflictingDuplicates ||
        !isValidMarkdown;

      if (
        requiresConfirmation &&
        !globalThis.confirm(
          this.getRawTextImportConfirmationMessage({
            isValidMarkdown,
            matchesPlainTextFormat: parsedDocument.matchesPlainTextFormat,
          }),
        )
      ) {
        this.setRawTextImportMessage(
          'Import cancelled. Raw text was not applied.',
        );
        return;
      }

      this.applyDocumentContent({
        content: parsedDocument.markdown,
        fileName: state.fileName || 'untitled.md',
        saveDraft: true,
      });

      this.closeRawTextImportDialog('submit');
      setStatus(formatRawTextImportStatus(parsedDocument.placeholdersUsed));
    },
  });
}

export { applyDocumentControllerRawTextImportMethods };
