/**
 * A `.pptx` writer, small enough to read in one sitting.
 *
 * It covers exactly what the Open Lyric deck asks for — a 16:9 presentation
 * whose slides carry a solid background, text boxes, and full-bleed pictures —
 * and nothing else: no charts, no tables, no notes, no animation. That is the
 * whole reason it exists in place of a general-purpose library.
 *
 * The shape of the API deliberately mirrors the handful of calls the exports
 * already made (`addSlide`, `slide.addText`, `slide.addImage`, `write`), so the
 * two call sites read the same as before.
 *
 * Geometry is in inches, type in points, colours as bare `RRGGBB` — the units
 * PowerPoint's own UI uses. They are converted to EMU (914400 per inch) and
 * hundredths of a point on the way out, which is what the file format wants.
 */

import { createZipBlob, type ZipSource } from './zip.ts';

const EMU_PER_INCH = 914400;
const EMU_PER_POINT = 12700;
// 13.333in x 7.5in — PowerPoint's "Widescreen" page, the deck's only layout.
const SLIDE_WIDTH_EMU = 12192000;
const SLIDE_HEIGHT_EMU = 6858000;
// The deck carries no speaker notes, but the format still asks how big a notes
// page would be. These are PowerPoint's own defaults, 7.5in x 10in portrait.
const NOTES_WIDTH_EMU = 6858000;
const NOTES_HEIGHT_EMU = 9144000;
const PPTX_MIME_TYPE =
  'application/vnd.openxmlformats-officedocument.presentationml.presentation';
const XML_DECLARATION =
  '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
const DRAWING_NS = 'http://schemas.openxmlformats.org/drawingml/2006/main';
const PRESENTATION_NS =
  'http://schemas.openxmlformats.org/presentationml/2006/main';
const RELATIONSHIP_NS =
  'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const PACKAGE_RELATIONSHIP_NS =
  'http://schemas.openxmlformats.org/package/2006/relationships';
const FIRST_SLIDE_ID = 256;

type Measure = number | string;

interface ShapeBox {
  x?: Measure;
  y?: Measure;
  w?: Measure;
  h?: Measure;
}

interface TextOptions extends ShapeBox {
  align?: 'left' | 'center' | 'right';
  bold?: boolean;
  color?: string;
  fill?: { color?: string } | null;
  fit?: 'shrink' | 'none';
  fontFace?: string;
  fontSize?: number;
  /** Inner padding in points, as `[left, right, bottom, top]` or one number. */
  margin?: number | number[];
  valign?: 'top' | 'middle' | 'bottom';
  line?: { color?: string; width?: number } | null;
}

interface ImageOptions extends ShapeBox {
  /** A `data:image/png;base64,…` URI. */
  data: string;
}

interface MediaPart {
  extension: string;
  bytes: Uint8Array;
  name: string;
}

/* -------------------------------- helpers -------------------------------- */

/**
 * XML 1.0 can spell tab, newline and carriage return, and nothing else below
 * `0x20`. A stray control character makes the whole package unreadable rather
 * than the one run it sits in, so they are dropped before anything else.
 */
function stripInvalidXmlCharacters(text: string): string {
  let output = '';

  for (const character of text) {
    const code = character.codePointAt(0) ?? 0;

    if (code === 9 || code === 10 || code === 13 || code >= 32) {
      output += character;
    }
  }

  return output;
}

function escapeXml(value: unknown): string {
  return stripInvalidXmlCharacters(String(value ?? ''))
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** `RRGGBB` from `#RRGGBB`, `RRGGBB`, or a fallback when it is neither. */
function normalizeColor(color: unknown, fallback = '000000'): string {
  const normalized = String(color ?? '')
    .trim()
    .replace(/^#/, '')
    .toUpperCase();

  return /^[0-9A-F]{6}$/.test(normalized) ? normalized : fallback;
}

/** Inches (or a `'50%'` share of `total`) as EMU. */
function toEmu(
  value: Measure | undefined,
  total: number,
  fallback = 0,
): number {
  if (typeof value === 'string' && value.trim().endsWith('%')) {
    const percent = Number.parseFloat(value);

    return Number.isFinite(percent)
      ? Math.round((percent / 100) * total)
      : fallback;
  }

  const inches = Number(value);

  return Number.isFinite(inches) ? Math.round(inches * EMU_PER_INCH) : fallback;
}

function resolveMargins(margin: TextOptions['margin']): {
  left: number;
  right: number;
  bottom: number;
  top: number;
} {
  const asPoints = (value: unknown): number => {
    const points = Number(value);

    return Number.isFinite(points) && points > 0
      ? Math.round(points * EMU_PER_POINT)
      : 0;
  };

  if (Array.isArray(margin)) {
    const [left = 0, right = 0, bottom = 0, top = 0] = margin;

    return {
      left: asPoints(left),
      right: asPoints(right),
      bottom: asPoints(bottom),
      top: asPoints(top),
    };
  }

  const uniform = asPoints(margin);

  return { left: uniform, right: uniform, bottom: uniform, top: uniform };
}

function decodeDataUri(dataUri: string): {
  bytes: Uint8Array;
  extension: string;
} {
  const text = String(dataUri ?? '');
  const mimeMatch = /^data:image\/([a-z0-9+.-]+);/i.exec(text);
  const base64 = text.slice(text.indexOf('base64,') + 'base64,'.length);
  const binary = globalThis.atob(base64);
  const bytes = new Uint8Array(binary.length);

  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }

  const rawExtension = (mimeMatch?.[1] ?? 'png').toLowerCase();

  return { bytes, extension: rawExtension === 'jpg' ? 'jpeg' : rawExtension };
}

function buildRelationships(
  relationships: Array<{ id: string; type: string; target: string }>,
): string {
  const entries = relationships
    .map(
      ({ id, type, target }) =>
        `<Relationship Id="${id}" Type="${type}" Target="${escapeXml(target)}"/>`,
    )
    .join('');

  return `${XML_DECLARATION}<Relationships xmlns="${PACKAGE_RELATIONSHIP_NS}">${entries}</Relationships>`;
}

/* --------------------------------- slides --------------------------------- */

class PptxSlide {
  /** `{ color }` — the solid fill painted behind the whole slide. */
  background: { color?: string } | null = null;
  /** Default run colour for text that names none. */
  color = '';

  private readonly shapes: string[] = [];
  private readonly imageRelationshipIds: string[] = [];
  private readonly addMedia: (dataUri: string) => string;

  constructor(addMedia: (dataUri: string) => string) {
    this.addMedia = addMedia;
  }

  addText(text: unknown, options: TextOptions = {}): void {
    const paragraphs = String(text ?? '').split('\n');
    const margins = resolveMargins(options.margin);
    const alignment = { left: 'l', center: 'ctr', right: 'r' }[
      options.align ?? 'left'
    ];
    const anchor = { top: 't', middle: 'ctr', bottom: 'b' }[
      options.valign ?? 'top'
    ];
    const runProperties = [
      `lang="en-US"`,
      `sz="${Math.round((Number(options.fontSize) || 18) * 100)}"`,
      options.bold ? 'b="1"' : '',
      'dirty="0"',
    ]
      .filter(Boolean)
      .join(' ');
    const runColor = normalizeColor(
      options.color || this.color,
      this.color ? normalizeColor(this.color) : '000000',
    );
    const fontFace = String(options.fontFace ?? '').trim();
    const typeface = fontFace
      ? `<a:latin typeface="${escapeXml(fontFace)}"/><a:cs typeface="${escapeXml(fontFace)}"/>`
      : '';
    const body = paragraphs
      .map((paragraph) => {
        const run = paragraph
          ? `<a:r><a:rPr ${runProperties}><a:solidFill><a:srgbClr val="${runColor}"/></a:solidFill>${typeface}</a:rPr><a:t>${escapeXml(paragraph)}</a:t></a:r>`
          : `<a:endParaRPr ${runProperties}/>`;

        return `<a:p><a:pPr algn="${alignment}"/>${run}</a:p>`;
      })
      .join('');
    const fillColor = options.fill?.color;
    const fill = fillColor
      ? `<a:solidFill><a:srgbClr val="${normalizeColor(fillColor)}"/></a:solidFill>`
      : '<a:noFill/>';
    const outline = options.line?.color
      ? `<a:ln w="${Math.round((Number(options.line.width) || 1) * EMU_PER_POINT)}"><a:solidFill><a:srgbClr val="${normalizeColor(options.line.color)}"/></a:solidFill></a:ln>`
      : '';
    // `normAutofit` is PowerPoint's own shrink-to-fit: it recomputes the scale
    // when the deck opens, which is what keeps a long verse inside its box on
    // a machine whose fonts measure differently than the browser's did.
    const autofit =
      options.fit === 'shrink' ? '<a:normAutofit/>' : '<a:spAutoFit/>';
    const index = this.shapes.length + 2;

    this.shapes.push(
      `<p:sp><p:nvSpPr><p:cNvPr id="${index}" name="Text ${index}"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr>` +
        `<p:spPr>${this.buildTransform(options)}<a:prstGeom prst="rect"><a:avLst/></a:prstGeom>${fill}${outline}</p:spPr>` +
        `<p:txBody><a:bodyPr lIns="${margins.left}" tIns="${margins.top}" rIns="${margins.right}" bIns="${margins.bottom}" anchor="${anchor}" wrap="square">${autofit}</a:bodyPr><a:lstStyle/>${body}</p:txBody>` +
        `</p:sp>`,
    );
  }

  addImage(options: ImageOptions): void {
    const relationshipId = this.addMedia(options.data);
    const index = this.shapes.length + 2;

    this.imageRelationshipIds.push(relationshipId);
    this.shapes.push(
      `<p:pic><p:nvPicPr><p:cNvPr id="${index}" name="Image ${index}"/><p:cNvPicPr><a:picLocks noChangeAspect="1"/></p:cNvPicPr><p:nvPr/></p:nvPicPr>` +
        `<p:blipFill><a:blip r:embed="${relationshipId}"/><a:stretch><a:fillRect/></a:stretch></p:blipFill>` +
        `<p:spPr>${this.buildTransform(options)}<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr>` +
        `</p:pic>`,
    );
  }

  toXml(): string {
    const backgroundColor = this.background?.color;
    const background = backgroundColor
      ? `<p:bg><p:bgPr><a:solidFill><a:srgbClr val="${normalizeColor(backgroundColor)}"/></a:solidFill><a:effectLst/></p:bgPr></p:bg>`
      : '';

    return (
      `${XML_DECLARATION}<p:sld xmlns:a="${DRAWING_NS}" xmlns:r="${RELATIONSHIP_NS}" xmlns:p="${PRESENTATION_NS}">` +
      `<p:cSld>${background}<p:spTree>` +
      `<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>` +
      `<p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>` +
      `${this.shapes.join('')}</p:spTree></p:cSld>` +
      `<p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>`
    );
  }

  private buildTransform(box: ShapeBox): string {
    const x = toEmu(box.x, SLIDE_WIDTH_EMU);
    const y = toEmu(box.y, SLIDE_HEIGHT_EMU);
    const width = toEmu(box.w, SLIDE_WIDTH_EMU, SLIDE_WIDTH_EMU);
    const height = toEmu(box.h, SLIDE_HEIGHT_EMU, SLIDE_HEIGHT_EMU);

    return `<a:xfrm><a:off x="${x}" y="${y}"/><a:ext cx="${width}" cy="${height}"/></a:xfrm>`;
  }
}

/* ----------------------------- the presentation ---------------------------- */

class PptxPresentation {
  private readonly slides: PptxSlide[] = [];
  private readonly mediaParts: MediaPart[] = [];
  private readonly mediaIdsByData = new Map<string, string>();
  private readonly relationshipIdsBySlide = new Map<PptxSlide, string[]>();
  private currentSlide: PptxSlide | null = null;

  addSlide(): PptxSlide {
    const slide = new PptxSlide((dataUri) => this.registerMedia(dataUri));

    this.slides.push(slide);
    this.relationshipIdsBySlide.set(slide, []);
    this.currentSlide = slide;
    return slide;
  }

  /** The finished deck, as a `.pptx` blob ready to hand to a download. */
  async write({
    compression = true,
  }: { compression?: boolean } = {}): Promise<Blob> {
    return createZipBlob(this.buildParts(), {
      isCompressed: compression,
      mimeType: PPTX_MIME_TYPE,
    });
  }

  private registerMedia(dataUri: string): string {
    const key = String(dataUri ?? '');
    const existingName = this.mediaIdsByData.get(key);
    const slide = this.currentSlide;
    const slideRelationships = slide
      ? (this.relationshipIdsBySlide.get(slide) ?? [])
      : [];

    // A part that comes round again in the structure shows the same picture,
    // so the media part is embedded once and pointed at twice.
    let name = existingName;

    if (!name) {
      const { bytes, extension } = decodeDataUri(key);

      name = `image${this.mediaParts.length + 1}.${extension}`;
      this.mediaParts.push({ bytes, extension, name });
      this.mediaIdsByData.set(key, name);
    }

    slideRelationships.push(name);
    if (slide) {
      this.relationshipIdsBySlide.set(slide, slideRelationships);
    }

    // rId1 on every slide is its layout, so images start at rId2.
    return `rId${slideRelationships.length + 1}`;
  }

  private buildParts(): ZipSource[] {
    const slideNumbers = this.slides.map((_slide, index) => index + 1);
    const imageExtensions = new Set(
      this.mediaParts.map((mediaPart) => mediaPart.extension),
    );
    const contentTypes =
      `${XML_DECLARATION}<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">` +
      `<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>` +
      `<Default Extension="xml" ContentType="application/xml"/>` +
      [...imageExtensions]
        .map(
          (extension) =>
            `<Default Extension="${extension}" ContentType="image/${extension}"/>`,
        )
        .join('') +
      `<Override PartName="/ppt/presentation.xml" ContentType="${PPTX_MIME_TYPE}.main+xml"/>` +
      `<Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/>` +
      `<Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/>` +
      `<Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>` +
      slideNumbers
        .map(
          (slideNumber) =>
            `<Override PartName="/ppt/slides/slide${slideNumber}.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>`,
        )
        .join('') +
      `</Types>`;

    const parts: ZipSource[] = [
      { name: '[Content_Types].xml', data: contentTypes },
      {
        name: '_rels/.rels',
        data: buildRelationships([
          {
            id: 'rId1',
            type: `${RELATIONSHIP_NS}/officeDocument`,
            target: 'ppt/presentation.xml',
          },
        ]),
      },
      { name: 'ppt/presentation.xml', data: this.buildPresentationXml() },
      {
        name: 'ppt/_rels/presentation.xml.rels',
        data: buildRelationships([
          {
            id: 'rId1',
            type: `${RELATIONSHIP_NS}/slideMaster`,
            target: 'slideMasters/slideMaster1.xml',
          },
          ...slideNumbers.map((slideNumber) => ({
            id: `rId${slideNumber + 1}`,
            type: `${RELATIONSHIP_NS}/slide`,
            target: `slides/slide${slideNumber}.xml`,
          })),
          {
            id: `rId${slideNumbers.length + 2}`,
            type: `${RELATIONSHIP_NS}/theme`,
            target: 'theme/theme1.xml',
          },
        ]),
      },
      { name: 'ppt/theme/theme1.xml', data: buildThemeXml() },
      {
        name: 'ppt/slideMasters/slideMaster1.xml',
        data: buildSlideMasterXml(),
      },
      {
        name: 'ppt/slideMasters/_rels/slideMaster1.xml.rels',
        data: buildRelationships([
          {
            id: 'rId1',
            type: `${RELATIONSHIP_NS}/slideLayout`,
            target: '../slideLayouts/slideLayout1.xml',
          },
          {
            id: 'rId2',
            type: `${RELATIONSHIP_NS}/theme`,
            target: '../theme/theme1.xml',
          },
        ]),
      },
      {
        name: 'ppt/slideLayouts/slideLayout1.xml',
        data: buildSlideLayoutXml(),
      },
      {
        name: 'ppt/slideLayouts/_rels/slideLayout1.xml.rels',
        data: buildRelationships([
          {
            id: 'rId1',
            type: `${RELATIONSHIP_NS}/slideMaster`,
            target: '../slideMasters/slideMaster1.xml',
          },
        ]),
      },
    ];

    this.slides.forEach((slide, index) => {
      const slideNumber = index + 1;
      const imageNames = this.relationshipIdsBySlide.get(slide) ?? [];

      parts.push(
        { name: `ppt/slides/slide${slideNumber}.xml`, data: slide.toXml() },
        {
          name: `ppt/slides/_rels/slide${slideNumber}.xml.rels`,
          data: buildRelationships([
            {
              id: 'rId1',
              type: `${RELATIONSHIP_NS}/slideLayout`,
              target: '../slideLayouts/slideLayout1.xml',
            },
            ...imageNames.map((imageName, imageIndex) => ({
              id: `rId${imageIndex + 2}`,
              type: `${RELATIONSHIP_NS}/image`,
              target: `../media/${imageName}`,
            })),
          ]),
        },
      );
    });

    for (const mediaPart of this.mediaParts) {
      parts.push({
        name: `ppt/media/${mediaPart.name}`,
        data: mediaPart.bytes,
      });
    }

    return parts;
  }

  private buildPresentationXml(): string {
    const slideIds = this.slides
      .map(
        (_slide, index) =>
          `<p:sldId id="${FIRST_SLIDE_ID + index}" r:id="rId${index + 2}"/>`,
      )
      .join('');

    return (
      `${XML_DECLARATION}<p:presentation xmlns:a="${DRAWING_NS}" xmlns:r="${RELATIONSHIP_NS}" xmlns:p="${PRESENTATION_NS}" saveSubsetFonts="1">` +
      `<p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId1"/></p:sldMasterIdLst>` +
      `<p:sldIdLst>${slideIds}</p:sldIdLst>` +
      `<p:sldSz cx="${SLIDE_WIDTH_EMU}" cy="${SLIDE_HEIGHT_EMU}"/>` +
      `<p:notesSz cx="${NOTES_WIDTH_EMU}" cy="${NOTES_HEIGHT_EMU}"/>` +
      `</p:presentation>`
    );
  }
}

/* ------------------------- the fixed package parts ------------------------- */

function buildEmptyShapeTree(): string {
  return (
    `<p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>` +
    `<p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr></p:spTree>`
  );
}

function buildSlideMasterXml(): string {
  return (
    `${XML_DECLARATION}<p:sldMaster xmlns:a="${DRAWING_NS}" xmlns:r="${RELATIONSHIP_NS}" xmlns:p="${PRESENTATION_NS}">` +
    `<p:cSld><p:bg><p:bgPr><a:solidFill><a:schemeClr val="lt1"/></a:solidFill><a:effectLst/></p:bgPr></p:bg>${buildEmptyShapeTree()}</p:cSld>` +
    `<p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/>` +
    `<p:sldLayoutIdLst><p:sldLayoutId id="2147483649" r:id="rId1"/></p:sldLayoutIdLst>` +
    `<p:txStyles><p:titleStyle/><p:bodyStyle/><p:otherStyle/></p:txStyles>` +
    `</p:sldMaster>`
  );
}

function buildSlideLayoutXml(): string {
  return (
    `${XML_DECLARATION}<p:sldLayout xmlns:a="${DRAWING_NS}" xmlns:r="${RELATIONSHIP_NS}" xmlns:p="${PRESENTATION_NS}" type="blank" preserve="1">` +
    `<p:cSld name="Blank">${buildEmptyShapeTree()}</p:cSld>` +
    `<p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>`
  );
}

/**
 * Every slide names its own colours and typeface, so the theme exists only
 * because the format requires the master to have one. It is the stock Office
 * palette, with the three-entry style lists the schema insists on.
 */
function buildThemeXml(): string {
  const accents = ['4472C4', 'ED7D31', 'A5A5A5', 'FFC000', '5B9BD5', '70AD47']
    .map(
      (color, index) =>
        `<a:accent${index + 1}><a:srgbClr val="${color}"/></a:accent${index + 1}>`,
    )
    .join('');
  const solidFill = '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill>';
  const outline = `<a:ln w="6350" cap="flat" cmpd="sng" algn="ctr">${solidFill}<a:prstDash val="solid"/></a:ln>`;

  return (
    `${XML_DECLARATION}<a:theme xmlns:a="${DRAWING_NS}" name="Open Lyric">` +
    `<a:themeElements>` +
    `<a:clrScheme name="Open Lyric">` +
    `<a:dk1><a:sysClr val="windowText" lastClr="000000"/></a:dk1>` +
    `<a:lt1><a:sysClr val="window" lastClr="FFFFFF"/></a:lt1>` +
    `<a:dk2><a:srgbClr val="44546A"/></a:dk2>` +
    `<a:lt2><a:srgbClr val="E7E6E6"/></a:lt2>` +
    `${accents}` +
    `<a:hlink><a:srgbClr val="0563C1"/></a:hlink>` +
    `<a:folHlink><a:srgbClr val="954F72"/></a:folHlink>` +
    `</a:clrScheme>` +
    `<a:fontScheme name="Open Lyric">` +
    `<a:majorFont><a:latin typeface="Calibri Light"/><a:ea typeface=""/><a:cs typeface=""/></a:majorFont>` +
    `<a:minorFont><a:latin typeface="Calibri"/><a:ea typeface=""/><a:cs typeface=""/></a:minorFont>` +
    `</a:fontScheme>` +
    `<a:fmtScheme name="Open Lyric">` +
    `<a:fillStyleLst>${solidFill.repeat(3)}</a:fillStyleLst>` +
    `<a:lnStyleLst>${outline.repeat(3)}</a:lnStyleLst>` +
    `<a:effectStyleLst>${'<a:effectStyle><a:effectLst/></a:effectStyle>'.repeat(3)}</a:effectStyleLst>` +
    `<a:bgFillStyleLst>${solidFill.repeat(3)}</a:bgFillStyleLst>` +
    `</a:fmtScheme>` +
    `</a:themeElements>` +
    `<a:objectDefaults/><a:extraClrSchemeLst/>` +
    `</a:theme>`
  );
}

/** A new, empty 16:9 deck. */
function createOpenLyricPresentation(): PptxPresentation {
  return new PptxPresentation();
}

export { createOpenLyricPresentation, PPTX_MIME_TYPE };
export type { ImageOptions, PptxPresentation, PptxSlide, TextOptions };
