import {
  CHORD_SYMBOL_SOURCE,
  CONFIG_ENUM_FIELD_VALUES,
  LYRIC_SECTION_NAMES,
  collapseSpaceLikeText,
  isSpaceLikeCharacter,
  isValidStrummingPatternValue,
  normalizeConfigFieldName,
  normalizeStrummingPatternValue,
  shouldAllowInvisibleWordSeparators,
  trimSpaceLikeEnd,
  trimSpaceLikeStart,
  trimSpaceLikeText,
} from '../../../editor/scripts/shared.ts';
import { parseFenceHeader } from '../domain/parser/fences.ts';
import { STRUCTURE_TOKEN_DEFINITIONS } from '../domain/structure.ts';

const DEFAULT_IMPORT_VALUES = {
  Artist: 'Unknown Artist',
  Copyright: 'Unknown',
  Key: Array.isArray(CONFIG_ENUM_FIELD_VALUES.Key)
    ? CONFIG_ENUM_FIELD_VALUES.Key[0]
    : 'C',
  Tempo: '120bpm',
  Time: Array.isArray(CONFIG_ENUM_FIELD_VALUES.Time)
    ? CONFIG_ENUM_FIELD_VALUES.Time[0]
    : '4/4',
};
const SINGLE_PATTERN_RE = /^Strumming Pattern:\s*(.+)$/;
const MULTI_PATTERN_HEADER_RE = /^Strumming Patterns:\s*$/;
const STRUCTURE_LINE_RE = /^Structure:\s*(.+)$/;
const ZWSP_SINGLE_PATTERN_RE = /^Strumming Pattern:[\s\u200B]*(.+)$/u;
const ZWSP_MULTI_PATTERN_HEADER_RE = /^Strumming Patterns:[\s\u200B]*$/u;
const ZWSP_STRUCTURE_LINE_RE = /^Structure:[\s\u200B]*(.+)$/u;
const REPEAT_SUFFIX_RE = /^\(([1-9]\d*x)\)(?:\s+|$)/;
const ZWSP_REPEAT_SUFFIX_RE = /^\(([1-9]\d*x)\)(?:[\s\u200B]+|$)/u;
const SECTION_INDENT_RE = /^(?: {2}|\t)/;
const CONFIG_ENTRY_RE = /^-\s*([^:]+):\s*(.*)$/;
const CHORD_PLACEMENT_RE = new RegExp(
  String.raw`^(\|?)(${CHORD_SYMBOL_SOURCE})`,
);
const SUPPORTED_PLAIN_TEXT_CONFIG_FIELDS = new Set([
  'Description',
  'Copyright',
  'Theme',
  'Genre',
  'Style',
  'Attachments',
]);
const STRUCTURE_CODE_BY_HEADER = new Map(
  STRUCTURE_TOKEN_DEFINITIONS.map(({ header, code }) => [header, code]),
);
const LYRIC_SECTION_NAME_SET = new Set(LYRIC_SECTION_NAMES);

function normalizeRawText(value) {
  return String(value ?? '')
    .replace(/\uFEFF/g, '')
    .replace(/\r\n?/g, '\n');
}

function trimLineEnd(line, allowZwspSeparators = true) {
  return trimSpaceLikeEnd(line, allowZwspSeparators);
}

function trimBlankEdges(lines, allowZwspSeparators = true) {
  const normalizedLines = Array.isArray(lines) ? lines.slice() : [];
  let startIndex = 0;
  let endIndex = normalizedLines.length;

  while (
    startIndex < endIndex &&
    !trimSpaceLikeText(normalizedLines[startIndex], allowZwspSeparators)
  ) {
    startIndex += 1;
  }

  while (
    endIndex > startIndex &&
    !trimSpaceLikeText(normalizedLines[endIndex - 1], allowZwspSeparators)
  ) {
    endIndex -= 1;
  }

  return normalizedLines.slice(startIndex, endIndex);
}

function sanitizeConfigValue(value, allowZwspSeparators = true) {
  return trimSpaceLikeText(value, allowZwspSeparators);
}

function normalizeSeparatorText(value, allowZwspSeparators = true) {
  return trimSpaceLikeText(
    collapseSpaceLikeText(value, ' ', allowZwspSeparators),
    allowZwspSeparators,
  );
}

function getSinglePatternRe(allowZwspSeparators) {
  return allowZwspSeparators ? ZWSP_SINGLE_PATTERN_RE : SINGLE_PATTERN_RE;
}

function getMultiPatternHeaderRe(allowZwspSeparators) {
  return allowZwspSeparators
    ? ZWSP_MULTI_PATTERN_HEADER_RE
    : MULTI_PATTERN_HEADER_RE;
}

function getStructureLineRe(allowZwspSeparators) {
  return allowZwspSeparators ? ZWSP_STRUCTURE_LINE_RE : STRUCTURE_LINE_RE;
}

function getRepeatSuffixRe(allowZwspSeparators) {
  return allowZwspSeparators ? ZWSP_REPEAT_SUFFIX_RE : REPEAT_SUFFIX_RE;
}

function stripSectionIndent(line) {
  return String(line ?? '').replace(SECTION_INDENT_RE, '');
}

function parseMetaEntriesFromLine(line, allowZwspSeparators = true) {
  return Array.from(
    normalizeSeparatorText(line, allowZwspSeparators).matchAll(
      /(?:^|,\s*)(Key|Time|Tempo):\s*([^,]+)(?=,\s*(?:Key|Time|Tempo):|$)/g,
    ),
  ).map((match) => ({
    field: match[1],
    value: sanitizeConfigValue(match[2], allowZwspSeparators),
  }));
}

function isStructuredHeaderLine(line, allowZwspSeparators = true) {
  const trimmedLine = trimSpaceLikeText(line, allowZwspSeparators);

  return Boolean(
    trimmedLine &&
    (parseMetaEntriesFromLine(trimmedLine, allowZwspSeparators).length ||
      getSinglePatternRe(allowZwspSeparators).test(trimmedLine) ||
      getMultiPatternHeaderRe(allowZwspSeparators).test(trimmedLine) ||
      getStructureLineRe(allowZwspSeparators).test(trimmedLine)),
  );
}

function parseSecondaryText(line, allowZwspSeparators = true) {
  const parts = String(line ?? '')
    .split(' · ')
    .map((segment) => sanitizeConfigValue(segment, allowZwspSeparators))
    .filter(Boolean);

  if (parts.length >= 2) {
    return {
      subtitle: parts.slice(0, -1).join(' · '),
      artist: parts[parts.length - 1] || '',
    };
  }

  return {
    subtitle: '',
    artist: sanitizeConfigValue(line, allowZwspSeparators),
  };
}

function parsePlainTextSectionHeading(line, allowZwspSeparators = true) {
  const rawLine = trimLineEnd(line, allowZwspSeparators);

  if (!rawLine || /^[ \t]/.test(rawLine)) {
    return null;
  }

  const colonIndex = rawLine.indexOf(':');
  if (colonIndex <= 0) {
    return null;
  }

  const partText = trimSpaceLikeText(
    rawLine.slice(0, colonIndex),
    allowZwspSeparators,
  );
  const parsedHeader = parseFenceHeader(partText);
  if (!parsedHeader || parsedHeader.header === 'Config') {
    return null;
  }

  let remainder = trimSpaceLikeStart(
    rawLine.slice(colonIndex + 1),
    allowZwspSeparators,
  );
  let repeatText = '';
  const repeatMatch = remainder.match(getRepeatSuffixRe(allowZwspSeparators));

  if (repeatMatch) {
    repeatText = repeatMatch[1];
    remainder = trimSpaceLikeStart(
      remainder.slice(repeatMatch[0].length),
      allowZwspSeparators,
    );
  }

  return {
    inlineBody: remainder,
    parsedHeader,
    repeatText,
  };
}

function finalizeParsedSection(section, allowZwspSeparators = true) {
  return {
    ...section,
    bodyLines: trimBlankEdges(
      (section.bodyLines || []).map((line) =>
        trimLineEnd(line, allowZwspSeparators),
      ),
      allowZwspSeparators,
    ),
  };
}

function splitHeaderAndSections(lines, allowZwspSeparators = true) {
  const headerLines = [];
  const sections = [];
  let currentSection = null;
  let sawSection = false;

  (lines || []).forEach((line) => {
    const parsedHeading = parsePlainTextSectionHeading(
      line,
      allowZwspSeparators,
    );

    if (parsedHeading) {
      sawSection = true;

      if (currentSection) {
        sections.push(
          finalizeParsedSection(currentSection, allowZwspSeparators),
        );
      }

      currentSection = {
        ...parsedHeading,
        bodyLines: parsedHeading.inlineBody ? [parsedHeading.inlineBody] : [],
      };
      return;
    }

    if (!sawSection) {
      headerLines.push(line);
      return;
    }

    currentSection?.bodyLines.push(line);
  });

  if (currentSection) {
    sections.push(finalizeParsedSection(currentSection, allowZwspSeparators));
  }

  return {
    headerLines,
    sections,
  };
}

function parseHeaderBlock(
  headerLines,
  { preferSecondaryText = true, allowZwspSeparators = true } = {},
) {
  const lines = Array.isArray(headerLines)
    ? headerLines.map((line) => trimLineEnd(line, allowZwspSeparators))
    : [];
  const meta = {
    Key: '',
    Tempo: '',
    Time: '',
  };
  const plainTextConfig = {
    Attachments: [],
    Copyright: '',
    Genre: '',
    Style: '',
    Theme: '',
  };
  const descriptionLines = [];
  const strummingLines = [];
  let title = '';
  let subtitle = '';
  let artist = '';
  let structureText = '';
  let signalCount = 0;
  let index = 0;

  while (
    index < lines.length &&
    !trimSpaceLikeText(lines[index], allowZwspSeparators)
  ) {
    index += 1;
  }

  if (index < lines.length) {
    title = sanitizeConfigValue(lines[index], allowZwspSeparators);
    if (title) {
      signalCount += 1;
    }
    index += 1;
  }

  while (
    index < lines.length &&
    !trimSpaceLikeText(lines[index], allowZwspSeparators)
  ) {
    index += 1;
  }

  if (
    preferSecondaryText &&
    index < lines.length &&
    trimSpaceLikeText(lines[index], allowZwspSeparators) &&
    !isStructuredHeaderLine(lines[index], allowZwspSeparators)
  ) {
    const parsedSecondary = parseSecondaryText(
      lines[index],
      allowZwspSeparators,
    );

    subtitle = parsedSecondary.subtitle;
    artist = parsedSecondary.artist;
    signalCount += 1;
    index += 1;
  }

  while (index < lines.length) {
    const rawLine = lines[index];
    const trimmedLine = trimSpaceLikeText(rawLine, allowZwspSeparators);

    if (!trimmedLine) {
      index += 1;
      continue;
    }

    const metaEntries = parseMetaEntriesFromLine(
      trimmedLine,
      allowZwspSeparators,
    );
    if (metaEntries.length) {
      metaEntries.forEach(({ field, value }) => {
        meta[field] = value;
      });
      signalCount += metaEntries.length;
      index += 1;
      continue;
    }

    const singlePatternMatch = trimmedLine.match(
      getSinglePatternRe(allowZwspSeparators),
    );
    if (singlePatternMatch) {
      strummingLines.push(
        trimSpaceLikeText(singlePatternMatch[1], allowZwspSeparators),
      );
      signalCount += 1;
      index += 1;
      continue;
    }

    if (getMultiPatternHeaderRe(allowZwspSeparators).test(trimmedLine)) {
      signalCount += 1;
      index += 1;

      while (index < lines.length) {
        const continuationLine = lines[index];

        if (!trimSpaceLikeText(continuationLine, allowZwspSeparators)) {
          index += 1;
          continue;
        }

        if (!/^[ \t]/.test(continuationLine)) {
          break;
        }

        strummingLines.push(
          trimSpaceLikeText(continuationLine, allowZwspSeparators),
        );
        index += 1;
      }

      continue;
    }

    const structureMatch = trimmedLine.match(
      getStructureLineRe(allowZwspSeparators),
    );
    if (structureMatch) {
      structureText = normalizeSeparatorText(
        structureMatch[1],
        allowZwspSeparators,
      );
      signalCount += 1;
      index += 1;
      continue;
    }

    const configEntryMatch = trimmedLine.match(CONFIG_ENTRY_RE);
    if (configEntryMatch) {
      const field = normalizeConfigFieldName(configEntryMatch[1]);

      if (SUPPORTED_PLAIN_TEXT_CONFIG_FIELDS.has(field)) {
        const initialValue = sanitizeConfigValue(
          configEntryMatch[2],
          allowZwspSeparators,
        );

        signalCount += 1;

        if (field === 'Description' || field === 'Attachments') {
          const targetLines =
            field === 'Description'
              ? descriptionLines
              : plainTextConfig.Attachments;

          if (initialValue) {
            targetLines.push(initialValue);
          }

          index += 1;

          while (index < lines.length) {
            const continuationLine = lines[index];
            const trimmedContinuationLine = trimSpaceLikeText(
              continuationLine,
              allowZwspSeparators,
            );

            if (!trimmedContinuationLine) {
              index += 1;
              continue;
            }

            if (!/^[ \t]/.test(continuationLine)) {
              break;
            }

            targetLines.push(
              sanitizeConfigValue(continuationLine, allowZwspSeparators),
            );
            index += 1;
          }

          continue;
        }

        plainTextConfig[field] = initialValue;
        index += 1;
        continue;
      }
    }

    descriptionLines.push(trimmedLine);
    index += 1;
  }

  return {
    artist,
    attachmentLines: plainTextConfig.Attachments,
    copyright: plainTextConfig.Copyright,
    descriptionLines,
    genre: plainTextConfig.Genre,
    meta,
    signalCount,
    style: plainTextConfig.Style,
    strummingLines,
    structureText,
    subtitle,
    theme: plainTextConfig.Theme,
    title,
  };
}

function normalizeStrummingConfigLines(rawLines, allowZwspSeparators = true) {
  const configLines = [];

  (rawLines || []).forEach((rawLine) => {
    const trimmedLine = trimSpaceLikeText(
      normalizeStrummingPatternValue(rawLine, allowZwspSeparators),
      allowZwspSeparators,
    );

    if (!trimmedLine) {
      return;
    }

    const labeledPatternMatch = trimmedLine.match(/^([^:]+):\s*(.+)$/);
    if (
      labeledPatternMatch &&
      isValidStrummingPatternValue(
        trimSpaceLikeText(labeledPatternMatch[2], allowZwspSeparators),
        allowZwspSeparators,
      )
    ) {
      const label = sanitizeConfigValue(
        labeledPatternMatch[1],
        allowZwspSeparators,
      );
      const pattern = normalizeStrummingPatternValue(
        labeledPatternMatch[2],
        allowZwspSeparators,
      ).trim();

      if (label) {
        configLines.push(`  // ${label}`);
      }

      configLines.push(`  ${pattern}`);
      return;
    }

    configLines.push(`  ${trimmedLine}`);
  });

  return configLines;
}

function parseRepeatCount(repeatText) {
  const match = String(repeatText ?? '').match(/^([1-9]\d*)x$/);

  return match ? Number.parseInt(match[1], 10) : 1;
}

function createStructureToken(parsedHeader, repeatText = '') {
  const structureCode = STRUCTURE_CODE_BY_HEADER.get(parsedHeader?.header);

  if (!structureCode) {
    return '';
  }

  const repeatCount = parseRepeatCount(repeatText);

  return `${structureCode}${parsedHeader.indexText || ''}${repeatCount > 1 ? `x${repeatCount}` : ''}`;
}

function parseChordPlacements(line, allowZwspSeparators = true) {
  const source = String(line ?? '');
  const placements = [];
  let offset = 0;

  while (offset < source.length) {
    if (isSpaceLikeCharacter(source[offset], allowZwspSeparators)) {
      offset += 1;
      continue;
    }

    const match = source.slice(offset).match(CHORD_PLACEMENT_RE);
    if (!match) {
      return null;
    }

    placements.push({
      chord: match[2],
      leadingBar: Boolean(match[1]),
      position: offset,
    });
    offset += match[0].length;
  }

  return placements.length ? placements : null;
}

function mergeChordPlacementLineWithLyrics(
  chordLine,
  lyricLine,
  allowZwspSeparators = true,
) {
  const placements = parseChordPlacements(chordLine, allowZwspSeparators);

  if (!placements) {
    return null;
  }

  let mergedLine = String(lyricLine ?? '');

  placements
    .slice()
    .sort((left, right) => right.position - left.position)
    .forEach(({ chord, leadingBar, position }) => {
      if (position > mergedLine.length) {
        mergedLine = `${mergedLine}${' '.repeat(position - mergedLine.length)}`;
      }

      const insertion = `${leadingBar ? '|' : ''}[${chord}]`;
      mergedLine = `${mergedLine.slice(0, position)}${insertion}${mergedLine.slice(position)}`;
    });

  return trimLineEnd(mergedLine, allowZwspSeparators);
}

function createSectionMarkdownLines(section, allowZwspSeparators = true) {
  const bodyLines = trimBlankEdges(
    (section.bodyLines || []).map((line) =>
      trimLineEnd(line, allowZwspSeparators),
    ),
    allowZwspSeparators,
  );
  const markdownLines = [];
  const isLyricSection = LYRIC_SECTION_NAME_SET.has(
    section.parsedHeader?.header,
  );

  for (let index = 0; index < bodyLines.length; index += 1) {
    const currentLine = stripSectionIndent(bodyLines[index]);

    if (isLyricSection && index < bodyLines.length - 1) {
      const nextLine = stripSectionIndent(bodyLines[index + 1]);
      const mergedLine = mergeChordPlacementLineWithLyrics(
        currentLine,
        nextLine,
        allowZwspSeparators,
      );

      if (mergedLine !== null) {
        markdownLines.push(mergedLine);
        index += 1;
        continue;
      }
    }

    markdownLines.push(currentLine);
  }

  return trimBlankEdges(markdownLines, allowZwspSeparators);
}

function dedupeSections(sections, allowZwspSeparators = true) {
  const uniqueSections = [];
  const sectionBodiesByPartName = new Map();
  let hasConflictingDuplicates = false;

  (sections || []).forEach((section) => {
    const partName = section.parsedHeader?.partName || '';

    if (!partName) {
      return;
    }

    const bodyText = createSectionMarkdownLines(
      section,
      allowZwspSeparators,
    ).join('\n');
    const previousBodyText = sectionBodiesByPartName.get(partName);

    if (typeof previousBodyText === 'string') {
      if (previousBodyText !== bodyText) {
        hasConflictingDuplicates = true;
      }
      return;
    }

    sectionBodiesByPartName.set(partName, bodyText);
    uniqueSections.push({
      bodyText,
      partName,
    });
  });

  return {
    hasConflictingDuplicates,
    uniqueSections,
  };
}

function createStructuredSectionsFromPlainTextStructure(
  structureText,
  allowZwspSeparators = true,
) {
  const normalizedStructureText = normalizeSeparatorText(
    structureText,
    allowZwspSeparators,
  );

  if (!normalizedStructureText) {
    return [];
  }

  const segments = normalizedStructureText
    .split(/\s+-\s+/)
    .map((segment) => normalizeSeparatorText(segment, allowZwspSeparators))
    .filter(Boolean);

  if (!segments.length) {
    return [];
  }

  const structuredSections = [];

  for (const segment of segments) {
    const repeatMatch = segment.match(/^(.*?)(?:\s+\(([1-9]\d*x)\))?$/);
    const partText = normalizeSeparatorText(
      repeatMatch?.[1] || segment,
      allowZwspSeparators,
    );
    const repeatText = normalizeSeparatorText(
      repeatMatch?.[2] || '',
      allowZwspSeparators,
    );
    const parsedHeader = parseFenceHeader(partText);

    if (!parsedHeader || parsedHeader.header === 'Config') {
      return [];
    }

    structuredSections.push({
      bodyLines: [],
      inlineBody: '',
      parsedHeader,
      repeatText,
    });
  }

  return structuredSections;
}

function createFallbackSection(text, allowZwspSeparators = true) {
  const parsedHeader = parseFenceHeader('Breakdown 1');

  if (!parsedHeader) {
    return null;
  }

  return {
    bodyLines: trimBlankEdges(
      normalizeRawText(text)
        .split('\n')
        .map((line) => trimLineEnd(line, allowZwspSeparators)),
      allowZwspSeparators,
    ),
    inlineBody: '',
    parsedHeader,
    repeatText: '',
  };
}

function createSectionMarkdownBlock(partName, bodyText) {
  return bodyText
    ? [`\`\`\`ol:${partName}`, bodyText, '\`\`\`'].join('\n')
    : [`\`\`\`ol:${partName}`, '\`\`\`'].join('\n');
}

function parseOpenLyricPlainText(rawText) {
  const normalizedText = normalizeRawText(rawText);
  const allowZwspSeparators =
    shouldAllowInvisibleWordSeparators(normalizedText);
  const { headerLines, sections: parsedSections } = splitHeaderAndSections(
    normalizedText.split('\n'),
    allowZwspSeparators,
  );
  const hasStructuredHeaderSignal = headerLines.some((line) => {
    return isStructuredHeaderLine(line, allowZwspSeparators);
  });
  const header = parseHeaderBlock(headerLines, {
    allowZwspSeparators,
    preferSecondaryText: Boolean(
      parsedSections.length || hasStructuredHeaderSignal,
    ),
  });
  const structuredSections = !parsedSections.length
    ? createStructuredSectionsFromPlainTextStructure(
        header.structureText,
        allowZwspSeparators,
      )
    : [];
  const fallbackSection =
    !parsedSections.length &&
    !structuredSections.length &&
    trimSpaceLikeText(normalizedText, allowZwspSeparators)
      ? createFallbackSection(normalizedText, allowZwspSeparators)
      : null;
  const sections = parsedSections.length
    ? parsedSections
    : structuredSections.length
      ? structuredSections
      : fallbackSection
        ? [fallbackSection]
        : [];
  const structureSourceSections = parsedSections.length
    ? parsedSections
    : structuredSections;
  const structureTokens = structureSourceSections
    .map((section) =>
      createStructureToken(section.parsedHeader, section.repeatText),
    )
    .filter(Boolean);
  const { hasConflictingDuplicates, uniqueSections } = dedupeSections(
    sections,
    allowZwspSeparators,
  );
  const placeholdersUsed = [];

  const title =
    sanitizeConfigValue(header.title, allowZwspSeparators) || 'Untitled Song';
  if (!sanitizeConfigValue(header.title, allowZwspSeparators)) {
    placeholdersUsed.push('Title');
  }

  const subtitle = sanitizeConfigValue(header.subtitle, allowZwspSeparators);

  const artistSource = sanitizeConfigValue(header.artist, allowZwspSeparators);
  const artist = artistSource || DEFAULT_IMPORT_VALUES.Artist;
  if (!artistSource) {
    placeholdersUsed.push('Artist');
  }

  const keySource = sanitizeConfigValue(header.meta.Key, allowZwspSeparators);
  const key = keySource || DEFAULT_IMPORT_VALUES.Key;
  if (!keySource) {
    placeholdersUsed.push('Key');
  }

  const tempoSource = sanitizeConfigValue(
    header.meta.Tempo,
    allowZwspSeparators,
  );
  const tempo = tempoSource || DEFAULT_IMPORT_VALUES.Tempo;
  if (!tempoSource) {
    placeholdersUsed.push('Tempo');
  }

  const timeSource = sanitizeConfigValue(header.meta.Time, allowZwspSeparators);
  const time = timeSource || DEFAULT_IMPORT_VALUES.Time;
  if (!timeSource) {
    placeholdersUsed.push('Time');
  }

  const descriptionLines = trimBlankEdges(
    header.descriptionLines.map((line) =>
      sanitizeConfigValue(line, allowZwspSeparators),
    ),
    allowZwspSeparators,
  );
  const copyrightSource = sanitizeConfigValue(
    header.copyright,
    allowZwspSeparators,
  );
  const copyright = copyrightSource || DEFAULT_IMPORT_VALUES.Copyright;
  if (!copyrightSource) {
    placeholdersUsed.push('Copyright');
  }

  const theme = sanitizeConfigValue(header.theme, allowZwspSeparators);
  const genre = sanitizeConfigValue(header.genre, allowZwspSeparators);
  const style = sanitizeConfigValue(header.style, allowZwspSeparators);
  const attachmentLines = (header.attachmentLines || [])
    .map((line) => sanitizeConfigValue(line, allowZwspSeparators))
    .filter(Boolean);
  const strummingLines = normalizeStrummingConfigLines(
    header.strummingLines,
    allowZwspSeparators,
  );
  const structureValue = structureTokens.join('') || 'D1';
  if (!structureTokens.length) {
    placeholdersUsed.push('Structure');
  }

  const configLines = ['```ol:Config', `- Title: ${title}`];

  if (subtitle) {
    configLines.push(`- Subtitle: ${subtitle}`);
  }

  if (descriptionLines.length) {
    configLines.push('- Description:');
    descriptionLines.forEach((line) => {
      configLines.push(`  ${line}`);
    });
  }

  configLines.push(`- Artist: ${artist}`);
  configLines.push(`- Copyright: ${copyright}`);
  configLines.push(`- Key: ${key}`);
  configLines.push(`- Tempo: ${tempo}`);
  configLines.push(`- Time: ${time}`);

  if (theme) {
    configLines.push(`- Theme: ${theme}`);
  }

  configLines.push(`- Structure: ${structureValue}`);

  if (genre) {
    configLines.push(`- Genre: ${genre}`);
  }

  if (style) {
    configLines.push(`- Style: ${style}`);
  }

  if (attachmentLines.length) {
    configLines.push('- Attachments:');
    attachmentLines.forEach((line) => {
      configLines.push(`  ${line}`);
    });
  }

  if (strummingLines.length) {
    configLines.push('- Strumming Patterns:');
    configLines.push(...strummingLines);
  }

  configLines.push('```');

  const markdown = [
    configLines.join('\n'),
    ...uniqueSections.map(({ bodyText, partName }) => {
      return createSectionMarkdownBlock(partName, bodyText);
    }),
  ]
    .filter(Boolean)
    .join('\n\n')
    .trim();

  const recognizableSignalCount = header.signalCount + parsedSections.length;

  return {
    hasConflictingDuplicates,
    markdown,
    matchesPlainTextFormat:
      !fallbackSection &&
      !hasConflictingDuplicates &&
      (parsedSections.length > 0 ||
        structuredSections.length > 0 ||
        recognizableSignalCount >= 3),
    placeholdersUsed,
  };
}

export { parseOpenLyricPlainText };
