import {
  getCurrentValue,
  refs,
  setStatus,
  supportsClipboardCopy,
} from '../../shared.ts';
import { getOpenLyricDocumentApi } from '../../open-lyric-plugin.ts';
import {
  INVALID_MARKDOWN_CONFIRMATION_MESSAGE,
  SHARED_MARKDOWN_DATE_QUERY_PARAM,
  SHARED_MARKDOWN_FILE_NAME,
  SHARED_MARKDOWN_PASSWORD_DIALOG_MESSAGE,
  SHARED_MARKDOWN_PASSWORD_PREFIX,
  SHARED_MARKDOWN_PASSWORD_RETRY_MESSAGE,
  SHARED_MARKDOWN_QUERY_PARAM,
  SHARED_MARKDOWN_QUERY_PARAM_MAX_CHARACTERS,
  SHARED_MARKDOWN_QUERY_PARAM_WARNING_SUFFIX,
  decodeBase64Utf8,
  decryptSharedMarkdown,
  encodeBase64Utf8,
  encryptSharedMarkdown,
  formatShareDateForUrl,
  isShareEncryptionSupported,
  normalizeSharedMarkdownParam,
} from './constants.ts';

function isSharedMarkdownQueryValueTooLong(sharedValue) {
  return (
    String(sharedValue ?? '').length >
    SHARED_MARKDOWN_QUERY_PARAM_MAX_CHARACTERS
  );
}

function formatSharedMarkdownQueryValueLength(value) {
  return String(value ?? '').length.toLocaleString('en-US');
}

function formatSharedMarkdownQueryValueWarning(sharedValue) {
  const currentCharacters = formatSharedMarkdownQueryValueLength(sharedValue);
  const maxCharacters =
    SHARED_MARKDOWN_QUERY_PARAM_MAX_CHARACTERS.toLocaleString('en-US');

  return [
    `md-text is ${currentCharacters} / ${maxCharacters} characters.`,
    SHARED_MARKDOWN_QUERY_PARAM_WARNING_SUFFIX,
  ].join(' ');
}

function applyDocumentControllerShareLinkMethods(DocumentControllerClass) {
  Object.assign(DocumentControllerClass.prototype, {
    confirmOpenInvalidMarkdown(this: any) {
      return globalThis.confirm(INVALID_MARKDOWN_CONFIRMATION_MESSAGE);
    },

    shouldOpenMarkdown(this: any, markdown) {
      const documentApi = getOpenLyricDocumentApi();

      return (
        !documentApi?.checkMarkdown ||
        documentApi.checkMarkdown(markdown) ||
        this.confirmOpenInvalidMarkdown()
      );
    },

    clearSharedMarkdownParamFromUrl(this: any) {
      if (!globalThis.history?.replaceState || !globalThis.location?.href) {
        return;
      }

      const currentUrl = new URL(globalThis.location.href);

      if (!currentUrl.searchParams.has(SHARED_MARKDOWN_QUERY_PARAM)) {
        return;
      }

      currentUrl.searchParams.delete(SHARED_MARKDOWN_QUERY_PARAM);
      currentUrl.searchParams.delete(SHARED_MARKDOWN_DATE_QUERY_PARAM);
      const nextSearch = currentUrl.searchParams.toString();
      const nextUrl = `${currentUrl.pathname}${nextSearch ? `?${nextSearch}` : ''}${currentUrl.hash}`;

      globalThis.history.replaceState(globalThis.history.state, '', nextUrl);
    },

    async promptToDecryptSharedMarkdown(this: any, encryptedValue) {
      if (!isShareEncryptionSupported()) {
        setStatus('Password-protected shared links are not supported here');
        return null;
      }

      let passwordMessage = SHARED_MARKDOWN_PASSWORD_DIALOG_MESSAGE;
      let passwordTone = 'muted';

      while (true) {
        const password = await this.requestSharedLinkPassword({
          message: passwordMessage,
          tone: passwordTone,
        });

        if (password === null) {
          break;
        }

        try {
          return await decryptSharedMarkdown(encryptedValue, password);
        } catch (_error) {
          passwordMessage = SHARED_MARKDOWN_PASSWORD_RETRY_MESSAGE;
          passwordTone = 'error';
        }
      }

      setStatus('Encrypted shared link not opened');
      return null;
    },

    async resolveSharedMarkdownFromQueryValue(this: any, sharedValue) {
      if (sharedValue.startsWith(SHARED_MARKDOWN_PASSWORD_PREFIX)) {
        return this.promptToDecryptSharedMarkdown(sharedValue);
      }

      return decodeBase64Utf8(sharedValue);
    },

    async loadSharedDocumentFromQuery(this: any) {
      const searchParams = new URLSearchParams(
        globalThis.location?.search || '',
      );
      const rawParamValue = searchParams.get(SHARED_MARKDOWN_QUERY_PARAM);

      if (rawParamValue === null) {
        return {
          wasPresent: false,
          document: null,
        };
      }

      const normalizedParamValue = normalizeSharedMarkdownParam(rawParamValue);
      if (!normalizedParamValue) {
        setStatus('Shared link is empty');
        return {
          wasPresent: true,
          document: null,
        };
      }

      const sharedDocumentDate = normalizeSharedMarkdownParam(
        searchParams.get(SHARED_MARKDOWN_DATE_QUERY_PARAM),
      );

      try {
        const content =
          await this.resolveSharedMarkdownFromQueryValue(normalizedParamValue);

        if (!content) {
          return {
            wasPresent: true,
            document: null,
          };
        }

        if (!this.shouldOpenMarkdown(content)) {
          setStatus('Skipped invalid shared markdown');
          return {
            wasPresent: true,
            document: null,
          };
        }

        this.clearSharedMarkdownParamFromUrl();

        return {
          wasPresent: true,
          document: {
            content,
            fileName: SHARED_MARKDOWN_FILE_NAME,
            sharedDocumentDate,
          },
        };
      } catch (_error) {
        setStatus('Failed to open shared link');
        return {
          wasPresent: true,
          document: null,
        };
      }
    },

    buildShareLinkFromQueryValue(this: any, sharedValue) {
      const encodedMarkdown = encodeURIComponent(sharedValue);
      const encodedShareDate = encodeURIComponent(formatShareDateForUrl());
      const baseUrl = String(globalThis.location?.href)
        .replace(/[?#].*$/, '')
        .trim();

      return `${baseUrl}?${SHARED_MARKDOWN_QUERY_PARAM}="${encodedMarkdown}"&${SHARED_MARKDOWN_DATE_QUERY_PARAM}=${encodedShareDate}`;
    },

    buildShareLinkQueryValue(this: any, markdown) {
      return encodeBase64Utf8(markdown);
    },

    buildShareLink(this: any, markdown) {
      return this.buildShareLinkFromQueryValue(
        this.buildShareLinkQueryValue(markdown),
      );
    },

    async buildEncryptedShareLinkQueryValue(this: any, markdown, password) {
      return encryptSharedMarkdown(markdown, password);
    },

    async buildEncryptedShareLink(this: any, markdown, password) {
      const encryptedMarkdown = await this.buildEncryptedShareLinkQueryValue(
        markdown,
        password,
      );

      return this.buildShareLinkFromQueryValue(encryptedMarkdown);
    },

    showShareLinkLengthWarning(this: any, sharedValue) {
      this.setShareLinkMessage(
        formatSharedMarkdownQueryValueWarning(sharedValue),
        'warning',
      );
    },

    async refreshShareLink(this: any, { selectText = false } = {}) {
      if (!refs.shareLinkDialog || !refs.shareLinkTextarea) {
        return;
      }

      this.clearShareCopyButtonResetTimer();
      this.updateShareEncryptionFieldsVisibility();

      const requestId = ++this.shareLinkGenerationRequestId;
      const markdown = getCurrentValue();
      const isEncryptionEnabled = Boolean(
        refs.shareLinkEncryptionToggle?.checked,
      );

      if (!isEncryptionEnabled) {
        const sharedValue = this.buildShareLinkQueryValue(markdown);

        refs.shareLinkTextarea.placeholder = '';
        refs.shareLinkTextarea.value =
          this.buildShareLinkFromQueryValue(sharedValue);

        if (isSharedMarkdownQueryValueTooLong(sharedValue)) {
          this.showShareLinkLengthWarning(sharedValue);
        } else {
          this.setShareLinkMessage(
            'Plain link ready. Anyone with the URL can read the markdown content.',
          );
        }

        this.setShareCopyButtonState('idle', { disabled: false });

        if (selectText && !this.isShareQrModeSelected()) {
          this.focusAndSelectShareLink();
        }

        await this.refreshShareLinkQrFromCurrentValue();

        return;
      }

      const password = String(refs.shareLinkPasswordInput?.value || '');
      const confirmPassword = String(
        refs.shareLinkPasswordConfirmInput?.value || '',
      );

      if (!password || !confirmPassword) {
        refs.shareLinkTextarea.value = '';
        refs.shareLinkTextarea.placeholder =
          'Enter and confirm a password to generate the encrypted link.';
        this.setShareLinkMessage(
          'Enter and confirm a password to generate an encrypted link.',
          'info',
        );
        this.setShareCopyButtonState('idle', { disabled: true });
        await this.refreshShareLinkQrFromCurrentValue();
        return;
      }

      if (password !== confirmPassword) {
        refs.shareLinkTextarea.value = '';
        refs.shareLinkTextarea.placeholder =
          'Passwords must match before the encrypted link can be created.';
        this.setShareLinkMessage(
          'Passwords must match before the encrypted link can be created.',
          'error',
        );
        this.setShareCopyButtonState('idle', { disabled: true });
        await this.refreshShareLinkQrFromCurrentValue();
        return;
      }

      if (!isShareEncryptionSupported()) {
        refs.shareLinkTextarea.value = '';
        refs.shareLinkTextarea.placeholder =
          'Password encryption is unavailable in this browser.';
        this.setShareLinkMessage(
          'Password encryption requires the Web Crypto API in this browser.',
          'error',
        );
        this.setShareCopyButtonState('idle', { disabled: true });
        await this.refreshShareLinkQrFromCurrentValue();
        return;
      }

      refs.shareLinkTextarea.value = '';
      refs.shareLinkTextarea.placeholder = 'Encrypting the share link...';
      this.setShareLinkMessage('Encrypting the share link...', 'info');
      this.setShareCopyButtonState('idle', { disabled: true });
      await this.refreshShareLinkQrFromCurrentValue();

      try {
        const encryptedMarkdown = await this.buildEncryptedShareLinkQueryValue(
          markdown,
          password,
        );

        if (requestId !== this.shareLinkGenerationRequestId) {
          return;
        }

        const shareLink = this.buildShareLinkFromQueryValue(encryptedMarkdown);

        refs.shareLinkTextarea.placeholder = '';
        refs.shareLinkTextarea.value = shareLink;

        if (isSharedMarkdownQueryValueTooLong(encryptedMarkdown)) {
          this.showShareLinkLengthWarning(encryptedMarkdown);
        } else {
          this.setShareLinkMessage(
            'Encrypted link ready. Readers will be asked for the password.',
            'success',
          );
        }

        this.setShareCopyButtonState('idle', { disabled: false });

        if (selectText && !this.isShareQrModeSelected()) {
          this.focusAndSelectShareLink();
        }

        await this.refreshShareLinkQrFromCurrentValue();
      } catch (_error) {
        if (requestId !== this.shareLinkGenerationRequestId) {
          return;
        }

        refs.shareLinkTextarea.value = '';
        refs.shareLinkTextarea.placeholder =
          'The encrypted share link could not be generated.';
        this.setShareLinkMessage(
          'The encrypted share link could not be generated.',
          'error',
        );
        this.setShareCopyButtonState('idle', { disabled: true });
        await this.refreshShareLinkQrFromCurrentValue();
      }
    },

    async openShareDialog(this: any) {
      if (!refs.shareLinkDialog || !refs.shareLinkTextarea) {
        return;
      }

      this.prepareShareDialogState();

      if (!refs.shareLinkDialog.open) {
        refs.shareLinkDialog.showModal();
      }

      this.focusAndSelectShareLink({ selectText: false });

      await this.refreshShareLink({ selectText: false });
    },

    async copyShareLink(this: any) {
      if (!refs.shareLinkTextarea || !refs.copyShareLinkBtn) {
        return;
      }

      const shareLink = refs.shareLinkTextarea.value;
      if (!shareLink) {
        return;
      }

      if (!supportsClipboardCopy()) {
        setStatus(
          'Clipboard copy is unavailable. Copy the share link manually.',
        );
        this.focusAndSelectShareLink();
        return;
      }

      try {
        this.setShareCopyButtonState('copying');

        if (globalThis.navigator?.clipboard?.writeText) {
          await globalThis.navigator.clipboard.writeText(shareLink);
        } else {
          this.focusAndSelectShareLink();

          if (
            typeof document.execCommand !== 'function' ||
            !document.execCommand('copy')
          ) {
            throw new Error('Copy command failed.');
          }
        }

        setStatus('Share link copied');
        this.setShareCopyButtonState('success');
        this.scheduleShareCopyButtonReset();
      } catch (_error) {
        setStatus('Copy failed. Copy the share link manually.');
        this.setShareCopyButtonState('error');
        this.scheduleShareCopyButtonReset();
        this.focusAndSelectShareLink();
      }
    },
  });
}

export { applyDocumentControllerShareLinkMethods };
