import { refs, state } from './shared.ts';

const TEXT_INPUT_TYPES = new Set([
  '',
  'email',
  'number',
  'search',
  'tel',
  'text',
  'url',
]);

function getEventTargetElement(event) {
  if (event.target instanceof Element) {
    return event.target;
  }

  if (event.target instanceof Node) {
    return event.target.parentElement;
  }

  return null;
}

function isAppElement(element) {
  return element instanceof Element && Boolean(refs.app?.contains(element));
}

function isCopyableTextInput(element) {
  if (element instanceof HTMLTextAreaElement) {
    return true;
  }

  if (!(element instanceof HTMLInputElement)) {
    return false;
  }

  return TEXT_INPUT_TYPES.has(String(element.type || '').toLowerCase());
}

function getSelectedInputText(element) {
  if (!isCopyableTextInput(element)) {
    return '';
  }

  const selectionStart = Number(element.selectionStart);
  const selectionEnd = Number(element.selectionEnd);

  if (
    !Number.isFinite(selectionStart) ||
    !Number.isFinite(selectionEnd) ||
    selectionStart === selectionEnd
  ) {
    return '';
  }

  return String(element.value || '').slice(
    Math.min(selectionStart, selectionEnd),
    Math.max(selectionStart, selectionEnd),
  );
}

function getMonacoEditorSelectionText(eventTarget) {
  if (!isAppElement(eventTarget) || !refs.editorHost?.contains(eventTarget)) {
    return '';
  }

  const editor = state.editor;
  const model = editor?.getModel?.();
  const selection = editor?.getSelection?.();

  if (!model || !selection || selection.isEmpty?.()) {
    return '';
  }

  return String(model.getValueInRange(selection) || '');
}

function selectionIntersectsElement(selection, element) {
  if (!(element instanceof Element)) {
    return false;
  }

  for (let index = 0; index < selection.rangeCount; index += 1) {
    const range = selection.getRangeAt(index);

    if (range.collapsed) {
      continue;
    }

    try {
      if (range.intersectsNode(element)) {
        return true;
      }
    } catch (_error) {
      // Ignore ranges that cannot be compared against a detached element.
    }
  }

  return false;
}

function getSelectedAppText() {
  const selection = globalThis.getSelection?.();

  if (!selection || selection.isCollapsed || !selection.rangeCount) {
    return '';
  }

  if (!selectionIntersectsElement(selection, refs.app)) {
    return '';
  }

  return selection.toString();
}

function getPlainTextForCopyEvent(event) {
  const eventTarget = getEventTargetElement(event);

  if (!isAppElement(eventTarget)) {
    return getSelectedAppText();
  }

  return (
    getSelectedInputText(eventTarget) ||
    getMonacoEditorSelectionText(eventTarget) ||
    getSelectedAppText()
  );
}

function handlePlainTextCopy(event) {
  if (!event.clipboardData) {
    return;
  }

  const selectedText = getPlainTextForCopyEvent(event);

  if (!selectedText) {
    return;
  }

  event.clipboardData.clearData?.();
  event.clipboardData.setData('text/plain', selectedText);
  event.preventDefault();
  event.stopImmediatePropagation?.();
}

function installPlainTextCopyHandler() {
  document.addEventListener('copy', handlePlainTextCopy, true);
}

export { installPlainTextCopyHandler };
